function hook_output = Run_Simulink_Exchange_Hook(state_in, stage_info, exchange_options)
% Simulink-backed thermal hook for the standardized four-stage cycle.

    activate_release_path();

    if nargin < 3 || isempty(exchange_options)
        exchange_options = struct();
    end

    hook_tic = tic;
    state_std = standardize_globalxi_exchange_state(state_in);
    runtime = get_option_field(exchange_options, 'runtime', struct());
    stage_config = Resolve_Exchange_Stage_Config(stage_info, exchange_options);
    sim_params = Build_Simulink_Exchange_Params(state_std, stage_config, exchange_options);
    exchange_backend_kind = get_exchange_backend_kind(exchange_options);
    internal_node_count = get_option_field(sim_params, ...
        'solver_internal_thermal_node_count', 21);
    proxy_options = build_proxy_options(exchange_options);
    proxy_options = complete_proxy_options_from_sim_params(proxy_options, sim_params);
    strip_geometry = build_axial21_se_geometry(proxy_options, internal_node_count);
    T_r_in = extract_state_temperature(state_std);
    [T_x_in_101, directional_initialization_report] = ...
        initialize_axial21_backend(stage_config, T_r_in, runtime, internal_node_count);
    input_map_report = build_axial21_backend_input_report(T_r_in, T_x_in_101);
    directional_contract = struct( ...
        'contract_kind', 'simulink_axial_21', ...
        'stage_name', stage_config.stage_name, ...
        'node_count', internal_node_count);
    sim_params.solver_T_init_21_internal = T_x_in_101(:);
    sim_params.solver_internal_21_strip_count = numel(T_x_in_101);
    sim_params.solver_internal_21_initialization_report = directional_initialization_report;
    sim_params.solver_internal_temperature_workspace_var = 'Tx21_internal';

    model_dir = fileparts(stage_config.model_path);
    if ~isempty(model_dir) && isfolder(model_dir)
        previous_dir = pwd;
        if ~strcmpi(previous_dir, model_dir)
            cd(model_dir);
            restore_dir = onCleanup(@() cd(previous_dir));
        end
    end

    sim_setup_tic = tic;
    configure_simulink_codegen_cache(exchange_options, stage_config);
    load_system(stage_config.model_path);
    inactive_copy_logging_report = configure_inactive_copy_logging(stage_config.model_name);
    local_solver_report = configure_simscape_local_solver(stage_config.model_name, exchange_options);
    simIn = Simulink.SimulationInput(stage_config.model_name);
    simIn = simIn.setModelParameter('StopTime', num2str(stage_config.stop_time_s));
    simulation_mode_requested = normalize_simulation_mode(get_option_field(exchange_options, 'simulation_mode', 'accelerator'));
    simulation_mode = simulation_mode_requested;
    simIn = simIn.setModelParameter('SimulationMode', simulation_mode);
    simulink_solver = char(string(get_option_field(exchange_options, 'simulink_solver', '')));
    simulink_solver_reltol = get_option_field(exchange_options, 'simulink_solver_reltol', NaN);
    simulink_solver_abstol = get_option_field(exchange_options, 'simulink_solver_abstol', '');
    simulink_solver_max_step = get_option_field(exchange_options, 'simulink_solver_max_step', '');
    simulink_solver_min_step = get_option_field(exchange_options, 'simulink_solver_min_step', '');
    simulink_solver_initial_step = get_option_field(exchange_options, 'simulink_solver_initial_step', '');
    simulink_zero_cross = get_option_field(exchange_options, 'simulink_zero_cross', '');
    if ~isempty(simulink_solver)
        simIn = simIn.setModelParameter('Solver', simulink_solver);
    end
    if isnumeric(simulink_solver_reltol) && isscalar(simulink_solver_reltol) && isfinite(simulink_solver_reltol)
        simIn = simIn.setModelParameter('RelTol', num2str(simulink_solver_reltol));
    end
    if (ischar(simulink_solver_abstol) || isstring(simulink_solver_abstol)) && ~isempty(char(string(simulink_solver_abstol)))
        simIn = simIn.setModelParameter('AbsTol', char(string(simulink_solver_abstol)));
    elseif isnumeric(simulink_solver_abstol) && isscalar(simulink_solver_abstol) && isfinite(simulink_solver_abstol)
        simIn = simIn.setModelParameter('AbsTol', num2str(simulink_solver_abstol));
    end
    if (ischar(simulink_solver_max_step) || isstring(simulink_solver_max_step)) && ~isempty(char(string(simulink_solver_max_step)))
        simIn = simIn.setModelParameter('MaxStep', char(string(simulink_solver_max_step)));
    elseif isnumeric(simulink_solver_max_step) && isscalar(simulink_solver_max_step) && isfinite(simulink_solver_max_step)
        simIn = simIn.setModelParameter('MaxStep', num2str(simulink_solver_max_step));
    end
    if (ischar(simulink_solver_min_step) || isstring(simulink_solver_min_step)) && ~isempty(char(string(simulink_solver_min_step)))
        simIn = simIn.setModelParameter('MinStep', char(string(simulink_solver_min_step)));
    elseif isnumeric(simulink_solver_min_step) && isscalar(simulink_solver_min_step) && isfinite(simulink_solver_min_step)
        simIn = simIn.setModelParameter('MinStep', num2str(simulink_solver_min_step));
    end
    if (ischar(simulink_solver_initial_step) || isstring(simulink_solver_initial_step)) && ~isempty(char(string(simulink_solver_initial_step)))
        simIn = simIn.setModelParameter('InitialStep', char(string(simulink_solver_initial_step)));
    elseif isnumeric(simulink_solver_initial_step) && isscalar(simulink_solver_initial_step) && isfinite(simulink_solver_initial_step)
        simIn = simIn.setModelParameter('InitialStep', num2str(simulink_solver_initial_step));
    end
    if (ischar(simulink_zero_cross) || isstring(simulink_zero_cross)) && ~isempty(char(string(simulink_zero_cross)))
        simIn = simIn.setModelParameter('ZeroCross', char(string(simulink_zero_cross)));
    end
    fast_restart_requested = logical(get_option_field(exchange_options, 'use_fast_restart', false));
    fast_restart_effective = fast_restart_requested && ...
        logical(get_option_field(exchange_options, 'allow_fast_restart_with_nontunable_initial_conditions', false));
    fast_restart_disabled_reason = '';
    if fast_restart_requested && ~fast_restart_effective
        fast_restart_disabled_reason = 'disabled_for_simscape_nontunable_initial_conditions';
    end
    if fast_restart_effective
        simIn = simIn.setModelParameter('FastRestart', 'on');
    end
    simIn = apply_sim_params_to_simulation_input(simIn, sim_params);
    [simIn, r25_simstate_test_report] = configure_r25_simstate_test(simIn, exchange_options);
    simstate_chain_report = disabled_simstate_chain_report();
    sim_setup_walltime_s = toc(sim_setup_tic);

    sim_tic = tic;
    simulation_mode_fallback_used = false;
    simulation_mode_fallback_reason = '';
    try
        if logical(get_option_field(exchange_options, 'r24_mock_force_sim_error_before_sim', false))
            error('Run_Simulink_Exchange_Hook:R24MockSimError', ...
                'R24 mock forced Simulink exception before sim() for reused fallback verification.');
        end
        [simOut, sim_retry_report, sim_params] = run_simulation_with_init_retry( ...
            simIn, stage_config, exchange_options, sim_params);
    catch sim_error
        if strcmp(simulation_mode, 'accelerator') && logical(get_option_field(exchange_options, ...
                'allow_simulation_mode_fallback_to_normal', true))
            simulation_mode_fallback_used = true;
            simulation_mode_fallback_reason = sim_error.message;
            simulation_mode = 'normal';
            simIn = simIn.setModelParameter('SimulationMode', simulation_mode);
            try
                [simOut, sim_retry_report, sim_params] = run_simulation_with_init_retry( ...
                    simIn, stage_config, exchange_options, sim_params);
            catch normal_error
                reuse = build_stage_result_reuse_output( ...
                    state_std, stage_config, runtime, exchange_options, sim_params, normal_error, hook_tic, ...
                    simulation_mode, simulation_mode_requested, simulation_mode_fallback_used, ...
                    simulation_mode_fallback_reason, local_solver_report);
                if reuse.should_reuse
                    hook_output = reuse.hook_output;
                    return;
                end
                sim_error = addCause(normal_error, sim_error);
                failure_diagnostics = save_simulink_failure_diagnostics( ...
                    sim_error, state_std, stage_config, sim_params, strip_geometry, ...
                    T_r_in, T_x_in_101, runtime);
                wrapped_error = MException('Run_Simulink_Exchange_Hook:SimulinkSimulationFailed', ...
                    ['Simulink simulation failed for %s at cycle %d stage %d after accelerator fallback. ', ...
                    'failure_snapshot_mat=%s; failure_error_txt=%s; original_identifier=%s; original_message=%s'], ...
                    stage_config.stage_name, get_option_field(runtime, 'cycle_index', 0), ...
                    get_option_field(runtime, 'stage_index', 0), ...
                    failure_diagnostics.snapshot_mat_path, failure_diagnostics.error_txt_path, ...
                    sim_error.identifier, sim_error.message);
                wrapped_error = addCause(wrapped_error, sim_error);
                throw(wrapped_error);
            end
        else
        reuse = build_stage_result_reuse_output( ...
            state_std, stage_config, runtime, exchange_options, sim_params, sim_error, hook_tic, ...
            simulation_mode, simulation_mode_requested, simulation_mode_fallback_used, ...
            simulation_mode_fallback_reason, local_solver_report);
        if reuse.should_reuse
            hook_output = reuse.hook_output;
            return;
        end
        failure_diagnostics = save_simulink_failure_diagnostics( ...
            sim_error, state_std, stage_config, sim_params, strip_geometry, ...
            T_r_in, T_x_in_101, runtime);
        wrapped_error = MException('Run_Simulink_Exchange_Hook:SimulinkSimulationFailed', ...
            ['Simulink simulation failed for %s at cycle %d stage %d. ', ...
            'failure_snapshot_mat=%s; failure_error_txt=%s; original_identifier=%s; original_message=%s'], ...
            stage_config.stage_name, get_option_field(runtime, 'cycle_index', 0), ...
            get_option_field(runtime, 'stage_index', 0), ...
            failure_diagnostics.snapshot_mat_path, failure_diagnostics.error_txt_path, ...
            sim_error.identifier, sim_error.message);
        wrapped_error = addCause(wrapped_error, sim_error);
        throw(wrapped_error);
        end
    end
    simulink_walltime_s = toc(sim_tic);
    profiler_export_report = export_simulink_profiler_top30_if_requested( ...
        simOut, exchange_options, stage_config);
    [r25_simstate_test_report, r25_simstate_final_state] = finalize_r25_simstate_test( ...
        simOut, r25_simstate_test_report);
    simstate_final_report = disabled_simstate_final_report();

    [raw_temperature_var_name, raw_temperature_expected_count] = ...
        resolve_raw_temperature_log_contract(exchange_backend_kind, sim_params);
    Tx51_raw = extract_terminal_temperature(simOut, raw_temperature_var_name, raw_temperature_expected_count);
    hot_sink_temp_out = extract_terminal_scalar(simOut, {'hot_sink_temp_out', 'hot_source_out'});
    cold_sink_temp_out = extract_terminal_scalar(simOut, {'cold_sink_temp_out'});
    Qdot_cold_sink_mass_to_pipe_terminal_W = extract_terminal_scalar(simOut, ...
        {'Qdot_cold_sink_mass_to_hx_pipe_W', 'Qdot_cold_sink_mass_to_pipe_W'}, NaN);
    cold_sink_pipe_thermal_port_temp_out = extract_terminal_scalar(simOut, ...
        {'cold_sink_hx_pipe_thermal_port_temp_out', 'cold_sink_pipe_thermal_port_temp_out'}, NaN);
    cold_return_pipe_thermal_port_temp_out = extract_terminal_scalar(simOut, ...
        {'cold_return_pipe_thermal_port_temp_out'}, NaN);
    cold_load_temp_out = extract_terminal_scalar(simOut, {'cold_load_temp_out', 'chip_temp_out'});
    chip_temp_out = cold_load_temp_out; % Deprecated compatibility alias.
    hot_buffer_temp_out = extract_terminal_scalar(simOut, {'probe_root_hot_buffer_fluid_T_K', 'hot_buffer_temp_out'});
    cold_buffer_temp_out = extract_terminal_scalar(simOut, {'probe_root_cold_buffer_fluid_T_K', 'cold_buffer_temp_out'});
    hot_buffer_sample_stats = extract_logged_endpoint_stats(simOut, ...
        {'probe_root_hot_buffer_fluid_T_K', 'hot_buffer_temp_out'}, hot_buffer_temp_out);
    cold_buffer_sample_stats = extract_logged_endpoint_stats(simOut, ...
        {'probe_root_cold_buffer_fluid_T_K', 'cold_buffer_temp_out'}, cold_buffer_temp_out);
    probe_root_hot_buffer_fluid_T_K = hot_buffer_temp_out;
    probe_root_cold_buffer_fluid_T_K = cold_buffer_temp_out;
    probe_sma_stage2_port1_v1_side_T_K = extract_terminal_scalar(simOut, ...
        {'probe_sma_stage2_port1_v1_side_T_K', 'sma_hold_inlet_fluid_temp_out'});
    probe_sma_stage2_port2_v3_side_T_K = extract_terminal_scalar(simOut, ...
        {'probe_sma_stage2_port2_v3_side_T_K', 'sma_hold_outlet_fluid_temp_out'});
    probe_sma_stage4_port3_v4_side_T_K = extract_terminal_scalar(simOut, ...
        {'probe_sma_stage4_port3_v4_side_T_K', 'sma_cooldown_inlet_fluid_temp_out'});
    probe_sma_stage4_port4_v6_side_T_K = extract_terminal_scalar(simOut, ...
        {'probe_sma_stage4_port4_v6_side_T_K', 'sma_cooldown_outlet_fluid_temp_out'});
    probe_hot_hx_port1_v3_side_T_K = extract_terminal_scalar(simOut, ...
        {'probe_hot_hx_port1_v3_side_T_K', 'hot_hx_inlet_fluid_temp_out', 'hot_subsystem_inlet_fluid_temp_out'});
    probe_hot_hx_port2_v2_return_side_T_K = extract_terminal_scalar(simOut, ...
        {'probe_hot_hx_port2_v2_return_side_T_K', 'hot_hx_outlet_fluid_temp_out', 'hot_subsystem_outlet_fluid_temp_out'});
    probe_chip_pipe_port_conn2_v6_sma_side_T_K = extract_terminal_scalar(simOut, ...
        {'probe_chip_pipe_port_conn2_v6_sma_side_T_K', 'chip_inlet_fluid_temp_out', ...
        'cold_subsystem_inlet_fluid_temp_out', 'probe_transit_pipe_inlet_T_K'});
    probe_chip_to_cold_junction_T_K = extract_terminal_scalar(simOut, ...
        {'probe_chip_to_cold_junction_T_K', 'chip_outlet_fluid_temp_out'});
    probe_cold_hx_port_conn1_v5_return_side_T_K = extract_terminal_scalar(simOut, ...
        {'probe_cold_hx_port_conn1_v5_return_side_T_K', 'cold_return_outlet_fluid_temp_out', 'cold_subsystem_outlet_fluid_temp_out'});
    cold_hx_outlet_measured_T_K = extract_terminal_scalar(simOut, ...
        {'cold_hx_outlet_fluid_temp_out', 'probe_chip_to_cold_junction_T_K', 'chip_outlet_fluid_temp_out'}, ...
        probe_chip_to_cold_junction_T_K);
    cold_return_inlet_fluid_temp_out = extract_terminal_scalar(simOut, ...
        {'cold_return_inlet_fluid_temp_out', 'cold_hx_outlet_fluid_temp_out'}, cold_hx_outlet_measured_T_K);
    % Pre-CHEX boundary temperature. R68 reads the post-transit junction;
    % R69 has no transit pipe, so the same signal is the direct Conn2/CHEX
    % inlet boundary.
    probe_transit_pipe_outlet_T_K = extract_terminal_scalar(simOut, ...
        {'probe_transit_pipe_outlet_T_K', 'transit_to_chex_fluid_temp_out', 'cold_hx_inlet_fluid_temp_out'}, ...
        probe_chip_pipe_port_conn2_v6_sma_side_T_K);
    probe_v1_cold_inlet_cold_buffer_side_T_K = extract_terminal_scalar(simOut, {'probe_v1_cold_inlet_cold_buffer_side_T_K'}, NaN);
    probe_v1_cold_inlet_sma_side_T_K = extract_terminal_scalar(simOut, {'probe_v1_cold_inlet_sma_side_T_K'}, NaN);
    probe_v3_sma_to_hot_sma_side_T_K = extract_terminal_scalar(simOut, {'probe_v3_sma_to_hot_sma_side_T_K'}, NaN);
    probe_v3_sma_to_hot_hot_hx_side_T_K = extract_terminal_scalar(simOut, {'probe_v3_sma_to_hot_hot_hx_side_T_K'}, NaN);
    probe_v4_hot_inlet_hot_buffer_side_T_K = extract_terminal_scalar(simOut, {'probe_v4_hot_inlet_hot_buffer_side_T_K'}, NaN);
    probe_v4_hot_inlet_sma_side_T_K = extract_terminal_scalar(simOut, {'probe_v4_hot_inlet_sma_side_T_K'}, NaN);
    probe_v6_sma_to_chip_sma_side_T_K = extract_terminal_scalar(simOut, {'probe_v6_sma_to_chip_sma_side_T_K'}, NaN);
    probe_v6_sma_to_chip_chip_side_T_K = extract_terminal_scalar(simOut, {'probe_v6_sma_to_chip_chip_side_T_K'}, NaN);
    probe_hot_sink_solid_T_K = hot_sink_temp_out;
    probe_cold_sink_solid_T_K = cold_sink_temp_out;
    probe_chip_solid_T_K = chip_temp_out;
    probe_cold_load_solid_T_K = cold_load_temp_out;
    hot_hx_inlet_fluid_temp_out = probe_hot_hx_port1_v3_side_T_K;
    hot_hx_outlet_fluid_temp_out = probe_hot_hx_port2_v2_return_side_T_K;
    chip_inlet_fluid_temp_out = probe_chip_pipe_port_conn2_v6_sma_side_T_K;
    chip_outlet_fluid_temp_out = probe_chip_to_cold_junction_T_K;
    cold_hx_inlet_fluid_temp_out = probe_transit_pipe_outlet_T_K;
    cold_hx_outlet_fluid_temp_out = cold_hx_outlet_measured_T_K;
    cold_return_outlet_fluid_temp_out = probe_cold_hx_port_conn1_v5_return_side_T_K;
    sma_hold_inlet_fluid_temp_out = probe_sma_stage2_port1_v1_side_T_K;
    sma_hold_outlet_fluid_temp_out = probe_sma_stage2_port2_v3_side_T_K;
    sma_cooldown_inlet_fluid_temp_out = probe_sma_stage4_port3_v4_side_T_K;
    sma_cooldown_outlet_fluid_temp_out = probe_sma_stage4_port4_v6_side_T_K;
    mass_flow_v1_cold_inlet_kgps = extract_terminal_scalar(simOut, {'mass_flow_v1_cold_inlet_kgps'});
    mass_flow_v3_sma_to_hot_kgps = extract_terminal_scalar(simOut, {'mass_flow_v3_sma_to_hot_kgps'});
    mass_flow_v4_hot_inlet_kgps = extract_terminal_scalar(simOut, {'mass_flow_v4_hot_inlet_kgps'});
    mass_flow_v6_sma_to_chip_cold_kgps = extract_terminal_scalar(simOut, {'mass_flow_v6_sma_to_chip_cold_kgps'});
    observability = build_observability_snapshot(stage_config, sim_params, ...
        hot_sink_temp_out, cold_sink_temp_out, chip_temp_out, ...
        hot_buffer_temp_out, cold_buffer_temp_out, ...
        hot_hx_inlet_fluid_temp_out, hot_hx_outlet_fluid_temp_out, ...
        chip_inlet_fluid_temp_out, chip_outlet_fluid_temp_out, ...
        cold_hx_inlet_fluid_temp_out, cold_hx_outlet_fluid_temp_out, ...
        sma_hold_inlet_fluid_temp_out, sma_hold_outlet_fluid_temp_out, ...
        sma_cooldown_inlet_fluid_temp_out, sma_cooldown_outlet_fluid_temp_out, ...
        probe_v1_cold_inlet_cold_buffer_side_T_K, probe_v1_cold_inlet_sma_side_T_K, ...
        probe_v3_sma_to_hot_sma_side_T_K, probe_v3_sma_to_hot_hot_hx_side_T_K, ...
        probe_v4_hot_inlet_hot_buffer_side_T_K, probe_v4_hot_inlet_sma_side_T_K, ...
        probe_v6_sma_to_chip_sma_side_T_K, probe_v6_sma_to_chip_chip_side_T_K, ...
        mass_flow_v1_cold_inlet_kgps, mass_flow_v3_sma_to_hot_kgps, ...
        mass_flow_v4_hot_inlet_kgps, mass_flow_v6_sma_to_chip_cold_kgps);
    % Augment observability with cold endpoint probes. R69 intentionally has no
    % transit or cold return pipe; legacy field names remain diagnostic aliases
    % only so older report code can read the direct CHEX inlet/outlet.
    observability.transit_to_chex_fluid_temp_out = probe_transit_pipe_outlet_T_K;
    observability.transit_pipe_inlet_fluid_temp_out = chip_inlet_fluid_temp_out;
    observability.transit_pipe_outlet_fluid_temp_out = probe_transit_pipe_outlet_T_K;
    observability.cold_return_inlet_fluid_temp_out = cold_return_inlet_fluid_temp_out;
    observability.cold_return_outlet_fluid_temp_out = cold_return_outlet_fluid_temp_out;
    observability.Qdot_cold_sink_mass_to_pipe_terminal_W = Qdot_cold_sink_mass_to_pipe_terminal_W;
    observability.cold_sink_pipe_thermal_port_temp_out = cold_sink_pipe_thermal_port_temp_out;
    observability.cold_return_pipe_thermal_port_temp_out = cold_return_pipe_thermal_port_temp_out;
    cold_end_topology_mode = lower(strtrim(char(string(get_option_field(sim_params, ...
        'cold_end_topology_mode', 'r69_symmetric')))));
    if strcmp(cold_end_topology_mode, 'r69_symmetric')
        observability.Qdot_cold_sink_mass_to_pipe_semantics = ...
            ['R69 probe is in series between ColdSinkMass and ColdSinkFluidLink into single ColdSinkPipe/CHEX. ', ...
            'Positive value means heat leaves ColdSinkMass and enters the CHEX pipe fluid.'];
        observability.cold_sink_pipe_thermal_port_temp_semantics = ...
            'R69 single ColdSinkPipe thermal conserving port connected to ColdSinkFluidLink and ColdSinkMass.';
        observability.cold_return_pipe_thermal_port_temp_semantics = ...
            'R69 has no ColdSinkReturnPipe; this field is intentionally NaN.';
    else
        observability.Qdot_cold_sink_mass_to_pipe_semantics = ...
            ['Probe is in series between ColdSinkMass and ColdSinkFluidLink into ColdSinkHXPipe. ', ...
            'Positive value means heat leaves ColdSinkMass and enters the HX pipe fluid.'];
        observability.cold_sink_pipe_thermal_port_temp_semantics = ...
            'Thermal conserving port of ColdSinkHXPipe connected to ColdSinkFluidLink and ColdSinkMass; ColdSinkReturnPipe is adiabatic.';
        observability.cold_return_pipe_thermal_port_temp_semantics = ...
            'ColdSinkReturnPipe thermal conserving port is intentionally not instrumented in R68 because probing it made the adiabatic return boundary stiff; use fluid inlet/outlet probes for return storage audit.';
    end
    observability.hot_buffer_temp_out_first_sample = hot_buffer_sample_stats.first;
    observability.hot_buffer_temp_out_last_sample = hot_buffer_sample_stats.last;
    observability.hot_buffer_temp_out_min_sample = hot_buffer_sample_stats.min;
    observability.hot_buffer_temp_out_max_sample = hot_buffer_sample_stats.max;
    observability.hot_buffer_temp_out_sample_count = hot_buffer_sample_stats.count;
    observability.cold_buffer_temp_out_first_sample = cold_buffer_sample_stats.first;
    observability.cold_buffer_temp_out_last_sample = cold_buffer_sample_stats.last;
    observability.cold_buffer_temp_out_min_sample = cold_buffer_sample_stats.min;
    observability.cold_buffer_temp_out_max_sample = cold_buffer_sample_stats.max;
    observability.cold_buffer_temp_out_sample_count = cold_buffer_sample_stats.count;
    probe_timeseries = build_exchange_probe_timeseries( ...
        simOut, stage_info, stage_config, sim_params, runtime, ...
        raw_temperature_var_name, raw_temperature_expected_count, observability);
    observability = merge_flat_struct(observability, probe_timeseries);
    raw_observability = build_simulink_raw_namespace(observability);
    active_flow_audit = build_active_flow_audit(simOut, stage_config, sim_params, observability);
    pressure_retry = maybe_retry_actual_flush_pressure_control( ...
        state_in, stage_info, exchange_options, stage_config, sim_params, ...
        active_flow_audit, simulink_walltime_s);
    if pressure_retry.should_retry
        hook_output = Run_Simulink_Exchange_Hook( ...
            state_in, stage_info, pressure_retry.exchange_options);
        return;
    end
    active_flow_audit = merge_flat_struct(active_flow_audit, pressure_retry.pressure_control_report);
    pump_work_audit = build_pump_work_audit(stage_config, sim_params, active_flow_audit);

    backend_result = run_exchange_temperature_backend( ...
        exchange_backend_kind, stage_config, sim_params, proxy_options, strip_geometry, ...
        T_r_in, T_x_in_101, Tx51_raw, directional_contract, directional_initialization_report);
    T_x_out_101 = backend_result.T_x_out_101;
    T_r_compressed = backend_result.T_r_compressed;
    compression_report = backend_result.compression_report;
    output_map_report = backend_result.output_map_report;
    energy_audit = build_energy_audit(sim_params, observability, stage_config, strip_geometry, ...
        T_r_in, T_x_in_101, T_x_out_101, T_r_compressed, simOut, active_flow_audit);
    active_flow_audit = attach_closed_branch_leakage_heat_audit( ...
        active_flow_audit, observability, energy_audit, sim_params, stage_config);
    active_flow_audit = attach_pressure_retry_transport_diagnostics(active_flow_audit, energy_audit);
    r28_cold_side_snapshot = build_r28_cold_side_snapshot( ...
        stage_config, sim_params, runtime, observability, energy_audit, ...
        active_flow_audit, exchange_options);

    if stage_config.apply_temperature_back_to_state
        state_out = apply_temperature_to_globalxi_state(state_std, T_r_compressed);
        bridge_plan = build_disabled_bridge_plan(stage_config, T_r_in);
        reconcile_report = build_globalxi_temperature_writeback_report( ...
            stage_config, state_std, T_r_in, T_r_compressed);
    else
        state_out = state_std;
        bridge_plan = build_disabled_bridge_plan(stage_config, T_r_in);
        T_r_compressed = T_r_in;
        T_x_out_101 = T_x_in_101;
        Tx51_raw = T_r_in;
        compression_report = build_noop_compression_report(T_r_in, proxy_options, exchange_backend_kind);
        reconcile_report = build_noop_reconcile_report(stage_config, state_std, T_r_in);
        backend_result.T_x_out_101 = T_x_in_101;
        backend_result.T_r_compressed = T_r_in;
    end

    checkpoint_path = '';
    checkpoint_walltime_s = 0.0;
    if isfield(runtime, 'save_checkpoints') && runtime.save_checkpoints
        checkpoint_tic = tic;
        timing_info = struct( ...
            'sim_setup_walltime_s', sim_setup_walltime_s, ...
            'simulink_walltime_s', simulink_walltime_s, ...
            'simulation_mode_requested', simulation_mode_requested, ...
            'simulation_mode_fallback_used', simulation_mode_fallback_used, ...
            'simulation_mode_fallback_reason', simulation_mode_fallback_reason, ...
            'simulink_solver', simulink_solver, ...
            'simulink_solver_reltol', simulink_solver_reltol, ...
            'simulink_solver_abstol', simulink_solver_abstol, ...
            'simulink_solver_max_step', simulink_solver_max_step, ...
            'simulink_solver_min_step', simulink_solver_min_step, ...
            'simulink_solver_initial_step', simulink_solver_initial_step, ...
            'simulink_zero_cross', simulink_zero_cross, ...
            'simscape_local_solver_enabled', local_solver_report.enabled, ...
            'simscape_local_solver_choice', local_solver_report.choice, ...
            'simscape_local_solver_sample_time', local_solver_report.sample_time, ...
            'simscape_local_solver_block_count', local_solver_report.block_count, ...
            'simscape_local_solver_status', local_solver_report.status, ...
            'simulink_simstate_chain_enabled', simstate_chain_report.enabled, ...
            'simulink_simstate_loaded', simstate_chain_report.loaded, ...
            'simulink_simstate_source_stage_index', simstate_chain_report.source_stage_index, ...
            'simulink_simstate_sma_injection_status', simstate_chain_report.sma_injection_status, ...
            'simulink_simstate_final_saved', simstate_final_report.saved, ...
            'simulink_simstate_final_class', simstate_final_report.final_state_class, ...
            'simulink_simstate_error_message', simstate_chain_report.error_message, ...
            'simulink_profiler_export_success', profiler_export_report.success, ...
            'simulink_profiler_top30_csv_path', profiler_export_report.csv_path, ...
            'simulink_profiler_row_count', profiler_export_report.row_count, ...
            'simulink_profiler_error_message', profiler_export_report.error_message, ...
            'r25_simstate_test_save_enabled', r25_simstate_test_report.save_enabled, ...
            'r25_simstate_test_load_enabled', r25_simstate_test_report.load_enabled, ...
            'r25_simstate_test_loaded', r25_simstate_test_report.loaded, ...
            'r25_simstate_test_final_saved', r25_simstate_test_report.final_saved, ...
            'r25_simstate_test_final_class', r25_simstate_test_report.final_class, ...
            'r25_simstate_test_error_message', r25_simstate_test_report.error_message, ...
            'simulink_init_retry_attempt_count', get_option_field(sim_retry_report, 'attempt_count', 1), ...
            'simulink_init_retry_used', get_option_field(sim_retry_report, 'retry_used', false), ...
            'simulink_init_adaptive_fallback_used', get_option_field(sim_retry_report, 'adaptive_fallback_used', false), ...
            'simulink_init_successful_attempt_index', get_option_field(sim_retry_report, 'successful_attempt_index', NaN), ...
            'simulink_init_successful_closed_valve_opening', get_option_field(sim_retry_report, 'successful_closed_valve_opening', NaN), ...
            'simulink_init_successful_ramp_s', get_option_field(sim_retry_report, 'successful_ramp_s', NaN), ...
            'simulink_init_successful_startup_profile', get_option_field(sim_retry_report, 'successful_startup_profile', ''), ...
            'hook_walltime_pre_checkpoint_s', toc(hook_tic), ...
            'checkpoint_walltime_s', NaN, ...
            'hook_walltime_s', NaN);
        checkpoint_payload = build_checkpoint_payload( ...
            state_std, stage_config, sim_params, strip_geometry, proxy_options, exchange_backend_kind, ...
            T_r_in, T_x_in_101, Tx51_raw, T_x_out_101, T_r_compressed, ...
            input_map_report, output_map_report, compression_report, directional_contract, ...
            directional_initialization_report, backend_result, bridge_plan, reconcile_report, ...
            observability, raw_observability, active_flow_audit, pump_work_audit, energy_audit, state_out, simOut, runtime, ...
            simulation_mode, fast_restart_requested, fast_restart_effective, fast_restart_disabled_reason, timing_info);
        checkpoint_path = save_stage_checkpoint_payload(checkpoint_payload, runtime);
        checkpoint_walltime_s = toc(checkpoint_tic);
    end
    runtime_out = update_runtime(runtime, stage_info, stage_config, ...
        observability, checkpoint_path, bridge_plan, energy_audit, sim_params, T_x_out_101, active_flow_audit);
    buffer_handoff_audit = build_buffer_handoff_audit( ...
        runtime, runtime_out, stage_config, sim_params, observability);
    energy_audit.hot_side_state_sync_policy = get_option_field(runtime_out, 'hot_side_state_sync_policy', ...
        get_option_field(energy_audit, 'hot_side_state_sync_policy', ''));
    energy_audit.cold_side_state_sync_policy = get_option_field(runtime_out, 'cold_side_state_sync_policy', ...
        get_option_field(energy_audit, 'cold_side_state_sync_policy', ''));
    hook_walltime_s = toc(hook_tic);

    hook_report = struct( ...
