        'bridge_latest_checkpoint_path', '', ...
        'bridge_execution_report', struct(), ...
        'proxy_input_map_report', summarize_map_report(input_map_report), ...
        'proxy_output_map_report', summarize_map_report(output_map_report), ...
        'compression_report', summarize_compression_report(compression_report), ...
        'reconcile_report', summarize_reconcile_report(reconcile_report), ...
        'energy_audit_ok', energy_audit.energy_audit_ok, ...
        'energy_audit_status', energy_audit.energy_audit_status, ...
        'energy_audit_scope', energy_audit.energy_audit_scope, ...
        'sma_htf_energy_audit_ok', energy_audit.sma_htf_energy_audit_ok, ...
        'system_energy_audit_ok', energy_audit.system_energy_audit_ok, ...
        'system_energy_residual_J', energy_audit.system_energy_residual_J, ...
