function reuse = build_stage_result_reuse_output( ...
        state_std, stage_config, runtime, exchange_options, sim_params, sim_error, hook_tic, ...
        simulation_mode, simulation_mode_requested, simulation_mode_fallback_used, ...
        simulation_mode_fallback_reason, local_solver_report)
    reuse = struct('should_reuse', false, 'hook_output', struct());
    if ~logical(get_option_field(exchange_options, 'enable_stage_result_reuse_on_sim_failure', true))
        return;
    end

    previous = select_previous_stage_reuse_record(runtime, stage_config);
    if isempty(previous)
        return;
    end

    T_out = get_option_field(previous, 'T_out_51', []);
    if ~(isnumeric(T_out) && numel(T_out) == numel(extract_state_temperature(state_std)) && ...
            all(isfinite(T_out(:))))
        T_out = extract_state_temperature(state_std);
    end
    T_out = T_out(:);
    state_out = apply_temperature_to_globalxi_state(state_std, T_out);

    previous_report = get_option_field(previous, 'hook_report', struct());
    if isempty(previous_report) || ~isstruct(previous_report)
        previous_report = struct();
    end
    runtime_out = get_option_field(previous, 'runtime_out', runtime);
    if isempty(runtime_out) || ~isstruct(runtime_out)
        runtime_out = runtime;
    end

    current_cycle = get_option_field(runtime, 'cycle_index', NaN);
    current_stage = get_option_field(runtime, 'stage_index', get_option_field(stage_config, 'stage_index', NaN));
    hook_walltime_s = toc(hook_tic);
    hook_report = previous_report;
    hook_report.handler = 'Run_Simulink_Exchange_Hook';
    hook_report.stage_name = stage_config.stage_name;
    hook_report.cycle_index = current_cycle;
    hook_report.stage_index = current_stage;
    hook_report.ok = true;
    hook_report.stage_result_reused_from_previous_cycle = true;
    hook_report.stage_result_diagnostic_only_not_for_publication = true;
    hook_report.stage_result_reuse_source_cycle_index = get_option_field(previous, 'cycle_index', NaN);
    hook_report.stage_result_reuse_source_stage_index = get_option_field(previous, 'stage_index', NaN);
    hook_report.stage_result_reuse_source_stage_name = get_option_field(previous, 'stage_name', '');
    hook_report.stage_result_reuse_error_identifier = sim_error.identifier;
    hook_report.stage_result_reuse_error_message = sim_error.message;
    hook_report.stage_result_reuse_policy = 'previous_cycle_same_stage_on_sim_exception_v1';
    hook_report.simulation_mode = simulation_mode;
    hook_report.simulation_mode_requested = simulation_mode_requested;
    hook_report.simulation_mode_fallback_used = simulation_mode_fallback_used;
    hook_report.simulation_mode_fallback_reason = simulation_mode_fallback_reason;
    hook_report.simscape_local_solver_enabled = get_option_field(local_solver_report, 'enabled', false);
    hook_report.simscape_local_solver_choice = get_option_field(local_solver_report, 'choice', '');
    hook_report.simscape_local_solver_sample_time = get_option_field(local_solver_report, 'sample_time', '');
    hook_report.simscape_local_solver_block_count = get_option_field(local_solver_report, 'block_count', 0);
    hook_report.simscape_local_solver_status = get_option_field(local_solver_report, 'status', '');
    hook_report.sim_setup_walltime_s = 0;
    hook_report.simulink_walltime_s = 0;
    hook_report.hook_walltime_s = hook_walltime_s;
    hook_report.exchange_walltime_s = hook_walltime_s;
    hook_report.checkpoint_path = '';
    hook_report.failure_reason = '';
    hook_report.pressure_control_compensation_used = false;
    hook_report.pressure_control_compensation_source = '';
    hook_report.pressure_control_compensation_pressure_MPa = NaN;
    hook_report.stage_result_reused_note = ...
        'Diagnostic reused stage result after Simulink exception; not for publication physics.';

    runtime_out.cycle_index = current_cycle;
    runtime_out.stage_index = current_stage;
    runtime_out.last_stage_name = stage_config.stage_name;
    runtime_out.stage_result_reused_from_previous_cycle = true;
    runtime_out.last_stage_result_reuse_error_identifier = sim_error.identifier;
    runtime_out.last_stage_result_reuse_error_message = sim_error.message;
    runtime_out.last_stage_result_reuse_source_cycle_index = ...
        get_option_field(previous, 'cycle_index', NaN);
    runtime_out.last_stage_result_reuse_source_stage_index = ...
        get_option_field(previous, 'stage_index', NaN);
    runtime_out = store_reusable_stage_record(runtime_out, runtime, stage_config, hook_report, T_out, state_out);

    reuse.should_reuse = true;
    reuse.hook_output = struct( ...
        'T_out', T_out, ...
        'state_out', state_out, ...
        'hook_report', hook_report, ...
        'runtime_out', runtime_out);
end

function previous = select_previous_stage_reuse_record(runtime, stage_config)
    previous = [];
    if isempty(runtime) || ~isstruct(runtime)
        return;
    end
    stage_index = get_option_field(runtime, 'stage_index', get_option_field(stage_config, 'stage_index', NaN));
    if ~isfinite(stage_index)
        return;
    end
    field_name = reusable_stage_field_name(stage_index);
    if ~isfield(runtime, field_name) || isempty(runtime.(field_name)) || ~isstruct(runtime.(field_name))
        return;
    end
    candidate = runtime.(field_name);
    current_cycle = get_option_field(runtime, 'cycle_index', NaN);
    source_cycle = get_option_field(candidate, 'cycle_index', NaN);
    if isfinite(current_cycle) && isfinite(source_cycle) && source_cycle >= current_cycle
        return;
    end
    previous = candidate;
end

function runtime_out = store_reusable_stage_record(runtime_out, runtime_in, stage_config, hook_report, T_out_51, state_out)
    if isempty(runtime_out) || ~isstruct(runtime_out)
        runtime_out = struct();
    end
    stage_index = get_option_field(runtime_in, 'stage_index', get_option_field(stage_config, 'stage_index', NaN));
    if ~isfinite(stage_index)
        return;
    end
    record = struct( ...
        'cycle_index', get_option_field(runtime_in, 'cycle_index', NaN), ...
        'stage_index', stage_index, ...
        'stage_name', stage_config.stage_name, ...
        'hook_report', hook_report, ...
        'T_out_51', T_out_51(:), ...
        'state_out', state_out, ...
        'runtime_out', runtime_out);
    field_name = reusable_stage_field_name(stage_index);
    runtime_out.(field_name) = record;
    runtime_out.last_cycle_stage_report = hook_report;
    runtime_out.last_cycle_stage_result_reuse_record = record;
end

function field_name = reusable_stage_field_name(stage_index)
    field_name = sprintf('last_reusable_stage_%02d', round(stage_index));
end

function runtime_out = update_runtime(runtime_in, stage_info, stage_config, ...
        observability, checkpoint_path, bridge_plan, energy_audit, sim_params, T_x_out_101, active_flow_audit)
    runtime_out = runtime_in;
    if isempty(runtime_out) || ~isstruct(runtime_out)
        runtime_out = struct();
    end
    if nargin < 10 || isempty(active_flow_audit) || ~isstruct(active_flow_audit)
        active_flow_audit = struct();
    end

    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    official_cold_end_temp = get_option_field(energy_audit, 'cold_end_temp_out', NaN);
    official_hot_end_temp = get_option_field(energy_audit, 'hot_end_temp_out', NaN);
    use_official_cold_end = strcmp(stage_name, 'cooldown_exchange') && isfinite(official_cold_end_temp);
    use_official_hot_end = strcmp(stage_name, 'hold_exchange') && isfinite(official_hot_end_temp);

    runtime_out.last_stage_name = get_option_field(stage_info, 'stage_name', '');
    runtime_out.last_hot_sink_temp_out = observability.hot_sink_temp_out;
    runtime_out.last_cold_sink_temp_out = observability.cold_sink_temp_out;
    runtime_out.last_chip_temp_out = observability.chip_temp_out;
    runtime_out.last_cold_load_temp_out = get_option_field(observability, ...
        'cold_load_temp_out', observability.chip_temp_out);
    runtime_out.last_hot_buffer_temp_out = observability.hot_buffer_temp_out;
    runtime_out.last_cold_buffer_temp_out = observability.cold_buffer_temp_out;
    runtime_out.last_hot_source_out = observability.hot_sink_temp_out;
    runtime_out.hot_sink_temp_current = observability.hot_sink_temp_out;
    runtime_out.cold_sink_temp_current = observability.cold_sink_temp_out;
    runtime_out.chip_temp_current = observability.chip_temp_out;
    runtime_out.cold_load_temp_current = get_option_field(observability, ...
        'cold_load_temp_out', observability.chip_temp_out);
    runtime_out.hot_buffer_temp_current = observability.hot_buffer_temp_out;
    runtime_out.cold_buffer_temp_current = observability.cold_buffer_temp_out;
    if use_official_hot_end
        runtime_out.official_hot_end_temp_current = official_hot_end_temp;
        runtime_out.last_hot_end_temp_out = official_hot_end_temp;
        runtime_out.hot_end_temp_current = official_hot_end_temp;
        runtime_out.hot_side_fluid_T_init = runtime_out.hot_buffer_temp_current;
        runtime_out.root_hot_loop_T_init = runtime_out.hot_buffer_temp_current;
    elseif strcmp(stage_name, 'cooldown_exchange')
        runtime_out.last_hot_end_temp_out = get_option_field(runtime_in, ...
            'hot_end_temp_current', get_option_field(runtime_in, ...
            'last_hot_end_temp_out', runtime_out.hot_sink_temp_current));
        runtime_out.hot_end_temp_current = runtime_out.last_hot_end_temp_out;
        runtime_out.hot_side_fluid_T_init = runtime_out.hot_buffer_temp_current;
        runtime_out.root_hot_loop_T_init = runtime_out.hot_buffer_temp_current;
    end
    if strcmp(stage_name, 'hold_exchange')
        runtime_out.last_cold_end_temp_out = get_option_field(runtime_in, 'cold_end_temp_current', runtime_out.cold_sink_temp_current);
        runtime_out.cold_end_temp_current = runtime_out.last_cold_end_temp_out;
        runtime_out.cold_side_fluid_T_init = runtime_out.cold_buffer_temp_current;
        runtime_out.root_cold_loop_T_init = runtime_out.cold_buffer_temp_current;
    end
    if use_official_cold_end
        runtime_out.official_cold_end_temp_current = official_cold_end_temp;
        runtime_out.last_cold_end_temp_out = official_cold_end_temp;
        runtime_out.cold_end_temp_current = official_cold_end_temp;
        runtime_out.cold_side_fluid_T_init = runtime_out.cold_buffer_temp_current;
        runtime_out.root_cold_loop_T_init = runtime_out.cold_buffer_temp_current;
    end
    runtime_out.hot_source_current = runtime_out.hot_sink_temp_current;
    pipe_T_end = get_option_field(energy_audit, 'pipe_internal_fluid_mean_T_end_K', ...
        get_option_field(sim_params, 'sma_fluid_T_init', NaN));
    pipe_delta_energy_J = get_option_field(energy_audit, 'pipe_internal_fluid_delta_energy_J', NaN);
    pipe_carryover_model = 'path_mean_pipe_temperature_carryover_v1';
    if strcmpi(char(string(get_option_field(sim_params, 'sma_fluid_T_init_policy', ''))), ...
            'previous_exchange_sma_avg')
        pipe_carryover_model = 'previous_exchange_sma_avg_pipe_initialization_v1';
    elseif strcmpi(char(string(get_option_field(sim_params, 'sma_fluid_T_init_policy', ''))), ...
            'stage_buffer_temperature')
        pipe_carryover_model = 'stage_buffer_temperature_pipe_initialization_v1';
    elseif any(strcmpi(char(string(get_option_field(sim_params, 'sma_fluid_T_init_policy', ''))), ...
            {'previous_active_stage_pipe', 'shared_pipe_previous_stage', 'opposite_path_carryover'}))
        pipe_carryover_model = 'shared_active_pipe_previous_stage_carryover_v1';
    end
    exchange_sma_avg_T_out = get_option_field(energy_audit, ...
        'T51_energy_weighted_mean_after_K', mean_finite(T_x_out_101(:)));
    if any(strcmp(stage_name, {'hold_exchange', 'cooldown_exchange'})) && ...
            isfinite(exchange_sma_avg_T_out)
        runtime_out.last_exchange_sma_avg_T_K = exchange_sma_avg_T_out;
        runtime_out.last_exchange_sma_avg_T_source = ...
            ['simulink_internal_101_mean_after_' stage_name];
        if strcmp(stage_name, 'hold_exchange')
            runtime_out.last_stage2_exchange_sma_avg_T_K = exchange_sma_avg_T_out;
        else
            runtime_out.last_stage4_exchange_sma_avg_T_K = exchange_sma_avg_T_out;
        end
    end
    runtime_out.official_cold_end_definition = get_option_field(energy_audit, 'official_cold_end_definition', ...
        get_option_field(sim_params, 'official_cold_end_definition', ''));
    runtime_out.official_hot_end_definition = get_option_field(energy_audit, 'official_hot_end_definition', ...
        get_option_field(sim_params, 'official_hot_end_definition', ''));
    pressure_control_converged = logical(get_option_field(active_flow_audit, ...
        'actual_flush_pressure_control_converged', false));
    stage_pressure_MPa = get_option_field(sim_params, 'pressure_differential_MPa', NaN);
    if pressure_control_converged && isnumeric(stage_pressure_MPa) && isscalar(stage_pressure_MPa) && ...
            isfinite(stage_pressure_MPa)
        switch stage_name
            case 'hold_exchange'
                runtime_out.stage2_converged_pressure_MPa = stage_pressure_MPa;
                runtime_out.stage2_last_known_good_pressure_MPa = stage_pressure_MPa;
                runtime_out.stage2_run_last_known_good_pressure_MPa = stage_pressure_MPa;
            case 'cooldown_exchange'
                runtime_out.stage4_converged_pressure_MPa = stage_pressure_MPa;
                runtime_out.stage4_last_known_good_pressure_MPa = stage_pressure_MPa;
                runtime_out.stage4_run_last_known_good_pressure_MPa = stage_pressure_MPa;
        end
        runtime_out.run_last_known_good_pressure_MPa = stage_pressure_MPa;
        runtime_out.run_last_known_good_pressure_stage_name = stage_name;
    end
    runtime_out.hot_end_C_total_J_per_K = get_option_field(energy_audit, 'hot_end_C_total_J_per_K', ...
        get_option_field(sim_params, 'hot_end_C_total_J_per_K', NaN));
    runtime_out.hot_end_effective_water_volume_ml = get_option_field(energy_audit, ...
        'hot_end_effective_water_volume_ml', get_option_field(sim_params, 'hot_end_effective_water_volume_ml', NaN));
    runtime_out.hot_end_delivery_ratio_measured = get_option_field(energy_audit, 'hot_end_delivery_ratio_measured', NaN);
    runtime_out.Q_hot_end_received_measured_J = get_option_field(energy_audit, 'Q_hot_end_received_measured_J', NaN);
    runtime_out.Q_unaccounted_stage2_J = get_option_field(energy_audit, 'Q_unaccounted_stage2_J', NaN);
    runtime_out.hot_end_delivery_pass = get_option_field(energy_audit, 'hot_end_delivery_pass', false);
    runtime_out.hot_side_state_sync_policy = ...
        'raw_hot_sink_and_buffer_writeback_all_stages; official_hot_end_active_hold_only';
    runtime_out.cold_end_C_total_J_per_K = get_option_field(energy_audit, 'cold_end_C_total_J_per_K', ...
        get_option_field(sim_params, 'cold_end_C_total_J_per_K', NaN));
    runtime_out.cold_end_effective_water_volume_ml = get_option_field(energy_audit, ...
        'cold_end_effective_water_volume_ml', get_option_field(sim_params, 'cold_end_effective_water_volume_ml', NaN));
    runtime_out.cold_end_delivery_ratio = get_option_field(energy_audit, 'cold_end_delivery_ratio', NaN);
    runtime_out.cold_end_delivery_ratio_measured = get_option_field(energy_audit, 'cold_end_delivery_ratio_measured', NaN);
    runtime_out.Q_cold_end_received_measured_J = get_option_field(energy_audit, 'Q_cold_end_received_measured_J', NaN);
    runtime_out.Q_cold_end_received_ideal_J = get_option_field(energy_audit, 'Q_cold_end_received_ideal_J', NaN);
    runtime_out.Q_unaccounted_stage4_J = get_option_field(energy_audit, 'Q_unaccounted_stage4_J', NaN);
    runtime_out.cold_end_delivery_pass = get_option_field(energy_audit, 'cold_end_delivery_pass', false);
    runtime_out.cold_side_state_sync_policy = ...
        'raw_cold_sink_and_buffer_writeback_all_stages; official_cold_end_active_cooldown_only';
    cold_pipe_T_state_out = get_option_field(energy_audit, 'cold_pipe_or_CHEX_T_state_out_K', ...
        get_option_field(energy_audit, 'cold_pipe_or_CHEX_T_mean_out_K', NaN));
    cold_hx_pipe_T_state_out = get_option_field(energy_audit, 'cold_hx_pipe_T_state_out_K', cold_pipe_T_state_out);
    cold_return_pipe_T_state_out = get_option_field(energy_audit, 'cold_return_pipe_T_state_out_K', NaN);
    cold_pipe_writeback_source = get_option_field(energy_audit, 'cold_pipe_state_writeback_source', ...
        get_option_field(energy_audit, 'cold_pipe_or_CHEX_runtime_writeback_source', ...
        'cold_pipe_or_CHEX_energy_audit_state'));
    if strcmpi(stage_name, 'cooldown_exchange') && ...
            isnumeric(cold_pipe_T_state_out) && isscalar(cold_pipe_T_state_out) && isfinite(cold_pipe_T_state_out)
        runtime_out.cold_pipe_or_CHEX_T_state_K = cold_pipe_T_state_out;
        runtime_out.last_cold_pipe_or_CHEX_T_state_out = cold_pipe_T_state_out;
        runtime_out.cold_pipe_or_CHEX_T_state_source = cold_pipe_writeback_source;
        runtime_out.cold_pipe_state_writeback_source = cold_pipe_writeback_source;
        if isnumeric(cold_hx_pipe_T_state_out) && isscalar(cold_hx_pipe_T_state_out) && isfinite(cold_hx_pipe_T_state_out)
            runtime_out.cold_hx_pipe_T_state_K = cold_hx_pipe_T_state_out;
            runtime_out.last_cold_hx_pipe_T_state_out = cold_hx_pipe_T_state_out;
            runtime_out.cold_hx_pipe_T_state_source = cold_pipe_writeback_source;
        end
        if isnumeric(cold_return_pipe_T_state_out) && isscalar(cold_return_pipe_T_state_out) && isfinite(cold_return_pipe_T_state_out)
            runtime_out.cold_return_pipe_T_state_K = cold_return_pipe_T_state_out;
            runtime_out.last_cold_return_pipe_T_state_out = cold_return_pipe_T_state_out;
            runtime_out.cold_return_pipe_T_state_source = get_option_field(energy_audit, ...
                'cold_return_pipe_state_writeback_source', 'active_cooldown_return_pipe_terminal_observation');
        end
    elseif strcmpi(stage_name, 'hold_exchange')
        runtime_out.cold_pipe_or_CHEX_T_state_source = 'frozen_previous_cooldown';
        runtime_out.cold_pipe_state_writeback_source = 'frozen_previous_cooldown';
        runtime_out.cold_hx_pipe_T_state_source = 'frozen_previous_cooldown';
        runtime_out.cold_return_pipe_T_state_source = 'frozen_previous_cooldown';
    end
    internal_node_count = get_option_field(sim_params, ...
        'solver_internal_thermal_node_count', numel(T_x_out_101));
    switch stage_name
        case 'hold_exchange'
            if isnumeric(T_x_out_101) && numel(T_x_out_101) == internal_node_count && all(isfinite(T_x_out_101(:)))
                runtime_out.stage2_T_x_21_state = T_x_out_101(:);
                runtime_out.stage2_T_x_21_state_source = 'simulink_internal_21_temperature_after_hold_exchange';
            end
            runtime_out.hold_pipe_fluid_mean_T_current_K = pipe_T_end;
            runtime_out.pending_hot_pipe_energy_J = pipe_delta_energy_J;
            runtime_out.last_pipe_carryover_destination = 'hold_path_to_hot_sink_next_hold';
            runtime_out.stage2_path_pipe_T_state_K = get_option_field(energy_audit, ...
                'stage2_path_pipe_T_state_out_K', pipe_T_end);
            runtime_out.stage2_path_pipe_unreleased_cumulative_J = get_option_field(energy_audit, ...
                'stage2_path_pipe_unreleased_cumulative_J', NaN);
            runtime_out.stage2_path_pipe_delta_U_J = get_option_field(energy_audit, ...
                'stage2_path_pipe_delta_U_J', pipe_delta_energy_J);
        case 'cooldown_exchange'
            if isnumeric(T_x_out_101) && numel(T_x_out_101) == internal_node_count && all(isfinite(T_x_out_101(:)))
                runtime_out.stage4_T_x_21_state = T_x_out_101(:);
                runtime_out.stage4_T_x_21_state_source = 'simulink_internal_21_temperature_after_cooldown_exchange';
            end
            runtime_out.cooldown_pipe_fluid_mean_T_current_K = pipe_T_end;
            runtime_out.pending_cold_pipe_energy_J = pipe_delta_energy_J;
            runtime_out.last_pipe_carryover_destination = 'cooldown_path_to_cold_sink_next_cooldown';
            runtime_out.stage4_path_pipe_T_state_K = get_option_field(energy_audit, ...
                'stage4_path_pipe_T_state_out_K', pipe_T_end);
            runtime_out.stage4_path_pipe_unreleased_cumulative_J = get_option_field(energy_audit, ...
                'stage4_path_pipe_unreleased_cumulative_J', NaN);
            runtime_out.stage4_path_pipe_delta_U_J = get_option_field(energy_audit, ...
                'stage4_path_pipe_delta_U_J', pipe_delta_energy_J);
            transit_T_state_out = get_option_field(energy_audit, ...
                'stage4_sma_to_CHEX_transit_T_state_out_K', NaN);
            if isnumeric(transit_T_state_out) && isscalar(transit_T_state_out) && isfinite(transit_T_state_out)
                % Forward-compatible canonical name for the Simulink-observed
                % TransitPipe state. Old key kept as alias for resume-from-old.
                runtime_out.transit_pipe_T_state_K = transit_T_state_out;
                runtime_out.last_transit_pipe_T_state_out_K = transit_T_state_out;
                runtime_out.transit_pipe_T_state_source = get_option_field(energy_audit, ...
                    'stage4_sma_to_CHEX_transit_state_source', ...
                    'simulink_TL_TransitPipe_LConn_probe_with_flux_integral');
                runtime_out.stage4_sma_to_CHEX_transit_T_state_K = transit_T_state_out;
                runtime_out.last_stage4_sma_to_CHEX_transit_T_state_out_K = transit_T_state_out;
                runtime_out.stage4_sma_to_CHEX_transit_T_state_source = ...
                    runtime_out.transit_pipe_T_state_source;
            end
            runtime_out.stage4_sma_to_CHEX_transit_delta_U_J = get_option_field(energy_audit, ...
                'stage4_sma_to_CHEX_transit_delta_U_J', NaN);
            runtime_out.stage4_sma_to_CHEX_transit_delta_U_flux_J = get_option_field(energy_audit, ...
                'stage4_sma_to_CHEX_transit_delta_U_flux_J', NaN);
            runtime_out.stage4_sma_to_CHEX_transit_delta_U_state_J = get_option_field(energy_audit, ...
                'stage4_sma_to_CHEX_transit_delta_U_state_J', NaN);
            runtime_out.stage4_sma_to_CHEX_transit_unaccounted_gap_J = get_option_field(energy_audit, ...
                'stage4_sma_to_CHEX_transit_unaccounted_gap_J', NaN);
    end
    runtime_out.pipe_energy_carryover_model = pipe_carryover_model;
    runtime_out.last_pipe_internal_fluid_delta_energy_J = pipe_delta_energy_J;
    runtime_out.last_pipe_internal_fluid_mean_T_end_K = pipe_T_end;
    runtime_out.last_checkpoint_path = checkpoint_path;
    runtime_out.last_bridge_plan = bridge_plan;
    runtime_out.last_stage_kind = stage_config.stage_kind;
    if get_option_field(bridge_plan, 'enabled', false)
        runtime_out.pending_bridge_plan = bridge_plan;
    else
        runtime_out.pending_bridge_plan = struct();
    end
end

function audit = build_buffer_handoff_audit(runtime_in, runtime_out, stage_config, sim_params, observability)
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    cold_runtime_in = get_option_field(runtime_in, 'cold_buffer_temp_current', NaN);
    hot_runtime_in = get_option_field(runtime_in, 'hot_buffer_temp_current', NaN);
    cold_observed_last = get_option_field(observability, 'cold_buffer_temp_out', NaN);
    hot_observed_last = get_option_field(observability, 'hot_buffer_temp_out', NaN);
    cold_runtime_out = get_option_field(runtime_out, 'cold_buffer_temp_current', NaN);
    hot_runtime_out = get_option_field(runtime_out, 'hot_buffer_temp_current', NaN);
    audit = struct( ...
        'buffer_handoff_audit_version', 'r48_a264a_raw_buffer_handoff_v1', ...
        'stage_name', stage_name, ...
        'cold_buffer_runtime_in_K', cold_runtime_in, ...
        'cold_buffer_runtime_after_observability_K', cold_observed_last, ...
        'cold_buffer_runtime_out_K', cold_runtime_out, ...
        'cold_buffer_runtime_restore_delta_K', cold_runtime_out - cold_observed_last, ...
        'cold_buffer_init_to_first_delta_K', get_option_field(observability, 'cold_buffer_temp_out_first_sample', NaN) - ...
            get_option_field(sim_params, 'cold_fluid_buffer_T_init', NaN), ...
        'cold_buffer_first_to_last_delta_K', get_option_field(observability, 'cold_buffer_temp_out_last_sample', NaN) - ...
            get_option_field(observability, 'cold_buffer_temp_out_first_sample', NaN), ...
        'cold_buffer_init_to_runtime_out_delta_K', cold_runtime_out - ...
            get_option_field(sim_params, 'cold_fluid_buffer_T_init', NaN), ...
        'cold_buffer_handoff_source', classify_buffer_handoff(stage_name, cold_runtime_out, cold_observed_last, cold_runtime_in), ...
        'hot_buffer_runtime_in_K', hot_runtime_in, ...
        'hot_buffer_runtime_after_observability_K', hot_observed_last, ...
        'hot_buffer_runtime_out_K', hot_runtime_out, ...
        'hot_buffer_runtime_restore_delta_K', hot_runtime_out - hot_observed_last, ...
        'hot_buffer_init_to_first_delta_K', get_option_field(observability, 'hot_buffer_temp_out_first_sample', NaN) - ...
            get_option_field(sim_params, 'hot_fluid_buffer_T_init', NaN), ...
        'hot_buffer_first_to_last_delta_K', get_option_field(observability, 'hot_buffer_temp_out_last_sample', NaN) - ...
            get_option_field(observability, 'hot_buffer_temp_out_first_sample', NaN), ...
        'hot_buffer_init_to_runtime_out_delta_K', hot_runtime_out - ...
            get_option_field(sim_params, 'hot_fluid_buffer_T_init', NaN), ...
        'hot_buffer_handoff_source', classify_buffer_handoff(stage_name, hot_runtime_out, hot_observed_last, hot_runtime_in));
end

function source = classify_buffer_handoff(stage_name, runtime_out_value, observed_value, runtime_in_value)
    tol = 1.0e-9;
    if isfinite(runtime_out_value) && isfinite(observed_value) && abs(runtime_out_value - observed_value) <= tol
        source = 'raw_observability_last_sample_carried';
    elseif isfinite(runtime_out_value) && isfinite(runtime_in_value) && abs(runtime_out_value - runtime_in_value) <= tol
        source = ['restored_runtime_in_during_', stage_name];
    else
        source = 'mixed_or_unknown_writeback';
    end
end

function snapshot = build_r28_cold_side_snapshot( ...
        stage_config, sim_params, runtime, observability, energy_audit, ...
        active_flow_audit, exchange_options)
    enabled = logical(get_option_field(exchange_options, 'r28_dump_cold_side', false));
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
