        'cold_end_delivery_ratio_measured', get_option_field(energy_audit, 'cold_end_delivery_ratio_measured', NaN), ...
        'CHEX_to_cold_entity_delivery_ratio_observed', get_option_field(energy_audit, 'CHEX_to_cold_entity_delivery_ratio_observed', NaN), ...
        'hot_buffer_T_in_K', get_option_field(sim_params, 'hot_fluid_buffer_T_init', NaN), ...
        'hot_buffer_T_out_K', get_option_field(observability, 'hot_buffer_temp_out', NaN), ...
        'hot_sink_T_in_K', get_option_field(sim_params, 'hot_sink_T_init', NaN), ...
        'hot_sink_T_out_K', get_option_field(observability, 'hot_sink_temp_out', NaN), ...
        'hot_pipe_or_HHEX_storage_J', get_option_field(energy_audit, 'Q_hot_pipe_or_HHEX_storage_J', NaN), ...
        'L_valve_target_json', jsonencode(get_option_field(sim_params, 'L_valve_target', [])), ...
        'L_valve_initial_json', jsonencode(get_option_field(sim_params, 'L_valve_initial', [])), ...
        'L_valve_command_target_json', jsonencode(get_option_field(sim_params, 'L_valve_command_target', [])), ...
        'runtime_run_last_known_good_pressure_MPa', get_option_field(runtime, 'run_last_known_good_pressure_MPa', NaN), ...
        'runtime_run_last_known_good_pressure_stage_name', get_option_field(runtime, 'run_last_known_good_pressure_stage_name', ''), ...
        'pressure_differential_MPa', get_option_field(sim_params, 'pressure_differential_MPa', NaN), ...
        'pressure_differential_MPa_initial_guess_source', get_option_field(sim_params, 'pressure_differential_MPa_initial_guess_source', ''));
    if ~enabled
        snapshot.source = 'r28_dump_cold_side_disabled';
    end
end

function T_end = extract_terminal_temperature(simOut, var_name, expected_count)
    values = extract_logged_values(simOut, var_name);
    if isempty(values)
        error('Run_Simulink_Exchange_Hook:MissingTemperatureLog', ...
            'Simulink output "%s" is missing.', var_name);
    end

    if isvector(values)
        T_end = values(:);
    elseif ismatrix(values)
        if size(values, 2) == expected_count
            T_end = values(end, :).';
        elseif size(values, 1) == expected_count
            T_end = values(:, end);
        else
            error('Run_Simulink_Exchange_Hook:UnexpectedTemperatureShape', ...
                'Logged temperature array for "%s" has unexpected shape.', var_name);
        end
    else
        error('Run_Simulink_Exchange_Hook:UnexpectedTemperatureRank', ...
            'Logged temperature array for "%s" must be 1D or 2D.', var_name);
    end

    if numel(T_end) ~= expected_count || any(~isfinite(T_end))
        error('Run_Simulink_Exchange_Hook:InvalidTemperatureLog', ...
            'Logged terminal temperature for "%s" is invalid.', var_name);
    end
end

function value = extract_terminal_scalar(simOut, var_names, default_value)
    if nargin < 3
        default_value = [];
    end
    if ischar(var_names) || isstring(var_names)
        var_names = cellstr(var_names);
    end

    for idx = 1:numel(var_names)
        values = extract_logged_values(simOut, var_names{idx});
        if isempty(values)
            continue;
        end

        value = values(end);
        if isfinite(value)
            return;
        end
    end

    if ~isempty(default_value)
        value = default_value;
        return;
    end

    error('Run_Simulink_Exchange_Hook:MissingScalarLog', ...
        'Unable to locate a finite scalar log among: %s', strjoin(var_names, ', '));
end

function values = extract_logged_values(simOut, var_name)
    values = [];
    if ~isprop(simOut, var_name)
        return;
    end

    logged = simOut.(var_name);
    if isa(logged, 'timeseries')
        values = logged.Data;
        return;
    end
    if isstruct(logged)
        if isfield(logged, 'signals') && isfield(logged.signals, 'values')
            values = logged.signals.values;
            return;
        end
        if isfield(logged, 'Data')
            values = logged.Data;
            return;
        end
    end
    if isnumeric(logged)
        values = logged;
    end
end

function [time, values] = extract_logged_series(simOut, var_names)
    if ischar(var_names) || isstring(var_names)
        var_names = cellstr(var_names);
    end

    for idx = 1:numel(var_names)
        var_name = var_names{idx};
        if ~isprop(simOut, var_name)
            continue;
        end
        logged = simOut.(var_name);
        if isa(logged, 'timeseries')
            time = logged.Time(:);
            values = normalize_series_data(logged.Data, numel(time));
            return;
        end
        if isstruct(logged)
            if isfield(logged, 'time')
                time = logged.time(:);
            elseif isfield(logged, 'Time')
                time = logged.Time(:);
            else
                time = [];
            end
            if isfield(logged, 'signals') && isfield(logged.signals, 'values')
                values = normalize_series_data(logged.signals.values, numel(time));
            elseif isfield(logged, 'Data')
                values = normalize_series_data(logged.Data, numel(time));
            else
                values = [];
            end
            if ~isempty(time) && ~isempty(values)
                return;
            end
        end
    end
    time = [];
    values = [];
end

function stats = extract_logged_endpoint_stats(simOut, var_names, terminal_fallback)
    if nargin < 3
        terminal_fallback = NaN;
    end
    [~, values] = extract_logged_series(simOut, var_names);
    finite_values = values(isfinite(values));
    if isempty(finite_values)
        finite_values = terminal_fallback;
        finite_values = finite_values(isfinite(finite_values));
    end
    if isempty(finite_values)
        stats = struct('first', NaN, 'last', NaN, 'min', NaN, 'max', NaN, 'count', 0);
        return;
    end
    stats = struct( ...
        'first', finite_values(1), ...
        'last', finite_values(end), ...
        'min', min(finite_values), ...
        'max', max(finite_values), ...
        'count', numel(finite_values));
end

function values = normalize_series_data(data, expected_length)
    data = squeeze(data);
    if isempty(data)
        values = [];
        return;
    end
    if isvector(data)
        values = double(data(:));
        return;
    end
    if size(data, 1) == expected_length
        values = double(data(:, 1));
    elseif size(data, 2) == expected_length
        values = double(data(1, :).');
    else
        values = double(data(:));
    end
end

function probe = build_exchange_probe_timeseries( ...
        simOut, stage_info, stage_config, sim_params, runtime, ...
        temperature_var_name, temperature_expected_count, observability)
    sample_count = round(get_option_field(sim_params, 'probe_sample_count', ...
        get_option_field(stage_config, 'probe_sample_count', 50)));
    sample_count = max(sample_count, 2);
    stage_duration_s = get_option_field(stage_config, 'stop_time_s', NaN);
    if ~(isfinite(stage_duration_s) && stage_duration_s > 0)
        stage_duration_s = 0.0;
    end
    t_local = linspace(0.0, stage_duration_s, sample_count).';
    cycle_index = get_option_field(runtime, 'cycle_index', 1);
    cycle_period_s = get_option_field(runtime, 'cycle_period_s', 1.0);
    t_stage_start = get_option_field(stage_info, 't_start', 0.0);
    t_global = (max(cycle_index, 1) - 1) * cycle_period_s + t_stage_start + t_local;

    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    switch stage_name
        case 'hold_exchange'
            sma_in_names = {'probe_sma_stage2_port1_v1_side_T_K', 'sma_hold_inlet_fluid_temp_out'};
            sma_out_names = {'probe_sma_stage2_port2_v3_side_T_K', 'sma_hold_outlet_fluid_temp_out'};
            active_mass_names = {'mass_flow_v1_cold_inlet_kgps'};
            cold_supply_names = sma_in_names;
            cold_return_names = {};
            cold_supply_semantics = 'hold_exchange_cold_buffer_to_sma_inlet';
            cold_return_semantics = 'not_applicable_hold_exchange_chip_side_isolated';
        case 'cooldown_exchange'
            sma_in_names = {'probe_sma_stage4_port3_v4_side_T_K', 'sma_cooldown_inlet_fluid_temp_out'};
            sma_out_names = {'probe_sma_stage4_port4_v6_side_T_K', 'sma_cooldown_outlet_fluid_temp_out'};
            active_mass_names = {'mass_flow_v4_hot_inlet_kgps'};
            cold_supply_names = {'probe_transit_pipe_outlet_T_K', ...
                'transit_to_chex_fluid_temp_out', 'cold_hx_inlet_fluid_temp_out'};
            cold_return_names = {'cold_hx_outlet_fluid_temp_out', ...
                'probe_chip_to_cold_junction_T_K', 'chip_outlet_fluid_temp_out'};
            cold_supply_semantics = 'stage4_true_CHEX_inlet_after_TransitPipe';
            cold_return_semantics = 'stage4_true_CHEX_outlet_before_adiabatic_return_pipe';
        otherwise
            sma_in_names = {};
            sma_out_names = {};
            active_mass_names = {};
            cold_supply_names = {};
            cold_return_names = {};
            cold_supply_semantics = 'not_exchange_stage';
            cold_return_semantics = 'not_exchange_stage';
    end

    T_sma_fluid_in = resample_logged_scalar(simOut, sma_in_names, t_local, ...
        get_option_field(observability, 'sma_inlet_fluid_temp_out', NaN));
    T_sma_fluid_out = resample_logged_scalar(simOut, sma_out_names, t_local, ...
        get_option_field(observability, 'sma_outlet_fluid_temp_out', NaN));
    T_chip = resample_logged_scalar(simOut, {'cold_load_temp_out', 'chip_temp_out'}, t_local, ...
        get_option_field(observability, 'chip_temp_out', NaN));
    T_chip_fluid_in = resample_logged_scalar(simOut, ...
        {'probe_chip_pipe_port_conn2_v6_sma_side_T_K', 'chip_inlet_fluid_temp_out', ...
        'probe_transit_pipe_inlet_T_K'}, ...
        t_local, get_option_field(observability, 'chip_inlet_fluid_temp_out', NaN));
    T_chip_fluid_out = resample_logged_scalar(simOut, ...
        {'probe_chip_to_cold_junction_T_K', 'chip_outlet_fluid_temp_out'}, ...
        t_local, get_option_field(observability, 'chip_outlet_fluid_temp_out', NaN));
    % Transit pipe outlet (= true CHEX inlet) time series. Falls back to the
    % V6/transit-inlet probe if the new ToWorkspace channel is absent (legacy
    % .slx without TransitPipe). This is the canonical post-transit boundary.
    T_transit_pipe_outlet = resample_logged_scalar(simOut, ...
        {'probe_transit_pipe_outlet_T_K', 'transit_to_chex_fluid_temp_out'}, ...
        t_local, get_option_field(observability, 'transit_to_chex_fluid_temp_out', ...
        get_option_field(observability, 'chip_inlet_fluid_temp_out', NaN)));
    T_hot_sink = resample_logged_scalar(simOut, {'hot_sink_temp_out', 'hot_source_out'}, ...
        t_local, get_option_field(observability, 'hot_sink_temp_out', NaN));
    T_hot_hx_inlet = resample_logged_scalar(simOut, ...
        {'probe_hot_hx_port1_v3_side_T_K', 'hot_hx_inlet_fluid_temp_out', 'hot_subsystem_inlet_fluid_temp_out'}, ...
        t_local, get_option_field(observability, 'hot_hx_inlet_fluid_temp_out', NaN));
    T_hot_hx_outlet = resample_logged_scalar(simOut, ...
        {'probe_hot_hx_port2_v2_return_side_T_K', 'hot_hx_outlet_fluid_temp_out', 'hot_subsystem_outlet_fluid_temp_out'}, ...
        t_local, get_option_field(observability, 'hot_hx_outlet_fluid_temp_out', NaN));
    T_cold_sink = resample_logged_scalar(simOut, {'cold_sink_temp_out'}, ...
        t_local, get_option_field(observability, 'cold_sink_temp_out', NaN));
    T_cold_sink_pipe_thermal_port = resample_logged_scalar(simOut, ...
        {'cold_sink_hx_pipe_thermal_port_temp_out', 'cold_sink_pipe_thermal_port_temp_out'}, t_local, ...
        get_option_field(observability, 'cold_sink_pipe_thermal_port_temp_out', NaN));
    T_cold_return_pipe_thermal_port = resample_logged_scalar(simOut, ...
        {'cold_return_pipe_thermal_port_temp_out'}, t_local, ...
        get_option_field(observability, 'cold_return_pipe_thermal_port_temp_out', NaN));
    Qdot_cold_sink_mass_to_pipe = resample_logged_scalar(simOut, ...
        {'Qdot_cold_sink_mass_to_hx_pipe_W', 'Qdot_cold_sink_mass_to_pipe_W'}, t_local, ...
        get_option_field(observability, 'Qdot_cold_sink_mass_to_pipe_terminal_W', NaN));
    T_cold_return_inlet = resample_logged_scalar(simOut, ...
        {'cold_return_inlet_fluid_temp_out', 'cold_hx_outlet_fluid_temp_out'}, t_local, ...
        get_option_field(observability, 'cold_return_inlet_fluid_temp_out', NaN));
    T_cold_return_outlet = resample_logged_scalar(simOut, ...
        {'cold_return_outlet_fluid_temp_out', 'probe_cold_hx_port_conn1_v5_return_side_T_K', ...
        'cold_subsystem_outlet_fluid_temp_out'}, t_local, ...
        get_option_field(observability, 'cold_return_outlet_fluid_temp_out', NaN));
    T_cold_supply = resample_logged_scalar(simOut, cold_supply_names, t_local, NaN);
    T_cold_return = resample_logged_scalar(simOut, cold_return_names, t_local, NaN);
    T_probe_v1_cold_inlet_cold_buffer_side = resample_logged_scalar(simOut, ...
        {'probe_v1_cold_inlet_cold_buffer_side_T_K'}, t_local, ...
        get_option_field(observability, 'probe_v1_cold_inlet_cold_buffer_side_T_K', NaN));
    T_probe_v1_cold_inlet_sma_side = resample_logged_scalar(simOut, ...
        {'probe_v1_cold_inlet_sma_side_T_K'}, t_local, ...
        get_option_field(observability, 'probe_v1_cold_inlet_sma_side_T_K', NaN));
    T_probe_sma_stage2_port1_v1_side = resample_logged_scalar(simOut, ...
        {'probe_sma_stage2_port1_v1_side_T_K', 'sma_hold_inlet_fluid_temp_out'}, t_local, ...
        get_option_field(observability, 'probe_sma_stage2_port1_v1_side_T_K', NaN));
    T_probe_sma_stage2_port2_v3_side = resample_logged_scalar(simOut, ...
        {'probe_sma_stage2_port2_v3_side_T_K', 'sma_hold_outlet_fluid_temp_out'}, t_local, ...
        get_option_field(observability, 'probe_sma_stage2_port2_v3_side_T_K', NaN));
    T_probe_v3_sma_to_hot_sma_side = resample_logged_scalar(simOut, ...
        {'probe_v3_sma_to_hot_sma_side_T_K'}, t_local, ...
        get_option_field(observability, 'probe_v3_sma_to_hot_sma_side_T_K', NaN));
    T_probe_v3_sma_to_hot_hot_hx_side = resample_logged_scalar(simOut, ...
        {'probe_v3_sma_to_hot_hot_hx_side_T_K'}, t_local, ...
        get_option_field(observability, 'probe_v3_sma_to_hot_hot_hx_side_T_K', NaN));
    T_probe_v4_hot_inlet_hot_buffer_side = resample_logged_scalar(simOut, ...
        {'probe_v4_hot_inlet_hot_buffer_side_T_K'}, t_local, ...
        get_option_field(observability, 'probe_v4_hot_inlet_hot_buffer_side_T_K', NaN));
    T_probe_v4_hot_inlet_sma_side = resample_logged_scalar(simOut, ...
        {'probe_v4_hot_inlet_sma_side_T_K'}, t_local, ...
        get_option_field(observability, 'probe_v4_hot_inlet_sma_side_T_K', NaN));
    T_probe_sma_stage4_port3_v4_side = resample_logged_scalar(simOut, ...
        {'probe_sma_stage4_port3_v4_side_T_K', 'sma_cooldown_inlet_fluid_temp_out'}, t_local, ...
        get_option_field(observability, 'probe_sma_stage4_port3_v4_side_T_K', NaN));
    T_probe_sma_stage4_port4_v6_side = resample_logged_scalar(simOut, ...
        {'probe_sma_stage4_port4_v6_side_T_K', 'sma_cooldown_outlet_fluid_temp_out'}, t_local, ...
        get_option_field(observability, 'probe_sma_stage4_port4_v6_side_T_K', NaN));
    T_probe_v6_sma_to_cold_hx_sma_side = resample_logged_scalar(simOut, ...
        {'probe_v6_sma_to_chip_sma_side_T_K', 'probe_v6_sma_to_cold_hx_sma_side_T_K'}, t_local, ...
        get_option_field(observability, 'probe_v6_sma_to_chip_sma_side_T_K', NaN));
    T_probe_v6_sma_to_cold_hx_cold_hx_side = resample_logged_scalar(simOut, ...
        {'probe_v6_sma_to_chip_chip_side_T_K', 'probe_v6_sma_to_cold_hx_cold_hx_side_T_K'}, t_local, ...
        get_option_field(observability, 'probe_v6_sma_to_chip_chip_side_T_K', NaN));

    if strcmpi(stage_name, 'cooldown_exchange')
        T_stage4_CHEX_pre_transit = T_chip_fluid_in;
        T_stage4_CHEX_inlet = T_transit_pipe_outlet;
        T_stage4_CHEX_outlet = T_chip_fluid_out;
        stage4_CHEX_inlet_source = 'TransitPipe_V6_to_CHEX.LConn / ColdSinkHXPipe.RConn post-transit probe';
        stage4_CHEX_outlet_source = 'ColdSinkHXPipe.LConn true HX outlet probe before ColdSinkReturnPipe';
    else
        T_stage4_CHEX_pre_transit = repmat(NaN, sample_count, 1);
        T_stage4_CHEX_inlet = repmat(NaN, sample_count, 1);
        T_stage4_CHEX_outlet = repmat(NaN, sample_count, 1);
        stage4_CHEX_inlet_source = 'not_cooldown_exchange';
        stage4_CHEX_outlet_source = 'not_cooldown_exchange';
    end
    cold_hx_inlet_stats = series_stats(T_stage4_CHEX_inlet);
    cold_hx_outlet_stats = series_stats(T_stage4_CHEX_outlet);
    stage4_CHEX_inlet_stats = series_stats(T_stage4_CHEX_inlet);
    stage4_CHEX_outlet_stats = series_stats(T_stage4_CHEX_outlet);

    [t_m, mdot_raw] = extract_logged_series(simOut, active_mass_names);
    if numel(t_m) >= 2 && numel(mdot_raw) == numel(t_m)
        mdot_active = signed_mass_flow_series(t_m, mdot_raw, t_local, observability);
        mdot_active = max(mdot_active, 0.0);
        mdot_quality = 'resampled_from_logged_active_branch';
    else
        mdot_active = repmat(max(get_option_field(observability, ...
            'sma_inlet_branch_mass_flow_kgps', NaN), 0.0), sample_count, 1);
        mdot_quality = 'terminal_constant_fallback';
    end
    Q_active = mdot_active ./ max(get_option_field(sim_params, 'rho_water', NaN), eps);

    [t_Tx, Tx_matrix] = extract_logged_matrix_series(simOut, temperature_var_name, temperature_expected_count);
    if numel(t_Tx) >= 2 && size(Tx_matrix, 1) == numel(t_Tx)
        Tx_sampled = resample_matrix_series(t_Tx, Tx_matrix, t_local);
        sma_101_quality = 'resampled_from_logged_temperature_matrix';
    elseif isfield(observability, 'Tx_internal_raw_simulink')
        Tx_sampled = repmat(observability.Tx_internal_raw_simulink(:).', sample_count, 1);
        sma_101_quality = 'terminal_temperature_fallback';
    else
        Tx_sampled = NaN(sample_count, max(temperature_expected_count, 1));
        sma_101_quality = 'missing_temperature_matrix';
    end
    T_sma_101_mean = mean(Tx_sampled, 2, 'omitnan');
    center_idx = max(1, ceil(size(Tx_sampled, 2) / 2));
    T_sma_101_center = Tx_sampled(:, center_idx);
    if size(Tx_sampled, 2) >= 2
        T_sma_101_edge = mean([Tx_sampled(:, 1), Tx_sampled(:, end)], 2, 'omitnan');
    else
        T_sma_101_edge = Tx_sampled(:, 1);
    end

    chip_fluid_G = get_option_field(sim_params, 'cold_load_to_cold_sink_G_W_per_K', ...
        get_option_field(sim_params, 'chip_fluid_G_effective_W_per_K', NaN));
    chip_heat_W = get_option_field(sim_params, 'cold_load_heat_W', ...
        get_option_field(sim_params, 'chip_heat_W', NaN));
    Qdot_chip_to_fluid = chip_fluid_G .* (T_chip - T_cold_sink);
    if ~isfinite(chip_fluid_G)
        Qdot_chip_to_fluid(:) = NaN;
    end
    if all(isfinite(Qdot_cold_sink_mass_to_pipe)) && numel(t_local) >= 2
        Q_cold_sink_mass_to_pipe_trapz_J = trapz(t_local, Qdot_cold_sink_mass_to_pipe);
    else
        Q_cold_sink_mass_to_pipe_trapz_J = NaN;
    end

    probe = struct( ...
        'probe_timeseries_semantics_version', 'exchange_probe_timeseries_v2_post_transit_chex_boundary_50pt', ...
        'probe_time_local_s', t_local, ...
        'probe_time_global_s', t_global, ...
        'probe_sample_count', sample_count, ...
        'probe_sampling_method', 'uniform_resample_from_simulink_logs', ...
        'probe_timeseries_mdot_quality', mdot_quality, ...
        'probe_timeseries_sma_101_quality', sma_101_quality, ...
        'T_sma_fluid_in_K_t', T_sma_fluid_in, ...
        'T_sma_fluid_out_K_t', T_sma_fluid_out, ...
        'T_sma_surface_or_strip_mean_K_t', T_sma_101_mean, ...
        'T_sma_101_mean_K_t', T_sma_101_mean, ...
        'T_sma_101_center_K_t', T_sma_101_center, ...
        'T_sma_101_edge_K_t', T_sma_101_edge, ...
        'mdot_active_kgps_t', mdot_active, ...
        'Q_active_m3ps_t', Q_active, ...
        'h_sma_W_m2K_t', repmat(get_option_field(sim_params, 'h_water', NaN), sample_count, 1), ...
        'Re_sma_t', repmat(get_option_field(sim_params, 'Re', NaN), sample_count, 1), ...
        'T_chip_K_t', T_chip, ...
        'T_cold_load_K_t', T_chip, ...
        'T_chip_fluid_in_K_t', T_chip_fluid_in, ...
        'T_chip_fluid_out_K_t', T_chip_fluid_out, ...
        'T_cold_hx_inlet_fluid_K_t', T_transit_pipe_outlet, ...
        'T_cold_hx_outlet_fluid_K_t', T_chip_fluid_out, ...
        'T_transit_pipe_inlet_K_t', T_chip_fluid_in, ...
        'T_transit_pipe_outlet_K_t', T_transit_pipe_outlet, ...
        'T_stage4_CHEX_pre_transit_fluid_K_t', T_stage4_CHEX_pre_transit, ...
        'T_stage4_CHEX_inlet_fluid_K_t', T_stage4_CHEX_inlet, ...
        'T_stage4_CHEX_outlet_fluid_K_t', T_stage4_CHEX_outlet, ...
        'stage4_CHEX_inlet_probe_source', stage4_CHEX_inlet_source, ...
        'stage4_CHEX_outlet_probe_source', stage4_CHEX_outlet_source, ...
        'chip_heat_W_t', repmat(chip_heat_W, sample_count, 1), ...
        'chip_fluid_G_W_per_K_t', repmat(chip_fluid_G, sample_count, 1), ...
        'Qdot_chip_to_fluid_W_t', Qdot_chip_to_fluid, ...
        'Qdot_cold_load_to_cold_sink_W_t', Qdot_chip_to_fluid, ...
        'Qdot_chip_to_fluid_method', 'deprecated_alias_for_cold_load_to_cold_sink_conductance', ...
        'Qdot_cold_load_to_cold_sink_method', 'cold_load_to_cold_sink_G_times_cold_load_minus_cold_sink_temperature', ...
        'T_hot_sink_K_t', T_hot_sink, ...
        'T_hot_hx_inlet_fluid_K_t', T_hot_hx_inlet, ...
        'T_hot_hx_outlet_fluid_K_t', T_hot_hx_outlet, ...
        'T_cold_sink_K_t', T_cold_sink, ...
        'T_cold_sink_pipe_thermal_port_K_t', T_cold_sink_pipe_thermal_port, ...
        'T_cold_return_pipe_thermal_port_K_t', T_cold_return_pipe_thermal_port, ...
        'Qdot_cold_sink_mass_to_pipe_W_t', Qdot_cold_sink_mass_to_pipe, ...
        'Qdot_cold_sink_mass_to_hx_pipe_W_t', Qdot_cold_sink_mass_to_pipe, ...
        'Q_cold_sink_mass_to_pipe_trapz_J', Q_cold_sink_mass_to_pipe_trapz_J, ...
        'Q_cold_sink_mass_to_hx_pipe_trapz_J', Q_cold_sink_mass_to_pipe_trapz_J, ...
        'Qdot_cold_sink_mass_to_pipe_semantics', ...
            get_option_field(observability, 'Qdot_cold_sink_mass_to_pipe_semantics', ...
            'ColdSinkMass-to-ColdSinkPipe thermal-link heat-flow sensor; sign must be validated by audit before pass/fail use.'), ...
        'T_cold_sink_pipe_thermal_port_semantics', ...
            get_option_field(observability, 'cold_sink_pipe_thermal_port_temp_semantics', ...
            'ColdSinkPipe thermal conserving port connected to ColdSinkFluidLink and ColdSinkMass.'), ...
        'T_cold_return_pipe_thermal_port_semantics', ...
            get_option_field(observability, 'cold_return_pipe_thermal_port_temp_semantics', ...
            'ColdSinkReturnPipe thermal conserving port intentionally not instrumented; use return fluid probes.'), ...
        'T_cold_supply_K_t', T_cold_supply, ...
        'T_cold_return_K_t', T_cold_return, ...
        'T_cold_return_inlet_fluid_K_t', T_cold_return_inlet, ...
        'T_cold_return_outlet_fluid_K_t', T_cold_return_outlet, ...
        'T_cold_supply_semantics', cold_supply_semantics, ...
        'T_cold_return_semantics', cold_return_semantics, ...
        'T_probe_v1_cold_inlet_cold_buffer_side_K_t', T_probe_v1_cold_inlet_cold_buffer_side, ...
        'T_probe_v1_cold_inlet_sma_side_K_t', T_probe_v1_cold_inlet_sma_side, ...
        'T_probe_sma_stage2_port1_v1_side_K_t', T_probe_sma_stage2_port1_v1_side, ...
        'T_probe_sma_stage2_port2_v3_side_K_t', T_probe_sma_stage2_port2_v3_side, ...
        'T_probe_v3_sma_to_hot_sma_side_K_t', T_probe_v3_sma_to_hot_sma_side, ...
        'T_probe_v3_sma_to_hot_hot_hx_side_K_t', T_probe_v3_sma_to_hot_hot_hx_side, ...
        'T_probe_v4_hot_inlet_hot_buffer_side_K_t', T_probe_v4_hot_inlet_hot_buffer_side, ...
        'T_probe_v4_hot_inlet_sma_side_K_t', T_probe_v4_hot_inlet_sma_side, ...
        'T_probe_sma_stage4_port3_v4_side_K_t', T_probe_sma_stage4_port3_v4_side, ...
        'T_probe_sma_stage4_port4_v6_side_K_t', T_probe_sma_stage4_port4_v6_side, ...
        'T_probe_v6_sma_to_cold_hx_sma_side_K_t', T_probe_v6_sma_to_cold_hx_sma_side, ...
        'T_probe_v6_sma_to_cold_hx_cold_hx_side_K_t', T_probe_v6_sma_to_cold_hx_cold_hx_side, ...
        'cold_hx_inlet_fluid_semantics', 'R68 true CHEX inlet: TransitPipe_V6_to_CHEX.LConn / ColdSinkHXPipe.RConn after SMA-to-CHEX transit', ...
        'cold_hx_outlet_fluid_semantics', 'R68 true CHEX outlet: ColdSinkHXPipe.LConn before adiabatic ColdSinkReturnPipe', ...
        'stage4_CHEX_inlet_fluid_semantics', 'canonical stage-4 CHEX inlet: TransitPipe_V6_to_CHEX.LConn / ColdSinkHXPipe.RConn', ...
        'stage4_CHEX_outlet_fluid_semantics', 'canonical stage-4 CHEX outlet: ColdSinkHXPipe.LConn before ColdSinkReturnPipe; not the return-to-buffer Conn1 probe', ...
        'cold_hx_inlet_fluid_first_K', cold_hx_inlet_stats.first, ...
        'cold_hx_inlet_fluid_min_K', cold_hx_inlet_stats.min, ...
        'cold_hx_inlet_fluid_max_K', cold_hx_inlet_stats.max, ...
        'cold_hx_inlet_fluid_last_K', cold_hx_inlet_stats.last, ...
        'cold_hx_outlet_fluid_first_K', cold_hx_outlet_stats.first, ...
        'cold_hx_outlet_fluid_min_K', cold_hx_outlet_stats.min, ...
        'cold_hx_outlet_fluid_max_K', cold_hx_outlet_stats.max, ...
        'cold_hx_outlet_fluid_last_K', cold_hx_outlet_stats.last, ...
        'stage4_CHEX_inlet_fluid_first_K', stage4_CHEX_inlet_stats.first, ...
        'stage4_CHEX_inlet_fluid_min_K', stage4_CHEX_inlet_stats.min, ...
        'stage4_CHEX_inlet_fluid_max_K', stage4_CHEX_inlet_stats.max, ...
        'stage4_CHEX_inlet_fluid_last_K', stage4_CHEX_inlet_stats.last, ...
        'stage4_CHEX_outlet_fluid_first_K', stage4_CHEX_outlet_stats.first, ...
        'stage4_CHEX_outlet_fluid_min_K', stage4_CHEX_outlet_stats.min, ...
        'stage4_CHEX_outlet_fluid_max_K', stage4_CHEX_outlet_stats.max, ...
        'stage4_CHEX_outlet_fluid_last_K', stage4_CHEX_outlet_stats.last, ...
        'probe_timeseries_complete', all(isfinite(T_sma_fluid_in)) && ...
            all(isfinite(T_sma_fluid_out)) && all(isfinite(T_chip)) && ...
            all(isfinite(T_hot_sink)) && all(isfinite(T_cold_sink)));
end

function stats = series_stats(values)
    values = values(:);
    finite_mask = isfinite(values);
    finite_values = values(finite_mask);
    if isempty(finite_values)
        stats = struct('first', NaN, 'min', NaN, 'max', NaN, 'last', NaN);
        return;
    end
    first_idx = find(finite_mask, 1, 'first');
    last_idx = find(finite_mask, 1, 'last');
    stats = struct( ...
        'first', values(first_idx), ...
        'min', min(finite_values), ...
        'max', max(finite_values), ...
        'last', values(last_idx));
end

function values = resample_logged_scalar(simOut, var_names, t_target, fallback_value)
    if isempty(var_names)
        values = repmat(NaN, numel(t_target), 1);
        return;
    end
    [t_raw, v_raw] = extract_logged_series(simOut, var_names);
    if numel(t_raw) >= 2 && numel(v_raw) == numel(t_raw)
        values = interp_series(t_raw, v_raw, t_target);
    elseif isfinite(fallback_value)
        values = repmat(fallback_value, numel(t_target), 1);
    else
        values = repmat(NaN, numel(t_target), 1);
    end
end

function [time, matrix] = extract_logged_matrix_series(simOut, var_name, expected_count)
    time = [];
    matrix = [];
    if isempty(var_name) || ~isprop(simOut, var_name)
        return;
    end
    logged = simOut.(var_name);
    if isa(logged, 'timeseries')
        time = logged.Time(:);
        matrix = normalize_matrix_series_data(logged.Data, numel(time), expected_count);
        return;
    end
    if isstruct(logged)
        if isfield(logged, 'time')
            time = logged.time(:);
        elseif isfield(logged, 'Time')
            time = logged.Time(:);
        else
            time = [];
        end
        if isfield(logged, 'signals') && isfield(logged.signals, 'values')
            matrix = normalize_matrix_series_data(logged.signals.values, numel(time), expected_count);
        elseif isfield(logged, 'Data')
            matrix = normalize_matrix_series_data(logged.Data, numel(time), expected_count);
        end
    end
end

function matrix = normalize_matrix_series_data(data, expected_length, expected_count)
    data = squeeze(double(data));
    if isempty(data)
        matrix = [];
        return;
    end
    if isvector(data)
        vec = data(:).';
        if numel(vec) == expected_count
            matrix = repmat(vec, max(expected_length, 1), 1);
        else
            matrix = vec(:);
        end
        return;
    end
    if ndims(data) > 2
        data = reshape(data, size(data, 1), []);
    end
    if size(data, 1) == expected_length
        matrix = data;
    elseif size(data, 2) == expected_length
        matrix = data.';
    elseif size(data, 1) == expected_count
        matrix = data.';
    else
        matrix = data;
    end
end

function sampled = resample_matrix_series(t_raw, matrix_raw, t_target)
    if isempty(t_raw) || isempty(matrix_raw)
        sampled = [];
        return;
    end
    t_raw = t_raw(:);
    if size(matrix_raw, 1) ~= numel(t_raw) && size(matrix_raw, 2) == numel(t_raw)
        matrix_raw = matrix_raw.';
    end
    sampled = NaN(numel(t_target), size(matrix_raw, 2));
    for col = 1:size(matrix_raw, 2)
        sampled(:, col) = interp_series(t_raw, matrix_raw(:, col), t_target);
    end
end

function report = export_simulink_profiler_top30_if_requested(simOut, exchange_options, stage_config)
    report = struct('enabled', false, 'success', false, 'csv_path', '', ...
        'row_count', 0, 'error_message', '');
    if ~logical(get_option_field(exchange_options, 'simulink_profiler_export_top30', false))
        return;
    end
    report.enabled = true;
    csv_path = char(string(get_option_field(exchange_options, ...
        'simulink_profiler_top30_csv_path', '')));
    if isempty(csv_path)
        outputs_dir = char(string(get_option_field(exchange_options, 'outputs_dir', pwd)));
        csv_path = fullfile(outputs_dir, sprintf('simulink_profiler_top30_cycle%03d_stage%02d.csv', ...
            get_option_field(get_option_field(exchange_options, 'runtime', struct()), 'cycle_index', 0), ...
            get_option_field(stage_config, 'stage_index', 0)));
    end
    report.csv_path = csv_path;
    try
        ensure_local_dir(fileparts(csv_path));
        profiler_data = extract_simulink_profiler_data(simOut);
        if isempty(profiler_data)
            rows = profiler_failure_rows('SimulationMetadata.TimingInfo.ProfilerData was not present.');
        else
            save(strrep(csv_path, '.csv', '.mat'), 'profiler_data');
            rows = profiler_data_to_rows(profiler_data);
            if height(rows) > 0
                block_mask = contains(rows.block_path, "/") | contains(rows.block_path, "\");
                if sum(block_mask) >= 30
                    rows = rows(block_mask, :);
                end
                rows = sortrows(rows, {'self_time_s', 'total_time_s'}, {'descend', 'descend'});
                rows = rows(1:min(30, height(rows)), :);
                rows.rank = (1:height(rows))';
                rows.pct_of_total = 100 * rows.total_time_s ./ max(max(rows.total_time_s), eps);
                rows = movevars(rows, 'rank', 'Before', 1);
            else
                rows = profiler_failure_rows('ProfilerData was present, but no UINode/ExecNode rows were extractable.');
            end
        end
        writetable(rows, csv_path);
        report.row_count = height(rows);
        report.success = height(rows) > 0 && ~strcmp(string(rows.block_path(1)), "not_generated");
        if ~report.success && any(strcmp(rows.Properties.VariableNames, 'error_message'))
            report.error_message = char(rows.error_message(1));
        end
    catch ME
        report.error_message = ME.message;
        rows = profiler_failure_rows(ME.message);
        ensure_local_dir(fileparts(csv_path));
        writetable(rows, csv_path);
        report.row_count = height(rows);
    end
end

function profiler_data = extract_simulink_profiler_data(simOut)
    profiler_data = [];
    try
        timing_info = simOut.SimulationMetadata.TimingInfo;
        if isstruct(timing_info) && isfield(timing_info, 'ProfilerData') && ...
                isa(timing_info.ProfilerData, 'Simulink.profiler.Data')
            profiler_data = timing_info.ProfilerData;
            return;
        end
        if isobject(timing_info) && isprop(timing_info, 'ProfilerData') && ...
                isa(timing_info.ProfilerData, 'Simulink.profiler.Data')
            profiler_data = timing_info.ProfilerData;
            return;
        end
    catch
    end
end

function rows = profiler_data_to_rows(profiler_data)
    rows = profiler_empty_rows();
    try
        rows = [rows; profiler_ui_node_rows(profiler_data.rootUINode)]; %#ok<AGROW>
    catch
    end
    if height(rows) == 0
        try
            rows = [rows; profiler_exec_node_rows(profiler_data.rootExecNode)]; %#ok<AGROW>
        catch
        end
    end
end

function rows = profiler_ui_node_rows(nodes)
    rows = profiler_empty_rows();
    for idx = 1:numel(nodes)
        node = nodes(idx);
        row = table(string(get_object_property(node, 'path', '')), "UINode", ...
            get_object_property(node, 'selfTime', NaN), ...
            get_object_property(node, 'totalTime', NaN), ...
            get_object_property(node, 'numberOfCalls', NaN), NaN, ...
            'VariableNames', {'block_path', 'block_type', 'self_time_s', ...
            'total_time_s', 'num_calls', 'pct_of_total'});
        rows = [rows; row]; %#ok<AGROW>
        children = get_object_property(node, 'children', []);
        if ~isempty(children)
            rows = [rows; profiler_ui_node_rows(children)]; %#ok<AGROW>
        end
    end
end

function rows = profiler_exec_node_rows(nodes)
    rows = profiler_empty_rows();
    for idx = 1:numel(nodes)
        node = nodes(idx);
        path_value = get_object_property(node, 'objectPath', '');
        if isempty(char(string(path_value)))
            path_value = get_object_property(node, 'location', '');
        end
        row = table(string(path_value), "ExecNode", ...
            get_object_property(node, 'selfTime', NaN), ...
            get_object_property(node, 'totalTime', NaN), ...
            get_object_property(node, 'numberOfCalls', NaN), NaN, ...
            'VariableNames', {'block_path', 'block_type', 'self_time_s', ...
            'total_time_s', 'num_calls', 'pct_of_total'});
        rows = [rows; row]; %#ok<AGROW>
        children = get_object_property(node, 'children', []);
        if ~isempty(children)
            rows = [rows; profiler_exec_node_rows(children)]; %#ok<AGROW>
        end
    end
end

function rows = profiler_empty_rows()
    rows = table(string.empty(0, 1), string.empty(0, 1), zeros(0, 1), ...
        zeros(0, 1), zeros(0, 1), zeros(0, 1), ...
        'VariableNames', {'block_path', 'block_type', 'self_time_s', ...
        'total_time_s', 'num_calls', 'pct_of_total'});
end

function rows = profiler_failure_rows(message)
    rows = table((1:30)', repmat("not_generated", 30, 1), repmat("not_available", 30, 1), ...
        NaN(30, 1), NaN(30, 1), NaN(30, 1), NaN(30, 1), repmat(string(message), 30, 1), ...
        'VariableNames', {'rank', 'block_path', 'block_type', 'self_time_s', ...
        'total_time_s', 'num_calls', 'pct_of_total', 'error_message'});
end

function value = get_object_property(obj, property_name, default_value)
    try
        if isobject(obj) && isprop(obj, property_name)
            value = obj.(property_name);
        else
            value = default_value;
        end
    catch
        value = default_value;
    end
end

function value = get_option_field(s, field_name, default_value)
    if isstruct(s) && isfield(s, field_name) && ~isempty(s.(field_name))
        value = s.(field_name);
    else
        value = default_value;
    end
end

function mode = normalize_simulation_mode(mode_value)
    mode = lower(strtrim(char(string(mode_value))));
    switch mode
        case {'normal', ''}
            mode = 'normal';
        case 'accelerator'
            mode = 'accelerator';
        case {'rapid', 'rapid-accelerator', 'rapid_accelerator'}
            mode = 'rapid-accelerator';
        otherwise
            error('Run_Simulink_Exchange_Hook:UnsupportedSimulationMode', ...
            'Unsupported simulation_mode: %s', char(string(mode_value)));
    end
end

function report = disabled_simstate_chain_report()
    report = struct( ...
        'enabled', false, ...
        'load_attempted', false, ...
        'loaded', false, ...
        'source_stage_index', NaN, ...
        'source_field', '', ...
        'initial_state_class', '', ...
        'sma_injection_status', 'abandoned_r24', ...
        'sma_injection_block_count', 0, ...
        'error_message', 'SimState chain abandoned in R24 A28 decision.');
end

function report = disabled_simstate_final_report()
    report = struct( ...
        'saved', false, ...
        'final_state_class', '', ...
        'error_message', 'SimState final-state export abandoned in R24 A28 decision.');
end

function [simIn, report] = configure_r25_simstate_test(simIn, exchange_options)
    report = struct( ...
        'save_enabled', logical(get_option_field(exchange_options, ...
        'r25_simstate_test_save_complete', false)), ...
        'load_enabled', false, ...
        'loaded', false, ...
        'final_saved', false, ...
        'final_class', '', ...
        'error_message', '');
    if report.save_enabled
        try
            simIn = simIn.setModelParameter('SaveFinalState', 'on');
            simIn = simIn.setModelParameter('FinalStateName', 'xfinal');
            simIn = simIn.setModelParameter('SaveCompleteFinalSimState', 'on');
        catch ME
            report.error_message = ['save_config_failed: ' ME.message];
        end
    end
    initial_state = get_option_field(exchange_options, 'r25_simstate_test_initial_state', []);
    if ~isempty(initial_state)
        report.load_enabled = true;
        try
            simIn = simIn.setInitialState(initial_state);
            report.loaded = true;
        catch ME
            report.error_message = ['load_config_failed: ' ME.message];
        end
    end
end

function [report, final_state] = finalize_r25_simstate_test(simOut, report)
    final_state = [];
    if ~report.save_enabled
        return;
    end
    try
        final_state = simOut.xfinal;
    catch
        try
            final_state = simOut.get('xfinal');
        catch ME
            report.error_message = ['final_state_missing: ' ME.message];
        end
    end
    if ~isempty(final_state)
        report.final_saved = true;
        report.final_class = class(final_state);
    end
end

function [simOut, retry_report, final_sim_params] = run_simulation_with_init_retry( ...
        simIn, stage_config, exchange_options, sim_params)
    max_retries = round(get_option_field(exchange_options, 'simulink_init_retry_count', 2));
    max_retries = max(0, max_retries);
    pause_s = get_option_field(exchange_options, 'simulink_init_retry_pause_s', 0.25);
    if ~isfinite(pause_s) || pause_s < 0
        pause_s = 0.0;
    end
    close_model_between_attempts = logical(get_option_field(exchange_options, ...
        'simulink_init_retry_bdclose', true));
    adaptive_fallback_enabled = logical(get_option_field(exchange_options, ...
        'simulink_init_adaptive_fallback_enabled', true));
    fallback_profiles = build_init_retry_fallback_profiles(exchange_options);
    if adaptive_fallback_enabled && max_retries > 0
        max_retries = max(max_retries, numel(fallback_profiles));
    end

    retry_report = struct( ...
        'attempt_count', 0, ...
        'max_retries', max_retries, ...
        'retry_used', false, ...
        'success', false, ...
        'adaptive_fallback_enabled', adaptive_fallback_enabled, ...
        'adaptive_fallback_used', false, ...
        'adaptive_fallback_attempt_count', 0, ...
        'near_zero_initialization_failure_detected', false, ...
        'successful_attempt_index', NaN, ...
        'successful_closed_valve_opening', get_option_field(sim_params, 'exchange_startup_closed_valve_opening', NaN), ...
        'successful_ramp_s', get_option_field(sim_params, 'exchange_startup_ramp_s', NaN), ...
        'successful_startup_profile', get_option_field(sim_params, 'exchange_startup_profile', ''), ...
        'attempt_closed_valve_openings', [], ...
        'attempt_ramp_s', [], ...
        'attempt_startup_profiles', {{}}, ...
        'error_identifiers', {{}}, ...
        'error_messages', {{}});

    attempt_count = max_retries + 1;
    last_error = [];
    current_simIn = simIn;
    current_sim_params = sim_params;
    fallback_index = 0;
    final_sim_params = sim_params;
    for attempt_idx = 1:attempt_count
        try
            retry_report.attempt_closed_valve_openings(end + 1) = ...
                get_option_field(current_sim_params, 'exchange_startup_closed_valve_opening', NaN);
            retry_report.attempt_ramp_s(end + 1) = ...
                get_option_field(current_sim_params, 'exchange_startup_ramp_s', NaN);
            retry_report.attempt_startup_profiles{end + 1} = ...
                get_option_field(current_sim_params, 'exchange_startup_profile', '');
            simOut = sim(current_simIn);
            retry_report.attempt_count = attempt_idx;
            retry_report.retry_used = attempt_idx > 1;
            retry_report.successful_attempt_index = attempt_idx;
            retry_report.successful_closed_valve_opening = ...
                get_option_field(current_sim_params, 'exchange_startup_closed_valve_opening', NaN);
            retry_report.successful_ramp_s = ...
                get_option_field(current_sim_params, 'exchange_startup_ramp_s', NaN);
            retry_report.successful_startup_profile = ...
                get_option_field(current_sim_params, 'exchange_startup_profile', '');
            retry_report.success = true;
            final_sim_params = current_sim_params;
            return;
        catch ME
            last_error = ME;
            retry_report.attempt_count = attempt_idx;
            retry_report.error_identifiers{end + 1} = ME.identifier;
            retry_report.error_messages{end + 1} = ME.message;
            if attempt_idx >= attempt_count
                break;
            end
            near_zero_init_failure = is_near_zero_simulink_initialization_failure(ME);
            retry_report.near_zero_initialization_failure_detected = ...
                retry_report.near_zero_initialization_failure_detected || near_zero_init_failure;
            if adaptive_fallback_enabled && near_zero_init_failure && fallback_index < numel(fallback_profiles)
                fallback_index = fallback_index + 1;
                current_sim_params = apply_init_retry_fallback_profile( ...
                    sim_params, stage_config, fallback_profiles(fallback_index), fallback_index);
                current_simIn = apply_sim_params_to_simulation_input(simIn, current_sim_params);
                retry_report.adaptive_fallback_used = true;
                retry_report.adaptive_fallback_attempt_count = fallback_index;
            end
            reset_simulink_model_for_retry(stage_config, close_model_between_attempts);
            if pause_s > 0
                pause(pause_s);
            end
        end
    end

    rethrow(last_error);
end

function simIn = apply_sim_params_to_simulation_input(simIn, sim_params)
    sim_param_names = fieldnames(sim_params);
    for idx = 1:numel(sim_param_names)
        simIn = simIn.setVariable(sim_param_names{idx}, sim_params.(sim_param_names{idx}));
    end
end

function profiles = build_init_retry_fallback_profiles(exchange_options)
    default_profiles = [1.0e-4, 0.002; 1.0e-4, 0.005; 1.0e-3, 0.010];
    raw_profiles = get_option_field(exchange_options, ...
        'simulink_init_adaptive_fallback_profiles', default_profiles);
    if ~(isnumeric(raw_profiles) && size(raw_profiles, 2) == 2)
        error('Run_Simulink_Exchange_Hook:InvalidInitFallbackProfiles', ...
            'simulink_init_adaptive_fallback_profiles must be an Nx2 numeric array [closed_opening, ramp_s].');
    end
    profiles = repmat(struct( ...
        'closed_valve_opening', NaN, ...
        'ramp_s', NaN, ...
        'profile_name', ''), 1, size(raw_profiles, 1));
    for idx = 1:size(raw_profiles, 1)
        profiles(idx).closed_valve_opening = min(max(double(raw_profiles(idx, 1)), 0.0), 1.0);
        profiles(idx).ramp_s = max(double(raw_profiles(idx, 2)), 0.0);
        profiles(idx).profile_name = sprintf('adaptive_retry_%02d_linear_valve_ramp_pressure_constant', idx);
    end
end

function sim_params = apply_init_retry_fallback_profile(sim_params, stage_config, profile, fallback_index)
    L_target = reshape(get_option_field(sim_params, 'L_valve_target', ...
        get_option_field(stage_config, 'L_valve', zeros(1, 6))), 1, []);
    stage_duration_s = get_option_field(stage_config, 'stop_time_s', NaN);
    if ~isfinite(stage_duration_s) || stage_duration_s <= 0
        stage_duration_s = max(get_option_field(sim_params, 'stop_time_s', 0.4), eps);
    end
    ramp_s = min(max(profile.ramp_s, 0.0), 0.25 * stage_duration_s);
    active_mask = abs(L_target) > 0;
    L_initial = L_target;
    L_initial(active_mask) = profile.closed_valve_opening .* sign_nonzero(L_target(active_mask));
    if ramp_s > 0 && any(active_mask)
        command_time_s = [0.0; ramp_s; stage_duration_s];
        command_values = [L_initial; L_target; L_target];
        startup_used = true;
    else
        command_time_s = [0.0; max(stage_duration_s, eps)];
        command_values = [L_target; L_target];
        ramp_s = 0.0;
        startup_used = false;
    end
    sim_params.L_valve_initial = L_initial;
    sim_params.L_valve_command = timeseries(command_values, command_time_s);
    sim_params.L_valve_command_time_s = command_time_s;
    sim_params.L_valve_command_values = command_values;
    sim_params.exchange_startup_smoothing_enabled = true;
    sim_params.exchange_startup_ramp_s = ramp_s;
    sim_params.exchange_startup_profile = profile.profile_name;
    sim_params.startup_smoothing_used = startup_used;
    sim_params.startup_smoothing_reason = sprintf( ...
        ['adaptive Simulink initialization retry fallback %d after near-zero-time ', ...
        'solver initialization failure; original physical target valve vector is unchanged'], fallback_index);
    sim_params.exchange_startup_closed_valve_opening = profile.closed_valve_opening;
    sim_params.simulink_init_adaptive_fallback_active = true;
    sim_params.simulink_init_adaptive_fallback_index = fallback_index;
    sim_params.simulink_init_adaptive_fallback_closed_valve_opening = profile.closed_valve_opening;
    sim_params.simulink_init_adaptive_fallback_ramp_s = ramp_s;
    sim_params.simulink_init_adaptive_fallback_profile = profile.profile_name;
end

function tf = is_near_zero_simulink_initialization_failure(ME)
    text = collect_exception_text(ME);
    lower_text = lower(text);
    solver_like = contains(lower_text, 'simulink:solver') || contains(lower_text, 'solver') || ...
        contains(lower_text, 'simscape') || contains(lower_text, 'initial');
    if ~solver_like
        tf = false;
        return;
    end
    number_tokens = regexp(text, '[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?', 'match');
    numeric_values = str2double(number_tokens);
    numeric_values = numeric_values(isfinite(numeric_values) & numeric_values > 0);
    tf = any(numeric_values < 1.0e-8);
end

function text = collect_exception_text(ME)
    parts = {ME.identifier, ME.message};
    try
        for idx = 1:numel(ME.cause)
            parts{end + 1} = collect_exception_text(ME.cause{idx}); %#ok<AGROW>
        end
    catch
    end
    text = strjoin(parts, newline);
end

function values = sign_nonzero(values)
    signs = sign(values);
    signs(signs == 0) = 1;
    values = signs;
end

function reset_simulink_model_for_retry(stage_config, close_model_between_attempts)
    model_name = char(string(get_option_field(stage_config, 'model_name', '')));
    model_path = char(string(get_option_field(stage_config, 'model_path', '')));
    try
        if ~isempty(model_name) && bdIsLoaded(model_name)
            try
                set_param(model_name, 'FastRestart', 'off');
            catch
            end
            if close_model_between_attempts
                bdclose(model_name);
            end
        end
    catch
    end
    if close_model_between_attempts && ~isempty(model_path)
        try
            load_system(model_path);
        catch
        end
    end
end

function T_init = extract_state_temperature(state_std)
    if isstruct(state_std) && isfield(state_std, 'T') && ~isempty(state_std.T)
        T_init = state_std.T(:);
    elseif isstruct(state_std) && isfield(state_std, 'Y') && isfield(state_std, 'T_idx')
        T_init = state_std.Y(state_std.T_idx);
    else
        X = state_std.X(:);
        node_count = numel(X) / 3;
        T_init = X(2 * node_count + (1:node_count));
    end
end

function state_std = standardize_globalxi_exchange_state(state_in)
    try
        state_std = GlobalXi_Checkpoint_To_Simulink_State(state_in);
    catch adapter_error
        if isstruct(state_in) && isfield(state_in, 'T') && ~isempty(state_in.T)
            state_std = state_in;
            return;
        end
        rethrow(adapter_error);
    end
end

function state_out = apply_temperature_to_globalxi_state(state_in, T_out)
    state_out = state_in;
    T_out = T_out(:);
    if isfield(state_out, 'Y') && isfield(state_out, 'T_idx')
        if numel(T_out) ~= numel(state_out.T_idx)
            error('Run_Simulink_Exchange_Hook:TemperatureWritebackSizeMismatch', ...
                'Expected %d T values, got %d.', numel(state_out.T_idx), numel(T_out));
        end
        state_out.Y(state_out.T_idx) = T_out;
        state_out.T = T_out;
        if isfield(state_out, 'checkpoint') && isstruct(state_out.checkpoint)
            state_out.checkpoint.Y = state_out.Y;
        end
    elseif isfield(state_out, 'T')
        state_out.T = T_out;
    else
        error('Run_Simulink_Exchange_Hook:UnsupportedStateWriteback', ...
            'State does not expose GlobalXi Y/T_idx or T fields.');
    end
end

function observability = build_observability_snapshot(stage_config, sim_params, ...
        hot_sink_temp_out, cold_sink_temp_out, chip_temp_out, ...
        hot_buffer_temp_out, cold_buffer_temp_out, ...
        hot_hx_inlet_fluid_temp_out, hot_hx_outlet_fluid_temp_out, ...
        chip_inlet_fluid_temp_out, chip_outlet_fluid_temp_out, ...
        cold_hx_inlet_fluid_temp_out, cold_hx_outlet_fluid_temp_out, ...
        sma_hold_inlet_fluid_temp_out, sma_hold_outlet_fluid_temp_out, ...
        sma_cooldown_inlet_fluid_temp_out, sma_cooldown_outlet_fluid_temp_out, ...
        probe_v1_cold_inlet_cold_buffer_side_T_K, probe_v1_cold_inlet_sma_side_T_K, ...
        probe_v3_sma_to_hot_sma_side_T_K, probe_v3_sma_to_hot_hot_hx_side_T_K, ...
        probe_v4_hot_inlet_hot_buffer_side_T_K, probe_v4_hot_inlet_sma_side_T_K, ...
        probe_v6_sma_to_chip_sma_side_T_K, probe_v6_sma_to_chip_chip_side_T_K, ...
        mass_flow_v1_cold_inlet_kgps, mass_flow_v3_sma_to_hot_kgps, ...
        mass_flow_v4_hot_inlet_kgps, mass_flow_v6_sma_to_chip_cold_kgps)
    stage_name = get_option_field(stage_config, 'stage_name', '');
    switch stage_name
        case 'hold_exchange'
            sma_inlet_fluid_temp_out = sma_hold_inlet_fluid_temp_out;
            sma_outlet_fluid_temp_out = sma_hold_outlet_fluid_temp_out;
            sma_inlet_branch_mass_flow_kgps = mass_flow_v1_cold_inlet_kgps;
            sma_outlet_branch_mass_flow_kgps = mass_flow_v3_sma_to_hot_kgps;
            expected_active_branches = {'V1_cold_inlet', 'V3_sma_to_hot'};
        case 'cooldown_exchange'
            sma_inlet_fluid_temp_out = sma_cooldown_inlet_fluid_temp_out;
            sma_outlet_fluid_temp_out = sma_cooldown_outlet_fluid_temp_out;
            sma_inlet_branch_mass_flow_kgps = mass_flow_v4_hot_inlet_kgps;
            sma_outlet_branch_mass_flow_kgps = mass_flow_v6_sma_to_chip_cold_kgps;
            expected_active_branches = {'V4_hot_inlet', 'V6_sma_to_chip_cold'};
        otherwise
            sma_inlet_fluid_temp_out = NaN;
            sma_outlet_fluid_temp_out = NaN;
            sma_inlet_branch_mass_flow_kgps = 0.0;
            sma_outlet_branch_mass_flow_kgps = 0.0;
            expected_active_branches = {};
    end

    flow_direction_ok = true;
    if strcmp(stage_name, 'hold_exchange')
        flow_direction_ok = (mass_flow_v1_cold_inlet_kgps >= -1.0e-9) && ...
            (mass_flow_v3_sma_to_hot_kgps >= -1.0e-9);
    elseif strcmp(stage_name, 'cooldown_exchange')
        flow_direction_ok = (mass_flow_v4_hot_inlet_kgps >= -1.0e-9) && ...
            (mass_flow_v6_sma_to_chip_cold_kgps >= -1.0e-9);
    elseif isfield(stage_config, 'all_valves_closed') && stage_config.all_valves_closed
        flow_direction_ok = max(abs([mass_flow_v1_cold_inlet_kgps, mass_flow_v3_sma_to_hot_kgps, ...
            mass_flow_v4_hot_inlet_kgps, mass_flow_v6_sma_to_chip_cold_kgps])) <= 1.0e-8;
    end
    [closed_branch_flow_ratio, closed_branch_flow_ok, closed_branch_flow_ideal_ok, ...
        closed_branch_flow_max_kgps, active_branch_flow_ref_kgps] = ...
        compute_closed_branch_flow_metrics(stage_name, mass_flow_v1_cold_inlet_kgps, ...
        mass_flow_v3_sma_to_hot_kgps, mass_flow_v4_hot_inlet_kgps, ...
        mass_flow_v6_sma_to_chip_cold_kgps, ...
        get_option_field(stage_config, 'closed_branch_flow_warning_threshold', 1.0e-2), ...
        get_option_field(stage_config, 'closed_branch_flow_ideal_threshold', 1.0e-3));
    cold_load_model_version = char(string(get_option_field(sim_params, ...
        'cold_load_model_version', 'legacy_inline_chip')));
    cold_load_mode = char(string(get_option_field(sim_params, 'cold_load_mode', 'constant_load')));
    cold_load_temp_in = get_option_field(stage_config, 'cold_load_T_in', ...
        get_option_field(stage_config, 'chip_T_in', NaN));
    cold_load_temp_out = chip_temp_out;
    cold_load_body_temperature_change_K = cold_load_temp_out - cold_load_temp_in;
    cold_load_to_cold_sink_G = get_option_field(sim_params, 'cold_load_to_cold_sink_G_W_per_K', ...
        get_option_field(sim_params, 'chip_fluid_G_effective_W_per_K', NaN));
    Qdot_cold_load_to_cold_sink_terminal_W = cold_load_to_cold_sink_G * ...
        (cold_load_temp_out - cold_sink_temp_out);
    cold_hx_fluid_endpoint_delta_K = cold_hx_outlet_fluid_temp_out - cold_hx_inlet_fluid_temp_out;
    chip_fluid_endpoint_delta_K = cold_hx_fluid_endpoint_delta_K;
    chip_fluid_temperature_gain_K = chip_fluid_endpoint_delta_K;
    chip_drop_K = get_option_field(stage_config, 'chip_T_in', NaN) - chip_temp_out;
    chip_body_temperature_drop_K = chip_drop_K;
    cold_load_contract_ok = ~strcmp(stage_name, 'cooldown_exchange') || ...
        (~isempty(cold_load_mode) && isfinite(cold_load_to_cold_sink_G));
    chip_body_cooling_ok = true; % Deprecated alias: cold load may heat or cool under external load.
    chip_heat_direction_ok = cold_load_contract_ok;
    chip_fluid_mode = char(string(get_option_field(sim_params, 'chip_fluid_coupling_mode', '')));
    chip_fluid_G = get_option_field(sim_params, 'chip_fluid_G_effective_W_per_K', NaN);
    cold_load_model_active = strcmp(cold_load_model_version, 'cold_load_external_to_chex_v1');
    stage2_chip_fluid_isolated_ok = ~strcmp(stage_name, 'hold_exchange') || ...
        cold_load_model_active || ...
        (strcmp(chip_fluid_mode, 'stage_isolated') && isfinite(chip_fluid_G) && chip_fluid_G <= 1.0e-8);
    stage2_chip_side_isolated_ok = ~strcmp(stage_name, 'hold_exchange') || ...
        (stage2_chip_fluid_isolated_ok && closed_branch_flow_ok);
    stage4_chip_cooling_ok = ~strcmp(stage_name, 'cooldown_exchange') || cold_load_contract_ok;
    probe_stage2_sma_port2_minus_port1_K = sma_hold_outlet_fluid_temp_out - sma_hold_inlet_fluid_temp_out;
    probe_stage2_hot_hx_port2_minus_port1_K = hot_hx_outlet_fluid_temp_out - hot_hx_inlet_fluid_temp_out;
    probe_stage4_sma_port4_minus_port3_K = sma_cooldown_outlet_fluid_temp_out - sma_cooldown_inlet_fluid_temp_out;
    probe_stage4_chip_conn2_minus_sma_port4_K = chip_inlet_fluid_temp_out - sma_cooldown_outlet_fluid_temp_out;
    probe_stage4_chip_junction_minus_chip_conn2_K = chip_outlet_fluid_temp_out - chip_inlet_fluid_temp_out;
    probe_stage4_cold_port_conn1_minus_chip_junction_K = cold_hx_outlet_fluid_temp_out - chip_outlet_fluid_temp_out;
    probe_stage2_v1_sma_side_minus_cold_side_K = probe_v1_cold_inlet_sma_side_T_K - probe_v1_cold_inlet_cold_buffer_side_T_K;
    probe_stage2_v3_hot_side_minus_sma_side_K = probe_v3_sma_to_hot_hot_hx_side_T_K - probe_v3_sma_to_hot_sma_side_T_K;
    probe_stage4_v4_sma_side_minus_hot_side_K = probe_v4_hot_inlet_sma_side_T_K - probe_v4_hot_inlet_hot_buffer_side_T_K;
    probe_stage4_sma_port3_minus_v4_sma_side_K = sma_cooldown_inlet_fluid_temp_out - probe_v4_hot_inlet_sma_side_T_K;
    probe_stage4_v6_chip_side_minus_sma_side_K = probe_v6_sma_to_chip_chip_side_T_K - probe_v6_sma_to_chip_sma_side_T_K;
    probe_stage4_chip_conn2_minus_v6_chip_side_K = chip_inlet_fluid_temp_out - probe_v6_sma_to_chip_chip_side_T_K;

    observability = struct( ...
        'hot_sink_temp_out', hot_sink_temp_out, ...
        'cold_sink_temp_out', cold_sink_temp_out, ...
        'chip_temp_out', chip_temp_out, ...
        'cold_load_temp_in', cold_load_temp_in, ...
        'cold_load_temp_out', cold_load_temp_out, ...
        'cold_load_temperature_change_K', cold_load_body_temperature_change_K, ...
        'cold_load_mode', cold_load_mode, ...
        'cold_load_model_version', cold_load_model_version, ...
        'cold_load_heat_W', get_option_field(sim_params, 'cold_load_heat_W', NaN), ...
        'cold_load_C_J_per_K', get_option_field(sim_params, 'cold_load_C_J_per_K', NaN), ...
        'cold_load_to_cold_sink_G_W_per_K', cold_load_to_cold_sink_G, ...
        'cold_load_ambient_G_W_per_K', get_option_field(sim_params, 'cold_load_ambient_G_W_per_K', NaN), ...
        'Qdot_cold_load_to_cold_sink_terminal_W', Qdot_cold_load_to_cold_sink_terminal_W, ...
        'cold_load_contract_ok', cold_load_contract_ok, ...
        'hot_buffer_temp_out', hot_buffer_temp_out, ...
        'cold_buffer_temp_out', cold_buffer_temp_out, ...
        'probe_semantics_version', 'fixed_port_probe_semantics_v3_cold_load_chex', ...
        'probe_root_hot_buffer_fluid_T_K', hot_buffer_temp_out, ...
        'probe_root_cold_buffer_fluid_T_K', cold_buffer_temp_out, ...
        'probe_hot_sink_solid_T_K', hot_sink_temp_out, ...
        'probe_cold_sink_solid_T_K', cold_sink_temp_out, ...
        'probe_chip_solid_T_K', chip_temp_out, ...
        'probe_cold_load_solid_T_K', cold_load_temp_out, ...
        'probe_sma_stage2_port1_v1_side_T_K', sma_hold_inlet_fluid_temp_out, ...
        'probe_sma_stage2_port2_v3_side_T_K', sma_hold_outlet_fluid_temp_out, ...
        'probe_sma_stage4_port3_v4_side_T_K', sma_cooldown_inlet_fluid_temp_out, ...
        'probe_sma_stage4_port4_v6_side_T_K', sma_cooldown_outlet_fluid_temp_out, ...
        'probe_hot_hx_port1_v3_side_T_K', hot_hx_inlet_fluid_temp_out, ...
        'probe_hot_hx_port2_v2_return_side_T_K', hot_hx_outlet_fluid_temp_out, ...
        'probe_chip_pipe_port_conn2_v6_sma_side_T_K', chip_inlet_fluid_temp_out, ...
        'probe_chip_to_cold_junction_T_K', chip_outlet_fluid_temp_out, ...
        'probe_cold_hx_port_conn1_v5_return_side_T_K', cold_hx_outlet_fluid_temp_out, ...
        'probe_v1_cold_inlet_cold_buffer_side_T_K', probe_v1_cold_inlet_cold_buffer_side_T_K, ...
        'probe_v1_cold_inlet_sma_side_T_K', probe_v1_cold_inlet_sma_side_T_K, ...
        'probe_v3_sma_to_hot_sma_side_T_K', probe_v3_sma_to_hot_sma_side_T_K, ...
        'probe_v3_sma_to_hot_hot_hx_side_T_K', probe_v3_sma_to_hot_hot_hx_side_T_K, ...
        'probe_v4_hot_inlet_hot_buffer_side_T_K', probe_v4_hot_inlet_hot_buffer_side_T_K, ...
        'probe_v4_hot_inlet_sma_side_T_K', probe_v4_hot_inlet_sma_side_T_K, ...
        'probe_v6_sma_to_chip_sma_side_T_K', probe_v6_sma_to_chip_sma_side_T_K, ...
        'probe_v6_sma_to_chip_chip_side_T_K', probe_v6_sma_to_chip_chip_side_T_K, ...
        'probe_stage2_sma_port2_minus_port1_K', probe_stage2_sma_port2_minus_port1_K, ...
        'probe_stage2_hot_hx_port2_minus_port1_K', probe_stage2_hot_hx_port2_minus_port1_K, ...
        'probe_stage4_sma_port4_minus_port3_K', probe_stage4_sma_port4_minus_port3_K, ...
        'probe_stage4_chip_conn2_minus_sma_port4_K', probe_stage4_chip_conn2_minus_sma_port4_K, ...
        'probe_stage4_chip_junction_minus_chip_conn2_K', probe_stage4_chip_junction_minus_chip_conn2_K, ...
        'probe_stage4_cold_port_conn1_minus_chip_junction_K', probe_stage4_cold_port_conn1_minus_chip_junction_K, ...
        'probe_stage2_v1_sma_side_minus_cold_side_K', probe_stage2_v1_sma_side_minus_cold_side_K, ...
        'probe_stage2_v3_hot_side_minus_sma_side_K', probe_stage2_v3_hot_side_minus_sma_side_K, ...
        'probe_stage4_v4_sma_side_minus_hot_side_K', probe_stage4_v4_sma_side_minus_hot_side_K, ...
        'probe_stage4_sma_port3_minus_v4_sma_side_K', probe_stage4_sma_port3_minus_v4_sma_side_K, ...
        'probe_stage4_v6_chip_side_minus_sma_side_K', probe_stage4_v6_chip_side_minus_sma_side_K, ...
        'probe_stage4_chip_conn2_minus_v6_chip_side_K', probe_stage4_chip_conn2_minus_v6_chip_side_K, ...
        'hot_hx_inlet_fluid_temp_out', hot_hx_inlet_fluid_temp_out, ...
        'hot_hx_outlet_fluid_temp_out', hot_hx_outlet_fluid_temp_out, ...
        'chip_inlet_fluid_temp_out', chip_inlet_fluid_temp_out, ...
        'chip_outlet_fluid_temp_out', chip_outlet_fluid_temp_out, ...
        'cold_hx_inlet_fluid_temp_out', cold_hx_inlet_fluid_temp_out, ...
        'cold_hx_outlet_fluid_temp_out', cold_hx_outlet_fluid_temp_out, ...
        'sma_hold_inlet_fluid_temp_out', sma_hold_inlet_fluid_temp_out, ...
        'sma_hold_outlet_fluid_temp_out', sma_hold_outlet_fluid_temp_out, ...
        'sma_cooldown_inlet_fluid_temp_out', sma_cooldown_inlet_fluid_temp_out, ...
        'sma_cooldown_outlet_fluid_temp_out', sma_cooldown_outlet_fluid_temp_out, ...
        'sma_inlet_fluid_temp_out', sma_inlet_fluid_temp_out, ...
        'sma_outlet_fluid_temp_out', sma_outlet_fluid_temp_out, ...
        'mass_flow_v1_cold_inlet_kgps', mass_flow_v1_cold_inlet_kgps, ...
        'mass_flow_v3_sma_to_hot_kgps', mass_flow_v3_sma_to_hot_kgps, ...
        'mass_flow_v4_hot_inlet_kgps', mass_flow_v4_hot_inlet_kgps, ...
        'mass_flow_v6_sma_to_chip_cold_kgps', mass_flow_v6_sma_to_chip_cold_kgps, ...
        'sma_inlet_branch_mass_flow_kgps', sma_inlet_branch_mass_flow_kgps, ...
        'sma_outlet_branch_mass_flow_kgps', sma_outlet_branch_mass_flow_kgps, ...
        'expected_active_branches', {expected_active_branches}, ...
        'flow_direction_ok', flow_direction_ok, ...
        'closed_branch_flow_ratio', closed_branch_flow_ratio, ...
        'closed_branch_flow_ok', closed_branch_flow_ok, ...
        'closed_branch_flow_ideal_ok', closed_branch_flow_ideal_ok, ...
        'closed_branch_flow_warning_threshold', get_option_field(stage_config, 'closed_branch_flow_warning_threshold', 1.0e-2), ...
        'closed_branch_flow_ideal_threshold', get_option_field(stage_config, 'closed_branch_flow_ideal_threshold', 1.0e-3), ...
        'closed_branch_flow_max_kgps', closed_branch_flow_max_kgps, ...
        'active_branch_flow_ref_kgps', active_branch_flow_ref_kgps, ...
        'chip_fluid_temperature_gain_K', chip_fluid_temperature_gain_K, ...
        'cold_hx_fluid_endpoint_delta_K', cold_hx_fluid_endpoint_delta_K, ...
        'cold_hx_fluid_endpoint_delta_semantics', 'simultaneous_CHEX_spatial_endpoint_delta', ...
        'chip_fluid_endpoint_delta_K', chip_fluid_endpoint_delta_K, ...
        'chip_fluid_endpoint_delta_semantics', 'deprecated_alias_for_cold_hx_fluid_endpoint_delta_K', ...
        'chip_fluid_temperature_gain_semantics', 'deprecated_alias_for_CHEX_spatial_endpoint_delta', ...
        'chip_fluid_endpoint_delta_used_for_stage4_cooling_ok', false, ...
        'chip_body_temperature_drop_K', chip_body_temperature_drop_K, ...
        'chip_body_cooling_ok', chip_body_cooling_ok, ...
        'stage4_chip_cooling_basis', 'deprecated_alias; formal cold-load check uses cold_load_contract_ok', ...
        'chip_heat_direction_ok', chip_heat_direction_ok, ...
        'cold_load_model_active', cold_load_model_active, ...
        'stage2_chip_fluid_isolated_ok', stage2_chip_fluid_isolated_ok, ...
        'stage2_chip_side_isolated_ok', stage2_chip_side_isolated_ok, ...
        'stage4_chip_cooling_ok', stage4_chip_cooling_ok, ...
        'semantic_warning_hold_hot_sink_cools', strcmp(stage_name, 'hold_exchange') && ...
            (hot_sink_temp_out < get_option_field(stage_config, 'hot_sink_T_in', NaN) - 1.0e-6), ...
        'semantic_warning_hold_chip_cools', false, ...
        'hot_buffer_temp_in', sim_params.hot_fluid_buffer_T_init, ...
        'cold_buffer_temp_in', sim_params.cold_fluid_buffer_T_init);
end

function [ratio, ok, ideal_ok, closed_max, active_ref] = compute_closed_branch_flow_metrics( ...
        stage_name, m_v1, m_v3, m_v4, m_v6, warning_threshold, ideal_threshold)
    if nargin < 6 || isempty(warning_threshold)
        warning_threshold = 1.0e-2;
    end
    if nargin < 7 || isempty(ideal_threshold)
        ideal_threshold = 1.0e-3;
    end
    switch char(string(stage_name))
        case 'hold_exchange'
            active = abs([m_v1, m_v3]);
            closed = abs([m_v4, m_v6]);
        case 'cooldown_exchange'
            active = abs([m_v4, m_v6]);
            closed = abs([m_v1, m_v3]);
        otherwise
            active = 0.0;
            closed = abs([m_v1, m_v3, m_v4, m_v6]);
    end
    active_ref = max(active);
    closed_max = max(closed);
    if ~isfinite(active_ref) || active_ref <= 1.0e-12
        ratio = 0.0;
    else
        ratio = closed_max / active_ref;
    end
    if ~isfinite(closed_max)
        closed_max = NaN;
    end
    is_exchange = any(strcmp(char(string(stage_name)), {'hold_exchange', 'cooldown_exchange'}));
    ok = ~is_exchange || ...
        (isfinite(ratio) && ratio <= warning_threshold);
    ideal_ok = ~is_exchange || ...
        (isfinite(ratio) && ratio <= ideal_threshold);
end

function energy_audit = build_energy_audit(sim_params, observability, stage_config, strip_geometry, ...
        T_r_in, T_x_in_101, T_x_out_101, T_r_compressed, simOut, active_flow_audit)
    if nargin < 10 || isempty(active_flow_audit) || ~isstruct(active_flow_audit)
        active_flow_audit = struct();
    end
    hot_sink_delta_energy_J = sim_params.hot_sink_C_J_per_K * ...
        (observability.hot_sink_temp_out - sim_params.hot_sink_T_init);
    cold_sink_delta_energy_J = sim_params.cold_sink_C_J_per_K * ...
        (observability.cold_sink_temp_out - sim_params.cold_sink_T_init);
    cold_load_delta_energy_J = get_option_field(sim_params, 'cold_load_C_J_per_K', ...
        sim_params.chip_C_J_per_K) * ...
        (get_option_field(observability, 'cold_load_temp_out', observability.chip_temp_out) - ...
        get_option_field(sim_params, 'cold_load_T_init', sim_params.chip_T_init));
    chip_delta_energy_J = cold_load_delta_energy_J; % Deprecated compatibility alias.
    hot_buffer_delta_energy_J = sim_params.hot_fluid_buffer_C_J_per_K * ...
        (observability.hot_buffer_temp_out - sim_params.hot_fluid_buffer_T_init);
    cold_buffer_delta_energy_J = sim_params.cold_fluid_buffer_C_J_per_K * ...
        (observability.cold_buffer_temp_out - sim_params.cold_fluid_buffer_T_init);

    strip_C = strip_geometry.strip_heat_capacity_J_per_K(:);
    T_x_in_101 = T_x_in_101(:);
    T_x_out_101 = T_x_out_101(:);
    if numel(strip_C) ~= numel(T_x_in_101) || numel(strip_C) ~= numel(T_x_out_101)
        sma_101_energy_in_J = NaN;
        sma_101_energy_out_J = NaN;
        sma_101_delta_energy_J = NaN;
    else
        sma_101_energy_in_J = sum(strip_C .* T_x_in_101);
        sma_101_energy_out_J = sum(strip_C .* T_x_out_101);
        sma_101_delta_energy_J = sma_101_energy_out_J - sma_101_energy_in_J;
    end

    radial_C = build_radial_heat_capacity_vector(numel(T_r_in), strip_geometry);
    T_r_in = T_r_in(:);
    T_r_compressed = T_r_compressed(:);
    if numel(radial_C) ~= numel(T_r_in) || numel(radial_C) ~= numel(T_r_compressed)
        sma_51_energy_in_J = NaN;
        sma_51_energy_out_J = NaN;
        sma_51_delta_energy_J = NaN;
    else
        sma_51_energy_in_J = sum(radial_C .* T_r_in);
        sma_51_energy_out_J = sum(radial_C .* T_r_compressed);
        sma_51_delta_energy_J = sma_51_energy_out_J - sma_51_energy_in_J;
    end
    compression_delta_energy_J = sma_51_energy_out_J - sma_101_energy_out_J;
    Q_sma_101_delta_J = sma_101_delta_energy_J;
    Q_sma_51_compressed_delta_J = sma_51_delta_energy_J;
    Q_sma_accepted_solver_delta_J = sma_51_delta_energy_J;
    Q_compression_projection_error_J = Q_sma_51_compressed_delta_J - Q_sma_101_delta_J;
    if isfinite(Q_sma_101_delta_J) && abs(Q_sma_101_delta_J) > 1.0e-12
        compression_projection_error_ratio = abs(Q_compression_projection_error_J) / abs(Q_sma_101_delta_J);
    elseif isfinite(Q_compression_projection_error_J)
        compression_projection_error_ratio = abs(Q_compression_projection_error_J);
    else
        compression_projection_error_ratio = NaN;
    end
    projection_energy_conservation_ok = isfinite(compression_projection_error_ratio) && ...
        compression_projection_error_ratio <= 1.0e-6;
    if isfinite(sma_101_energy_in_J) && isfinite(sum(strip_C)) && sum(strip_C) > eps
        T101_energy_weighted_mean_before_K = sma_101_energy_in_J / sum(strip_C);
        T101_energy_weighted_mean_after_K = sma_101_energy_out_J / sum(strip_C);
    else
        T101_energy_weighted_mean_before_K = NaN;
        T101_energy_weighted_mean_after_K = NaN;
    end
    if isfinite(sma_51_energy_in_J) && isfinite(sum(radial_C)) && sum(radial_C) > eps
        T51_energy_weighted_mean_before_K = sma_51_energy_in_J / sum(radial_C);
        T51_energy_weighted_mean_after_K = sma_51_energy_out_J / sum(radial_C);
    else
        T51_energy_weighted_mean_before_K = NaN;
        T51_energy_weighted_mean_after_K = NaN;
    end
    stage2_area_avg_T_before_K = mean(T_r_in(:), 'omitnan');
    stage2_area_avg_T_after_K = mean(T_r_compressed(:), 'omitnan');

    dt_s = get_option_field(stage_config, 'stop_time_s', 0.0);
    ambient_T = sim_params.ambient_T_init;
    hot_sink_mean_T = 0.5 * (sim_params.hot_sink_T_init + observability.hot_sink_temp_out);
    cold_sink_mean_T = 0.5 * (sim_params.cold_sink_T_init + observability.cold_sink_temp_out);
    cold_load_mean_T = 0.5 * (get_option_field(sim_params, 'cold_load_T_init', sim_params.chip_T_init) + ...
        get_option_field(observability, 'cold_load_temp_out', observability.chip_temp_out));
    chip_mean_T = cold_load_mean_T;
    environment_heat_into_hot_J = sim_params.hot_sink_ambient_G_W_per_K * (ambient_T - hot_sink_mean_T) * dt_s;
    environment_heat_into_cold_J = sim_params.cold_sink_ambient_G_W_per_K * (ambient_T - cold_sink_mean_T) * dt_s;
    environment_heat_into_chip_J = sim_params.chip_ambient_G_W_per_K * (ambient_T - chip_mean_T) * dt_s;
    environment_heat_into_objects_J = environment_heat_into_hot_J + environment_heat_into_cold_J + environment_heat_into_chip_J;
    cold_load_heat_source_input_J = get_option_field(sim_params, 'cold_load_heat_W', sim_params.chip_heat_W) * dt_s;
    chip_heat_source_input_J = cold_load_heat_source_input_J; % Deprecated compatibility alias.
    cold_load_to_cold_sink_G = get_option_field(sim_params, 'cold_load_to_cold_sink_G_W_per_K', ...
        get_option_field(sim_params, 'chip_fluid_G_effective_W_per_K', NaN));
    cold_load_to_cold_sink_mean_dT = cold_load_mean_T - cold_sink_mean_T;
    Q_cold_load_to_cold_sink_J = cold_load_to_cold_sink_G * cold_load_to_cold_sink_mean_dT * dt_s;
    [fluid_enthalpy_gain_J, enthalpy_audit_quality] = compute_fluid_enthalpy_gain( ...
        simOut, stage_config, sim_params, observability, dt_s);
    fluid_enthalpy_flow_J = fluid_enthalpy_gain_J;
    pipe_storage = estimate_internal_pipe_fluid_storage(sim_params, observability, stage_config);
    Q_internal_pipe_fluid_J = pipe_storage.Q_internal_pipe_fluid_J;
    Q_environment_sma_J = 0.0;
    Q_environment_sma_method = 'no_direct_sma_environment_term_in_current_model';
    topology = build_sma_flow_topology(stage_config);
    closure = build_sma_htf_closure(stage_config, observability, sma_101_delta_energy_J, ...
        fluid_enthalpy_gain_J, Q_internal_pipe_fluid_J, Q_environment_sma_J, ...
        enthalpy_audit_quality, pipe_storage.Q_internal_pipe_fluid_method, Q_environment_sma_method);
    hot_end_delivery = build_hot_end_delivery(stage_config, sim_params, observability, closure, ...
        hot_sink_delta_energy_J, hot_buffer_delta_energy_J, active_flow_audit);
    cold_end_delivery = build_cold_end_delivery(stage_config, sim_params, observability, closure, ...
        cold_sink_delta_energy_J, cold_buffer_delta_energy_J, active_flow_audit);
    theory_bound = build_exchange_theory_bound(stage_config, sim_params, observability, closure, ...
        pipe_storage, hot_end_delivery, cold_end_delivery, T_x_in_101);

    delta_vector = [hot_sink_delta_energy_J, cold_sink_delta_energy_J, chip_delta_energy_J, ...
        hot_buffer_delta_energy_J, cold_buffer_delta_energy_J];
    observable_energy_delta_sum_J = sum(delta_vector);
    total_internal_energy_delta_J = observable_energy_delta_sum_J + sma_101_delta_energy_J;
    external_energy_input_J = cold_load_heat_source_input_J + environment_heat_into_objects_J;
    energy_residual_without_fluid_enthalpy_J = total_internal_energy_delta_J - external_energy_input_J;
    raw_system_energy_residual_J = total_internal_energy_delta_J + fluid_enthalpy_gain_J - external_energy_input_J;
    if strcmpi(get_option_field(stage_config, 'stage_name', ''), 'cooldown_exchange')
        official_system_energy_residual_J = max_abs_finite([ ...
            closure.Q_sma_closure_error_stage4_J, cold_end_delivery.Q_unaccounted_stage4_J]);
    elseif strcmpi(get_option_field(stage_config, 'stage_name', ''), 'hold_exchange')
        official_system_energy_residual_J = max_abs_finite([ ...
            closure.Q_sma_closure_error_stage2_J, hot_end_delivery.Q_unaccounted_stage2_J]);
    else
        official_system_energy_residual_J = raw_system_energy_residual_J;
    end
    energy_residual_J = official_system_energy_residual_J;
    energy_audit_ok = closure.sma_htf_energy_closure_ok && projection_energy_conservation_ok;
    energy_audit_status = closure.sma_htf_energy_closure_status;
    system_energy_audit_ok = closure.sma_htf_energy_closure_ok && projection_energy_conservation_ok && ...
        (~strcmpi(get_option_field(stage_config, 'stage_name', ''), 'hold_exchange') || ...
        hot_end_delivery.stage2_hot_chain_residual_ok) && ...
        (~strcmpi(get_option_field(stage_config, 'stage_name', ''), 'cooldown_exchange') || ...
        cold_end_delivery.stage4_cold_chain_residual_ok);
    system_energy_residual_included_in_pass_fail = true;
    energy_audit_scope = 'official_projection_sma_htf_and_external_cold_end_chain';
    if strcmpi(get_option_field(stage_config, 'stage_name', ''), 'hold_exchange')
        T_sma101_min_before_hold = min_finite(T_x_in_101);
        T_sma101_min_after_hold = min_finite(T_x_out_101);
        T_radial51_min_before_hold = min_finite(T_r_in);
        T_radial51_min_after_hold = min_finite(T_r_compressed);
        min_temperature_change_source = 'hold_exchange_raw101_and_compressed51_diagnostic';
    else
        T_sma101_min_before_hold = NaN;
