    energy_audit = merge_flat_struct(energy_audit, select_pipe_storage_diagnostics(pipe_storage));
end

function hot_end = build_hot_end_delivery(stage_config, sim_params, observability, closure, ...
        hot_sink_delta_energy_J, hot_buffer_delta_energy_J, active_flow_audit)
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    is_hold = strcmpi(stage_name, 'hold_exchange');
    threshold = 0.80;

    C_sink = max(get_option_field(sim_params, 'hot_sink_C_J_per_K', NaN), 0.0);
    C_buffer = max(get_option_field(sim_params, 'hot_fluid_buffer_C_J_per_K', NaN), 0.0);
    C_pipe = max(get_option_field(sim_params, 'hot_pipe_or_HHEX_C_J_per_K', 0.0), 0.0);
    buffer_follow_sink_enabled = logical(get_option_field(sim_params, 'buffer_follow_sink_enabled', false));
    [Q_hot_fluid_buffer_effective_drift_J, hot_buffer_effective_volume_fraction, ...
        hot_buffer_effective_volume_m3, hot_buffer_numerical_volume_m3, ...
        hot_buffer_effective_drift_source] = compute_dynamic_effective_buffer_delta( ...
        hot_buffer_delta_energy_J, sim_params, active_flow_audit);
    if buffer_follow_sink_enabled
        Q_hot_fluid_buffer_simscape_drift_J = hot_buffer_delta_energy_J;
        hot_buffer_delta_energy_J_for_closure = Q_hot_fluid_buffer_effective_drift_J;
        C_buffer_for_closure = C_buffer * hot_buffer_effective_volume_fraction;
    else
        Q_hot_fluid_buffer_simscape_drift_J = NaN;
        Q_hot_fluid_buffer_effective_drift_J = hot_buffer_delta_energy_J;
        hot_buffer_effective_volume_fraction = 1.0;
        hot_buffer_effective_volume_m3 = hot_buffer_numerical_volume_m3;
        hot_buffer_effective_drift_source = 'legacy_full_buffer_storage_included';
        hot_buffer_delta_energy_J_for_closure = hot_buffer_delta_energy_J;
        C_buffer_for_closure = C_buffer;
    end
    hot_buffer_effective_C_J_per_K = C_buffer_for_closure;
    C_total = C_sink + C_buffer_for_closure + C_pipe;

    T_sink_in = get_option_field(sim_params, 'hot_sink_T_init', NaN);
    T_sink_out = get_option_field(observability, 'hot_sink_temp_out', NaN);
    T_buffer_in = get_option_field(sim_params, 'hot_fluid_buffer_T_init', T_sink_in);
    T_buffer_out = get_option_field(observability, 'hot_buffer_temp_out', T_sink_out);
    T_pipe_in = get_option_field(sim_params, 'hot_side_fluid_T_init', T_buffer_in);
    T_pipe_candidates = [ ...
        get_option_field(observability, 'hot_hx_inlet_fluid_temp_out', NaN), ...
        get_option_field(observability, 'hot_hx_outlet_fluid_temp_out', NaN)];
    finite_pipe = T_pipe_candidates(isfinite(T_pipe_candidates));
    if isempty(finite_pipe)
        T_pipe_out = T_buffer_out;
        pipe_storage_method = 'fallback_to_hot_buffer_temp_out';
    else
        T_pipe_out = mean(finite_pipe);
        pipe_storage_method = 'mean_of_HHEX_inlet_and_outlet_terminal_probes';
    end

    if C_total > 0 && all(isfinite([T_sink_in, T_sink_out, T_buffer_in, T_buffer_out, T_pipe_in, T_pipe_out]))
        T_hot_end_in = (C_sink * T_sink_in + C_buffer_for_closure * T_buffer_in + C_pipe * T_pipe_in) / C_total;
        T_hot_end_entity_out = (C_sink * T_sink_out + C_buffer_for_closure * T_buffer_out + C_pipe * T_pipe_out) / C_total;
    else
        T_hot_end_in = NaN;
        T_hot_end_entity_out = NaN;
    end

    Q_pipe_storage_J = C_pipe * (T_pipe_out - T_pipe_in);
    Q_storage_sum_J = hot_sink_delta_energy_J + hot_buffer_delta_energy_J_for_closure + Q_pipe_storage_J;
    Q_sma_htf_stage2_J = get_option_field(closure, 'Q_sma_htf_stage2_J', NaN);
    control_mode = char(string(get_option_field(sim_params, 'official_hot_end_control_mode', ...
        'external_hot_end_mixer_boundary_enthalpy_state_v1')));
    use_external_hot_mixer = contains(lower(control_mode), 'external_hot_end_mixer') || ...
        contains(lower(char(string(get_option_field(sim_params, 'official_hot_end_definition', '')))), 'external');
    hot_end_entity_is_used_for_physics = ~use_external_hot_mixer;
    hot_end_official_is_used_for_physics = true;
    [Q_hot_return_enthalpy_J, hot_enthalpy_source, hot_split] = ...
        integrate_hot_return_enthalpy(stage_config, sim_params, observability, T_hot_end_in);
    if is_hold && isfinite(Q_sma_htf_stage2_J)
        % Use the same logged SMA-HTF enthalpy integral as the SMA closure.
        % The separate terminal/probe integral remains in the split fields
        % only as a discrepancy diagnostic.
        Q_hot_return_enthalpy_J = -Q_sma_htf_stage2_J;
        hot_enthalpy_source = 'sma_htf_closure_timeseries_integral_boundary_enthalpy';
    end

    if is_hold && isfinite(Q_hot_return_enthalpy_J) && use_external_hot_mixer
        Q_external_hot_end_mixer_J = Q_hot_return_enthalpy_J;
        Q_hot_end_official_J = Q_external_hot_end_mixer_J;
        Q_hot_end_received_measured_J = Q_hot_end_official_J;
        measured_source = ['external_hot_end_mixer_boundary_enthalpy_state_v1:', hot_enthalpy_source];
        temperature_source = 'external_hot_end_mixer_boundary_enthalpy_state';
        T_hot_end_out = T_hot_end_in + Q_external_hot_end_mixer_J / max(C_total, eps);
    else
        Q_external_hot_end_mixer_J = NaN;
        Q_hot_end_official_J = Q_storage_sum_J;
        Q_hot_end_received_measured_J = Q_storage_sum_J;
        measured_source = 'measured_hot_control_volume_storage_sum';
        temperature_source = 'energy_weighted_HotSinkMass_HotFluidBuffer_HotPipe_HHEX';
        T_hot_end_out = T_hot_end_entity_out;
    end

    Q_hot_end_received_ideal_J = NaN;
    if is_hold && isfinite(Q_sma_htf_stage2_J)
        Q_hot_end_received_ideal_J = -Q_sma_htf_stage2_J;
    end
    if isfinite(Q_sma_htf_stage2_J) && isfinite(Q_hot_end_received_measured_J)
        Q_unaccounted_stage2_J = Q_sma_htf_stage2_J + Q_hot_end_received_measured_J;
    else
        Q_unaccounted_stage2_J = NaN;
    end
    if isfinite(Q_sma_htf_stage2_J) && abs(Q_sma_htf_stage2_J) > 1.0e-12
        Q_unaccounted_stage2_ratio = abs(Q_unaccounted_stage2_J) / abs(Q_sma_htf_stage2_J);
        delivery_ratio_measured = abs(Q_hot_end_received_measured_J) / abs(Q_sma_htf_stage2_J);
        delivery_ratio_ideal = abs(Q_hot_end_received_ideal_J) / abs(Q_sma_htf_stage2_J);
        measured_is_forced = isfinite(delivery_ratio_measured) && isfinite(delivery_ratio_ideal) && ...
            abs(delivery_ratio_measured - delivery_ratio_ideal) < 1.0e-10 && ...
            contains(lower(measured_source), 'ideal');
        residual_ok = isfinite(Q_unaccounted_stage2_ratio) && Q_unaccounted_stage2_ratio <= 0.20;
        delivery_pass = is_hold && ~measured_is_forced && isfinite(delivery_ratio_measured) && ...
            delivery_ratio_measured >= threshold && residual_ok;
    else
        Q_unaccounted_stage2_ratio = NaN;
        delivery_ratio_measured = NaN;
        delivery_ratio_ideal = NaN;
        measured_is_forced = false;
        residual_ok = ~is_hold;
        delivery_pass = ~is_hold;
    end

    hot_end = struct( ...
        'Q_hot_return_boundary_enthalpy_J', Q_hot_return_enthalpy_J, ...
        'Q_hot_return_positive_heating_J', hot_split.Q_hot_return_positive_heating_J, ...
        'Q_hot_return_negative_cooling_slug_J', hot_split.Q_hot_return_negative_cooling_slug_J, ...
        'hot_slug_to_heating_ratio', hot_split.hot_slug_to_heating_ratio, ...
        'T_hot_return_first_K', hot_split.T_hot_return_first_K, ...
        'T_hot_return_max_K', hot_split.T_hot_return_max_K, ...
        'T_hot_return_min_K', hot_split.T_hot_return_min_K, ...
        'T_hot_return_last_K', hot_split.T_hot_return_last_K, ...
        'T_hot_return_first_max_min_last_K', [hot_split.T_hot_return_first_K, ...
        hot_split.T_hot_return_max_K, hot_split.T_hot_return_min_K, hot_split.T_hot_return_last_K], ...
        'Q_hot_sink_mass_received_J', hot_sink_delta_energy_J, ...
        'Q_hot_fluid_buffer_received_J', hot_buffer_delta_energy_J_for_closure, ...
        'Q_hot_fluid_buffer_simscape_drift_J', Q_hot_fluid_buffer_simscape_drift_J, ...
        'Q_hot_fluid_buffer_effective_drift_J', Q_hot_fluid_buffer_effective_drift_J, ...
        'hot_fluid_buffer_effective_volume_fraction', hot_buffer_effective_volume_fraction, ...
        'hot_fluid_buffer_effective_volume_m3', hot_buffer_effective_volume_m3, ...
        'hot_fluid_buffer_numerical_volume_m3', hot_buffer_numerical_volume_m3, ...
        'hot_fluid_buffer_effective_drift_source', hot_buffer_effective_drift_source, ...
        'buffer_follow_sink_enabled', buffer_follow_sink_enabled, ...
        'Q_hot_pipe_or_HHEX_storage_J', Q_pipe_storage_J, ...
        'Q_hot_pipe_or_HHEX_storage_method', pipe_storage_method, ...
        'Q_hot_end_storage_sum_J', Q_storage_sum_J, ...
        'Q_hot_end_official_J', Q_hot_end_official_J, ...
        'Q_hot_end_received_measured_J', Q_hot_end_received_measured_J, ...
        'Q_hot_end_received_measured_source', measured_source, ...
        'Q_hot_end_received_ideal_J', Q_hot_end_received_ideal_J, ...
        'Q_hot_end_received_ideal_source', 'upper_bound_if_all_SMA_HTF_enthalpy_reaches_hot_end', ...
        'Q_external_hot_end_mixer_J', Q_external_hot_end_mixer_J, ...
        'hot_end_entity_mixer_discrepancy_J', Q_storage_sum_J - Q_hot_end_received_measured_J, ...
        'hot_end_entity_mixer_discrepancy_ratio', safe_abs_ratio(Q_storage_sum_J - Q_hot_end_received_measured_J, Q_hot_end_received_measured_J), ...
        'hot_end_entity_to_boundary_ratio', safe_abs_ratio(Q_storage_sum_J, Q_hot_end_received_measured_J), ...
        'hot_end_entity_is_used_for_physics', hot_end_entity_is_used_for_physics, ...
        'hot_end_official_is_used_for_physics', hot_end_official_is_used_for_physics, ...
        'hot_end_entity_role', ternary_string(hot_end_entity_is_used_for_physics, ...
            'entity_storage_is_physical_hot_end', 'entity_probe_diagnostic_only_not_physical_hot_end'), ...
        'hot_end_delivery_ratio_measured', delivery_ratio_measured, ...
        'hot_end_delivery_ratio_ideal', delivery_ratio_ideal, ...
        'hot_end_missing_energy_J', Q_unaccounted_stage2_J, ...
        'Q_unaccounted_stage2_J', Q_unaccounted_stage2_J, ...
        'Q_unaccounted_stage2_ratio', Q_unaccounted_stage2_ratio, ...
        'hot_end_delivery_pass', delivery_pass, ...
        'hot_end_delivery_threshold', threshold, ...
        'hot_end_energy_chain_ok', delivery_pass, ...
        'stage2_hot_chain_residual_ok', residual_ok, ...
        'hot_end_measured_is_forced_equal_to_sma_htf', measured_is_forced, ...
        'hot_end_control_mode', control_mode, ...
        'official_hot_end_definition', get_option_field(sim_params, 'official_hot_end_definition', ...
            'external_hot_end_mixer_boundary_enthalpy_state_v1'), ...
        'hot_end_entity_storage_sum_J', Q_storage_sum_J, ...
        'hot_end_entity_storage_sum_source', 'HotSinkMass_plus_HotFluidBuffer_plus_HotPipe_HHEX_storage_diagnostic_not_official_in_external_mixer_scheme', ...
        'hot_end_temp_in', T_hot_end_in, ...
        'hot_end_temp_out', T_hot_end_out, ...
        'hot_end_temperature_source', temperature_source, ...
        'hot_end_C_total_J_per_K', C_total, ...
        'hot_end_effective_water_volume_ml', get_option_field(sim_params, 'hot_end_effective_water_volume_ml', NaN), ...
        'hot_end_includes_hot_sink_mass', get_option_field(sim_params, 'hot_end_includes_hot_sink_mass', true), ...
        'hot_end_includes_hot_fluid_buffer', get_option_field(sim_params, 'hot_end_includes_hot_fluid_buffer', true), ...
        'hot_end_includes_hot_pipe_or_HHEX', get_option_field(sim_params, 'hot_end_includes_hot_pipe_or_HHEX', true), ...
        'hot_sink_mass_C_J_per_K', C_sink, ...
        'hot_fluid_buffer_C_J_per_K', C_buffer, ...
        'hot_fluid_buffer_effective_C_J_per_K', hot_buffer_effective_C_J_per_K, ...
        'hot_pipe_or_HHEX_C_J_per_K', C_pipe, ...
        'hot_pipe_or_HHEX_T_mean_in_K', T_pipe_in, ...
        'hot_pipe_or_HHEX_T_mean_out_K', T_pipe_out, ...
        'hot_side_state_sync_policy', get_option_field(sim_params, 'hot_end_state_sync_policy', ...
            'hold_end_external_mixer_written_to_hot_sink_and_hot_buffer'));
end

function cold_end = build_cold_end_delivery(stage_config, sim_params, observability, closure, ...
        cold_sink_delta_energy_J, cold_buffer_delta_energy_J, active_flow_audit)
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    is_cooldown = strcmpi(stage_name, 'cooldown_exchange');
    threshold = 0.80;

    C_sink = max(get_option_field(sim_params, 'cold_sink_C_J_per_K', NaN), 0.0);
    C_buffer = max(get_option_field(sim_params, 'cold_fluid_buffer_C_J_per_K', NaN), 0.0);
    C_pipe_full = max(get_option_field(sim_params, 'cold_pipe_or_CHEX_C_J_per_K', 0.0), 0.0);
    buffer_follow_sink_enabled = logical(get_option_field(sim_params, 'buffer_follow_sink_enabled', false));
    [Q_cold_fluid_buffer_effective_drift_J, cold_buffer_effective_volume_fraction, ...
        cold_buffer_effective_volume_m3, cold_buffer_numerical_volume_m3, ...
        cold_buffer_effective_drift_source] = compute_dynamic_effective_buffer_delta( ...
        cold_buffer_delta_energy_J, sim_params, active_flow_audit);
    if buffer_follow_sink_enabled
        Q_cold_fluid_buffer_simscape_drift_J = cold_buffer_delta_energy_J;
        cold_buffer_delta_energy_J_for_closure = Q_cold_fluid_buffer_effective_drift_J;
        C_buffer_for_closure = C_buffer * cold_buffer_effective_volume_fraction;
    else
        Q_cold_fluid_buffer_simscape_drift_J = NaN;
        Q_cold_fluid_buffer_effective_drift_J = cold_buffer_delta_energy_J;
        cold_buffer_effective_volume_fraction = 1.0;
        cold_buffer_effective_volume_m3 = cold_buffer_numerical_volume_m3;
        cold_buffer_effective_drift_source = 'legacy_full_buffer_storage_included';
        cold_buffer_delta_energy_J_for_closure = cold_buffer_delta_energy_J;
        C_buffer_for_closure = C_buffer;
    end
    cold_buffer_effective_C_J_per_K = C_buffer_for_closure;
    pipe_storage_fraction = get_option_field(sim_params, 'cold_pipe_or_CHEX_effective_storage_fraction', NaN);
    if ~(isnumeric(pipe_storage_fraction) && isscalar(pipe_storage_fraction) && isfinite(pipe_storage_fraction))
        cold_pipe_volume_m3 = get_option_field(sim_params, 'cold_pipe_or_CHEX_volume_m3', NaN);
        target_flush_volume_m3 = get_option_field(sim_params, 'target_flush_volume_m3', NaN);
        if all(isfinite([cold_pipe_volume_m3, target_flush_volume_m3])) && cold_pipe_volume_m3 > 0
            pipe_storage_fraction = min(max(target_flush_volume_m3 / cold_pipe_volume_m3, 0.0), 1.0);
        else
            pipe_storage_fraction = 1.0;
        end
    end
    pipe_storage_fraction = min(max(pipe_storage_fraction, 0.0), 1.0);
    C_pipe = C_pipe_full * pipe_storage_fraction;
    C_total = C_sink + C_buffer_for_closure + C_pipe;

    T_sink_in = get_option_field(sim_params, 'cold_sink_T_init', NaN);
    T_sink_out = get_option_field(observability, 'cold_sink_temp_out', NaN);
    T_buffer_in = get_option_field(sim_params, 'cold_fluid_buffer_T_init', T_sink_in);
    T_buffer_out = get_option_field(observability, 'cold_buffer_temp_out', T_sink_out);
    T_pipe_in = get_option_field(sim_params, 'cold_pipe_or_CHEX_T_state_in_K', ...
        get_option_field(sim_params, 'cold_side_fluid_T_init', T_buffer_in));
    T_pipe_candidates = [ ...
        get_option_field(observability, 'cold_hx_inlet_fluid_temp_out', NaN), ...
        get_option_field(observability, 'cold_hx_outlet_fluid_temp_out', NaN)];
    finite_pipe = T_pipe_candidates(isfinite(T_pipe_candidates));
    if isempty(finite_pipe)
        T_pipe_out = T_buffer_out;
        pipe_storage_method = 'effective_refreshed_fraction_fallback_to_cold_buffer_temp_out';
    else
        T_pipe_out = mean(finite_pipe);
        pipe_storage_method = 'effective_refreshed_fraction_mean_of_CHEX_inlet_and_outlet_terminal_probes';
    end
    T_pipe_out_terminal = T_pipe_out;
    pipe_storage_method_terminal = pipe_storage_method;

    if C_total > 0 && all(isfinite([T_sink_in, T_sink_out, T_buffer_in, T_buffer_out, T_pipe_in, T_pipe_out]))
        T_cold_end_in = (C_sink * T_sink_in + C_buffer_for_closure * T_buffer_in + C_pipe * T_pipe_in) / C_total;
        T_cold_end_out = (C_sink * T_sink_out + C_buffer_for_closure * T_buffer_out + C_pipe * T_pipe_out) / C_total;
    else
        T_cold_end_in = NaN;
        T_cold_end_out = NaN;
    end

    Q_pipe_storage_terminal_estimate_J = C_pipe * (T_pipe_out_terminal - T_pipe_in);
    Q_pipe_storage_J = Q_pipe_storage_terminal_estimate_J;
    Q_control_volume_storage_sum_J = cold_sink_delta_energy_J + cold_buffer_delta_energy_J_for_closure + Q_pipe_storage_J;
    Q_cold_fluid_buffer_source_boundary_delta_J = cold_buffer_delta_energy_J;
    if is_cooldown
        Q_cold_fluid_buffer_received_J = cold_buffer_delta_energy_J_for_closure;
    else
        Q_cold_fluid_buffer_received_J = 0.0;
    end
    Q_sma_stage4_state_J = get_option_field(closure, 'Q_sma_state_stage4_J', NaN);
    Q_sma_htf_stage4_J = get_option_field(closure, 'Q_sma_htf_stage4_J', NaN);
    cold_end_external_mixer_enabled = logical(get_option_field(sim_params, ...
        'cold_end_external_mixer_enabled', true));
    control_mode = char(string(get_option_field(sim_params, 'official_cold_end_control_mode', ...
        'entity_cold_end_storage_sum_v1')));
    use_external_cold_mixer = cold_end_external_mixer_enabled || ...
        contains(lower(control_mode), 'external') || ...
        contains(lower(char(string(get_option_field(sim_params, 'official_cold_end_definition', '')))), 'external');
    cold_end_entity_is_used_for_physics = ~use_external_cold_mixer;
    cold_end_official_is_used_for_physics = true;
    [Q_stage4_SMA_to_HTF_integral_J, stage4_sma_to_htf_source, stage4_sma_boundary] = ...
        integrate_stage4_sma_to_htf_enthalpy(stage_config, sim_params, observability);
    [Q_stage4_CHEX_in_to_out_J, stage4_chex_source, chex_split] = ...
        integrate_stage4_chex_enthalpy(stage_config, sim_params, observability, T_cold_end_in);
    cold_pipe_storage_model = char(string(get_option_field(sim_params, ...
        'cold_pipe_or_CHEX_storage_model', 'chex_50point_inlet_history_observed_no_residual_writeback_v1')));
    [T_pipe_out, pipe_storage_method, pipe_temperature_observation_source, pipe_temperature_blend_factor] = ...
        estimate_cold_pipe_chex_observed_temperature(T_pipe_out_terminal, ...
        pipe_storage_method_terminal, cold_pipe_storage_model, chex_split, pipe_storage_fraction);
    if use_external_cold_mixer && ~is_cooldown
        T_pipe_out = T_pipe_in;
        T_pipe_out_terminal = T_pipe_in;
        pipe_storage_method = 'external_cold_end_mixer_inactive_stage_frozen_previous_cooldown_state';
        pipe_storage_method_terminal = pipe_storage_method;
        pipe_temperature_observation_source = 'frozen_previous_cooldown_state_not_inactive_CHEX_probe';
        pipe_temperature_blend_factor = 0.0;
    end
    if C_total > 0 && all(isfinite([T_sink_in, T_sink_out, T_buffer_in, T_buffer_out, T_pipe_in, T_pipe_out]))
        T_cold_end_out = (C_sink * T_sink_out + C_buffer_for_closure * T_buffer_out + C_pipe * T_pipe_out) / C_total;
    else
        T_cold_end_out = NaN;
    end
    Q_pipe_storage_J = C_pipe * (T_pipe_out - T_pipe_in);
    Q_control_volume_storage_sum_J = cold_sink_delta_energy_J + cold_buffer_delta_energy_J_for_closure + Q_pipe_storage_J;
    residual_required_to_close_J = NaN;
    if is_cooldown && isfinite(Q_stage4_CHEX_in_to_out_J) && ...
            all(isfinite([cold_sink_delta_energy_J, cold_buffer_delta_energy_J_for_closure, Q_pipe_storage_J]))
        residual_required_to_close_J = ...
            -(Q_stage4_CHEX_in_to_out_J + cold_sink_delta_energy_J + cold_buffer_delta_energy_J_for_closure + Q_pipe_storage_J);
    end
    Q_control_volume_storage_sum_J = cold_sink_delta_energy_J + cold_buffer_delta_energy_J_for_closure + Q_pipe_storage_J;
    if is_cooldown && isfinite(Q_sma_htf_stage4_J)
        Q_stage4_SMA_to_HTF_J = Q_sma_htf_stage4_J;
        Q_stage4_SMA_to_HTF_source = 'sma_htf_closure_positive_heat_to_SMA_crosschecked_with_stage4_SMA_boundary_integral';
    else
        Q_stage4_SMA_to_HTF_J = Q_stage4_SMA_to_HTF_integral_J;
        Q_stage4_SMA_to_HTF_source = stage4_sma_to_htf_source;
    end

    if is_cooldown && use_external_cold_mixer && isfinite(Q_stage4_CHEX_in_to_out_J)
        Q_external_cold_end_mixer_J = -Q_stage4_CHEX_in_to_out_J;
        Q_cold_end_official_J = Q_external_cold_end_mixer_J;
        Q_cold_end_received_measured_J = Q_cold_end_official_J;
        measured_source = ['external_cold_end_mixer_CHEX_boundary_enthalpy_state_v1:', stage4_chex_source];
        temperature_source = 'external_cold_end_mixer_boundary_enthalpy_state';
        T_cold_end_out_measured = T_cold_end_in + Q_external_cold_end_mixer_J / max(C_total, eps);
    else
        Q_external_cold_end_mixer_J = NaN;
        if strcmpi(stage_name, 'hold_exchange')
            Q_cold_end_official_J = 0.0;
            Q_cold_end_received_measured_J = 0.0;
            measured_source = 'hold_exchange_cold_end_frozen_source_boundary_no_official_writeback';
            temperature_source = 'frozen_official_cold_end_previous_cooldown_state';
            T_cold_end_out_measured = T_cold_end_in;
        else
            Q_cold_end_official_J = Q_control_volume_storage_sum_J;
            Q_cold_end_received_measured_J = Q_control_volume_storage_sum_J;
            measured_source = 'measured_control_volume_storage_sum';
            temperature_source = 'energy_weighted_ColdSinkMass_ColdFluidBuffer_ColdSinkPipe_CHEX';
            T_cold_end_out_measured = T_cold_end_out;
        end
    end
    Q_cold_end_received_ideal_J = NaN;
    if is_cooldown && isfinite(Q_sma_htf_stage4_J)
        Q_cold_end_received_ideal_J = -Q_sma_htf_stage4_J;
    end
    T_cold_end_out = T_cold_end_out_measured;
    sync_policy = get_option_field(sim_params, 'cold_end_state_sync_policy', ...
        'cooldown_end_measured_energy_weighted_temperature_written_to_cold_sink_and_cold_buffer');
    if is_cooldown && use_external_cold_mixer && isfinite(T_pipe_out)
        cold_pipe_state_writeback_source = ['active_chex_internal:', pipe_temperature_observation_source];
    elseif use_external_cold_mixer
        cold_pipe_state_writeback_source = 'frozen_previous_cooldown';
    else
        cold_pipe_state_writeback_source = ['entity_storage:', pipe_temperature_observation_source];
    end
    T_cold_hx_pipe_in = get_option_field(sim_params, 'cold_hx_pipe_T_state_in_K', T_pipe_in);
    T_cold_return_pipe_in = get_option_field(sim_params, 'cold_return_pipe_T_state_in_K', T_pipe_in);
    T_return_candidates = [ ...
        get_option_field(observability, 'cold_hx_outlet_fluid_temp_out', NaN), ...
        get_option_field(observability, 'cold_return_outlet_fluid_temp_out', NaN)];
    finite_return_candidates = T_return_candidates(isfinite(T_return_candidates));
    if is_cooldown && ~isempty(finite_return_candidates)
        T_cold_return_pipe_out = mean(finite_return_candidates);
        cold_return_pipe_state_source = 'mean_true_CHEX_outlet_and_return_outlet_terminal_probes';
    else
        T_cold_return_pipe_out = T_cold_return_pipe_in;
        cold_return_pipe_state_source = 'inactive_stage_frozen_previous_return_pipe_state';
    end

    [Q_sma_latent_stage4_J, latent_stage4_reason, xi_stage4_report] = ...
        compute_stage4_latent_diagnostic(sim_params, stage_config);
    Q_sma_sensible_stage4_J = Q_sma_stage4_state_J;
    Q_sma_total_stage4_J = Q_sma_sensible_stage4_J + Q_sma_latent_stage4_J;
    if isfinite(Q_sma_htf_stage4_J) && isfinite(Q_sma_total_stage4_J) && abs(Q_sma_total_stage4_J) > 1.0e-12
        Q_sma_to_htf_ratio = abs(Q_sma_htf_stage4_J) / abs(Q_sma_total_stage4_J);
    else
        Q_sma_to_htf_ratio = NaN;
    end
    Q_stage4_cold_entity_storage_sum_J = Q_control_volume_storage_sum_J;
    if is_cooldown && isfinite(Q_stage4_CHEX_in_to_out_J) && isfinite(Q_stage4_cold_entity_storage_sum_J)
        Q_stage4_CHEX_energy_residual_J = Q_stage4_CHEX_in_to_out_J + Q_stage4_cold_entity_storage_sum_J;
        Q_stage4_CHEX_energy_residual_ratio = abs(Q_stage4_CHEX_energy_residual_J) / ...
            max([abs(Q_stage4_CHEX_in_to_out_J), abs(Q_stage4_cold_entity_storage_sum_J), 1.0e-12]);
        Q_stage4_CHEX_energy_residual_abs_J = abs(Q_stage4_CHEX_energy_residual_J);
        stage4_CHEX_residual_scale_J = max([ ...
            abs(Q_stage4_CHEX_in_to_out_J), abs(Q_stage4_cold_entity_storage_sum_J), 1.0e-12]);
        Q_stage4_CHEX_energy_residual_abs_limit_J = ...
            max(0.5, min(3.0, 0.30 * stage4_CHEX_residual_scale_J));
        stage4_CHEX_energy_residual_abs_ok = ...
            Q_stage4_CHEX_energy_residual_abs_J <= Q_stage4_CHEX_energy_residual_abs_limit_J;
        Q_stage4_CHEX_to_cold_entity_closure_ratio = abs(Q_stage4_cold_entity_storage_sum_J) / ...
            max(abs(Q_stage4_CHEX_in_to_out_J), 1.0e-12);
        Q_stage4_CHEX_entity_sign_opposite_ok = ...
            abs(Q_stage4_CHEX_in_to_out_J) <= 1.0e-9 || ...
            abs(Q_stage4_cold_entity_storage_sum_J) <= 1.0e-9 || ...
            sign(Q_stage4_CHEX_in_to_out_J) ~= sign(Q_stage4_cold_entity_storage_sum_J);
        stage4_CHEX_temperature_pointwise_ok = chex_split.stage4_CHEX_temperature_direction_ok;
        stage4_CHEX_energy_direction_ok = Q_stage4_CHEX_entity_sign_opposite_ok && ...
            stage4_CHEX_energy_residual_abs_ok;
        chex_split.stage4_CHEX_temperature_direction_ok = ...
            stage4_CHEX_temperature_pointwise_ok || stage4_CHEX_energy_direction_ok;
        stage4_CHEX_entity_balance_ok = Q_stage4_CHEX_entity_sign_opposite_ok && ...
            stage4_CHEX_energy_residual_abs_ok && chex_split.stage4_CHEX_temperature_direction_ok;
        Q_stage4_cold_chain_unclosed_excess_J = ...
            max(Q_stage4_CHEX_energy_residual_abs_J - Q_stage4_CHEX_energy_residual_abs_limit_J, 0.0);
    else
        Q_stage4_CHEX_energy_residual_J = NaN;
        Q_stage4_CHEX_energy_residual_ratio = NaN;
        Q_stage4_CHEX_energy_residual_abs_J = NaN;
        Q_stage4_CHEX_energy_residual_abs_limit_J = NaN;
        stage4_CHEX_energy_residual_abs_ok = ~is_cooldown;
        Q_stage4_CHEX_to_cold_entity_closure_ratio = NaN;
        Q_stage4_CHEX_entity_sign_opposite_ok = ~is_cooldown;
        stage4_CHEX_temperature_pointwise_ok = ~is_cooldown;
        stage4_CHEX_energy_direction_ok = ~is_cooldown;
        stage4_CHEX_entity_balance_ok = ~is_cooldown;
        Q_stage4_cold_chain_unclosed_excess_J = NaN;
    end
    if is_cooldown && isfinite(Q_stage4_SMA_to_HTF_J) && isfinite(Q_stage4_CHEX_in_to_out_J)
        Q_stage4_SMA_to_CHEX_transit_storage_J = ...
            Q_stage4_SMA_to_HTF_J - abs(Q_stage4_CHEX_in_to_out_J);
        if Q_stage4_SMA_to_CHEX_transit_storage_J < 0 && ...
                abs(Q_stage4_SMA_to_CHEX_transit_storage_J) < 1.0e-9
            Q_stage4_SMA_to_CHEX_transit_storage_J = 0.0;
        end
    else
        Q_stage4_SMA_to_CHEX_transit_storage_J = NaN;
    end
    if is_cooldown && isfinite(Q_stage4_SMA_to_HTF_J) && abs(Q_stage4_SMA_to_HTF_J) > 1.0e-12
        Q_stage4_SMA_to_HTF_abs_J = abs(Q_stage4_SMA_to_HTF_J);
        Q_stage4_CHEX_boundary_abs_J = abs(Q_stage4_CHEX_in_to_out_J);
        Q_stage4_cold_entity_abs_J = abs(Q_stage4_cold_entity_storage_sum_J);
        sma_to_CHEX_transport_ratio_observed = Q_stage4_CHEX_boundary_abs_J / Q_stage4_SMA_to_HTF_abs_J;
        Q_sma_to_CHEX_transport_gap_J = Q_stage4_SMA_to_HTF_abs_J - Q_stage4_CHEX_boundary_abs_J;
        if isfinite(Q_stage4_CHEX_boundary_abs_J) && Q_stage4_CHEX_boundary_abs_J > 1.0e-12
            CHEX_to_cold_entity_delivery_ratio_observed = ...
                Q_stage4_cold_entity_abs_J / Q_stage4_CHEX_boundary_abs_J;
            Q_CHEX_to_cold_entity_gap_J = Q_stage4_CHEX_boundary_abs_J - Q_stage4_cold_entity_abs_J;
        else
            CHEX_to_cold_entity_delivery_ratio_observed = NaN;
            Q_CHEX_to_cold_entity_gap_J = NaN;
        end
        stage4_two_step_energy_chain_ok = stage4_CHEX_entity_balance_ok;
        stage4_cold_chain_primary_bottleneck = classify_stage4_cold_chain_bottleneck( ...
            sma_to_CHEX_transport_ratio_observed, ...
            CHEX_to_cold_entity_delivery_ratio_observed, ...
            Q_stage4_CHEX_energy_residual_ratio, ...
            Q_stage4_CHEX_entity_sign_opposite_ok);
        if stage4_CHEX_entity_balance_ok && isfinite(sma_to_CHEX_transport_ratio_observed) && ...
                sma_to_CHEX_transport_ratio_observed < 0.80
            stage4_cold_chain_primary_bottleneck = ...
                'sma_to_CHEX_transport_ratio_low_trend_only_equilibrium_or_CHEX_effectiveness';
        end
    else
        Q_stage4_SMA_to_HTF_abs_J = NaN;
        Q_stage4_CHEX_boundary_abs_J = NaN;
        Q_stage4_cold_entity_abs_J = NaN;
        sma_to_CHEX_transport_ratio_observed = NaN;
        CHEX_to_cold_entity_delivery_ratio_observed = NaN;
        Q_sma_to_CHEX_transport_gap_J = NaN;
        Q_CHEX_to_cold_entity_gap_J = NaN;
        stage4_two_step_energy_chain_ok = ~is_cooldown;
        stage4_cold_chain_primary_bottleneck = ternary_string(is_cooldown, ...
            'insufficient_stage4_energy_chain_data', 'not_cooldown_exchange');
    end
    transit_cv = build_stage4_sma_to_CHEX_transit_control_volume( ...
        stage_config, sim_params, observability, ...
        Q_stage4_SMA_to_HTF_abs_J, Q_stage4_CHEX_boundary_abs_J, Q_sma_to_CHEX_transport_gap_J);
    if logical(transit_cv.stage4_sma_to_CHEX_transit_observable) && ...
            isfinite(transit_cv.stage4_sma_to_CHEX_transit_cold_storage_observed_J)
        % Replace the legacy gap-based estimate with the Simulink TransitPipe
        % flux integral. This is the canonical observed transit storage.
        Q_stage4_SMA_to_CHEX_transit_storage_J = ...
            transit_cv.stage4_sma_to_CHEX_transit_cold_storage_observed_J;
    end
    if strcmp(stage4_cold_chain_primary_bottleneck, 'sma_to_CHEX_transport_or_upstream_pipe_storage') && ...
            logical(transit_cv.stage4_sma_to_CHEX_transit_observable)
        if logical(transit_cv.stage4_sma_to_CHEX_transit_closure_ok)
            stage4_cold_chain_primary_bottleneck = ...
                'sma_to_CHEX_transit_control_volume_accounts_gap_with_simulink_TL_pipe_observation';
        else
            stage4_cold_chain_primary_bottleneck = ...
                'sma_to_CHEX_transit_control_volume_cannot_account_gap';
        end
    end
    if isfinite(Q_stage4_SMA_to_HTF_J) && isfinite(Q_cold_end_received_measured_J)
        Q_stage4_direct_cold_entity_gap_J = Q_stage4_SMA_to_HTF_J + Q_cold_end_received_measured_J;
        Q_unaccounted_stage4_J = Q_stage4_direct_cold_entity_gap_J;
    else
        Q_stage4_direct_cold_entity_gap_J = NaN;
        Q_unaccounted_stage4_J = NaN;
    end
    if isfinite(Q_stage4_SMA_to_HTF_J) && abs(Q_stage4_SMA_to_HTF_J) > 1.0e-12
        Q_unaccounted_stage4_ratio = abs(Q_unaccounted_stage4_J) / abs(Q_stage4_SMA_to_HTF_J);
        delivery_ratio_measured = abs(Q_cold_end_received_measured_J) / abs(Q_stage4_SMA_to_HTF_J);
        delivery_ratio_ideal = abs(Q_cold_end_received_ideal_J) / abs(Q_stage4_SMA_to_HTF_J);
        if isfinite(Q_stage4_SMA_to_CHEX_transit_storage_J)
            cold_end_delivery_with_transit_storage_ratio = ...
                (abs(Q_cold_end_received_measured_J) + max(Q_stage4_SMA_to_CHEX_transit_storage_J, 0.0)) / ...
                abs(Q_stage4_SMA_to_HTF_J);
        else
            cold_end_delivery_with_transit_storage_ratio = NaN;
        end
        missing_energy_J = Q_unaccounted_stage4_J;
        measured_is_forced = isfinite(delivery_ratio_measured) && isfinite(delivery_ratio_ideal) && ...
            abs(delivery_ratio_measured - delivery_ratio_ideal) < 1.0e-10 && ...
            contains(lower(measured_source), 'ideal');
        transit_storage_explains_gap_ok = false;
        if use_external_cold_mixer
            stage4_cold_chain_residual_ok = stage4_CHEX_entity_balance_ok;
        else
            stage4_cold_chain_residual_ok = isfinite(Q_unaccounted_stage4_ratio) && Q_unaccounted_stage4_ratio <= 0.20 && ...
                isfinite(Q_stage4_CHEX_energy_residual_ratio) && Q_stage4_CHEX_energy_residual_ratio <= 0.20 && ...
                Q_stage4_CHEX_entity_sign_opposite_ok && chex_split.stage4_CHEX_temperature_direction_ok;
        end
        delivery_pass = is_cooldown && ~measured_is_forced && ...
            isfinite(Q_stage4_CHEX_in_to_out_J) && stage4_cold_chain_residual_ok;
    else
        Q_unaccounted_stage4_ratio = NaN;
        delivery_ratio_measured = NaN;
        delivery_ratio_ideal = NaN;
        cold_end_delivery_with_transit_storage_ratio = NaN;
        missing_energy_J = NaN;
        measured_is_forced = false;
        transit_storage_explains_gap_ok = ~is_cooldown;
        stage4_cold_chain_residual_ok = ~is_cooldown;
        delivery_pass = ~is_cooldown;
    end

    if strcmpi(stage_name, 'hold_exchange') && isfinite(T_cold_end_in) && isfinite(T_cold_end_out_measured)
        hold_cold_official_drift_due_to_source_buffer_K = T_cold_end_out_measured - T_cold_end_in;
        stage2_cold_buffer_source_pollution_ok = abs(hold_cold_official_drift_due_to_source_buffer_K) <= 1.0e-8;
    else
        hold_cold_official_drift_due_to_source_buffer_K = NaN;
        stage2_cold_buffer_source_pollution_ok = true;
    end

