        'cold_end_energy_chain_ok', delivery_pass, ...
        'stage4_cold_chain_residual_ok', stage4_cold_chain_residual_ok, ...
        'cold_end_measured_is_forced_equal_to_sma_htf', measured_is_forced, ...
        'cold_end_control_mode', control_mode, ...
        'official_cold_end_definition', get_option_field(sim_params, 'official_cold_end_definition', ...
            'entity_cold_end_storage_sum_v1'), ...
        'cold_end_entity_storage_sum_J', Q_control_volume_storage_sum_J, ...
        'cold_end_entity_storage_sum_source', ternary_string(buffer_follow_sink_enabled, ...
            'R62_ColdSinkMass_plus_CHEX_pipe_storage_plus_dynamic_effective_ColdFluidBuffer_drift', ...
            'ColdSinkMass_plus_ColdFluidBuffer_plus_CHEX_pipe_storage_official_entity_cold_end'), ...
        'latent_stage4_reason', latent_stage4_reason, ...
        'xi_stage4_in_avg', xi_stage4_report.xi_stage4_in_avg, ...
        'xi_stage4_in_max', xi_stage4_report.xi_stage4_in_max, ...
        'xi_stage4_out_avg', xi_stage4_report.xi_stage4_out_avg, ...
        'xi_stage4_out_max', xi_stage4_report.xi_stage4_out_max, ...
        'delta_xi_stage4_avg', xi_stage4_report.delta_xi_stage4_avg, ...
        'delta_xi_stage4_max_abs', xi_stage4_report.delta_xi_stage4_max_abs, ...
        'Q_latent_balance_est_J_diagnostic_only', xi_stage4_report.Q_latent_balance_est_J_diagnostic_only, ...
        'cold_end_temp_in', T_cold_end_in, ...
        'cold_end_temp_out', T_cold_end_out, ...
        'cold_end_temp_out_measured_K', T_cold_end_out_measured, ...
        'cold_end_temperature_source', temperature_source, ...
        'hold_cold_official_drift_due_to_source_buffer_K', hold_cold_official_drift_due_to_source_buffer_K, ...
        'stage2_cold_buffer_source_pollution_ok', stage2_cold_buffer_source_pollution_ok, ...
        'cold_end_C_total_J_per_K', C_total, ...
        'cold_end_effective_water_volume_ml', get_option_field(sim_params, 'cold_end_effective_water_volume_ml', NaN), ...
        'cold_end_includes_cold_sink_mass', get_option_field(sim_params, 'cold_end_includes_cold_sink_mass', true), ...
        'cold_end_includes_cold_fluid_buffer', get_option_field(sim_params, 'cold_end_includes_cold_fluid_buffer', true), ...
        'cold_end_includes_cold_pipe_or_CHEX', get_option_field(sim_params, 'cold_end_includes_cold_pipe_or_CHEX', true), ...
        'cold_sink_mass_C_J_per_K', C_sink, ...
        'cold_fluid_buffer_C_J_per_K', C_buffer, ...
        'cold_fluid_buffer_effective_C_J_per_K', cold_buffer_effective_C_J_per_K, ...
        'cold_pipe_or_CHEX_C_J_per_K', C_pipe, ...
        'cold_pipe_or_CHEX_full_C_J_per_K', C_pipe_full, ...
        'cold_pipe_or_CHEX_effective_storage_fraction', pipe_storage_fraction, ...
        'cold_pipe_or_CHEX_T_mean_in_K', T_pipe_in, ...
        'cold_pipe_or_CHEX_T_mean_out_K', T_pipe_out, ...
        'cold_pipe_or_CHEX_T_state_in_K', T_pipe_in, ...
        'cold_pipe_or_CHEX_T_state_out_K', T_pipe_out, ...
        'cold_hx_pipe_T_state_in_K', T_cold_hx_pipe_in, ...
        'cold_hx_pipe_T_state_out_K', T_pipe_out, ...
        'cold_return_pipe_T_state_in_K', T_cold_return_pipe_in, ...
        'cold_return_pipe_T_state_out_K', T_cold_return_pipe_out, ...
        'cold_return_pipe_state_writeback_source', cold_return_pipe_state_source, ...
        'cold_side_state_sync_policy', sync_policy);
end

function [Q_effective_delta_J, effective_fraction, effective_volume_m3, numerical_volume_m3, source] = ...
        compute_dynamic_effective_buffer_delta(Q_full_buffer_delta_J, sim_params, active_flow_audit)
    numerical_volume_m3 = get_option_field(sim_params, 'fluid_buffer_volume_m3', NaN);
    target_volume_m3 = get_option_field(sim_params, 'target_flush_volume_m3', NaN);
    actual_flush_ratio = get_option_field(active_flow_audit, 'actual_active_flush_volume_ratio', NaN);
    if ~(isnumeric(actual_flush_ratio) && isscalar(actual_flush_ratio) && isfinite(actual_flush_ratio))
        actual_flush_ratio = get_option_field(sim_params, 'actual_active_flush_volume_ratio', NaN);
    end
    if ~(isnumeric(actual_flush_ratio) && isscalar(actual_flush_ratio) && isfinite(actual_flush_ratio))
        actual_flush_ratio = 1.0;
        ratio_source = 'fallback_target_flush_volume';
    else
        ratio_source = 'active_flow_audit_actual_active_flush_volume_ratio';
    end
    actual_flush_ratio = max(actual_flush_ratio, 0.0);

    if all(isfinite([target_volume_m3, numerical_volume_m3])) && numerical_volume_m3 > 0
        effective_volume_m3 = min(max(actual_flush_ratio * target_volume_m3, 0.0), numerical_volume_m3);
        effective_fraction = effective_volume_m3 / numerical_volume_m3;
    else
        reference_ratio = get_option_field(sim_params, 'fluid_buffer_reference_ratio', NaN);
        if ~(isnumeric(reference_ratio) && isscalar(reference_ratio) && isfinite(reference_ratio) && reference_ratio > 0)
            reference_ratio = 1.0;
        end
        effective_fraction = min(max(actual_flush_ratio / reference_ratio, 0.0), 1.0);
        effective_volume_m3 = numerical_volume_m3 * effective_fraction;
    end

    if ~logical(get_option_field(sim_params, 'buffer_effective_energy_accounting_enabled', true))
        effective_fraction = 1.0;
        effective_volume_m3 = numerical_volume_m3;
        source = 'disabled_legacy_full_numerical_buffer_volume';
    else
        source = ['R62_actual_active_flush_volume_over_numerical_buffer_volume:', ratio_source];
    end
    Q_effective_delta_J = Q_full_buffer_delta_J * effective_fraction;
end

function [T_pipe_out, method, source, blend_factor_used] = estimate_cold_pipe_chex_observed_temperature( ...
        T_terminal_pair_mean, terminal_method, storage_model, chex_split, blend_factor)
    T_pipe_out = T_terminal_pair_mean;
    method = terminal_method;
    source = 'terminal_CHEX_inlet_outlet_mean';
    blend_factor_used = NaN;
    model = lower(char(string(storage_model)));
    if ~(contains(model, '50point') || contains(model, 'multinode') || contains(model, 'history'))
        return;
    end

    candidates = [ ...
        get_option_field(chex_split, 'T_stage4_CHEX_in_mass_weighted_mean_K', NaN), ...
        get_option_field(chex_split, 'T_stage4_CHEX_in_time_mean_K', NaN), ...
        get_option_field(chex_split, 'T_cold_supply_min_K', NaN)];
    candidates = candidates(isfinite(candidates));
    if isempty(candidates)
        return;
    end

    if ~(isnumeric(blend_factor) && isscalar(blend_factor) && isfinite(blend_factor))
        blend_factor = 1.0;
    end
    blend_factor = min(max(blend_factor, 0.0), 1.0);

    if contains(model, 'blend')
        T_pipe_out = (1.0 - blend_factor) * T_terminal_pair_mean + blend_factor * candidates(1);
        method = 'effective_refreshed_fraction_blend_of_terminal_pair_and_50point_CHEX_inlet_history';
        blend_factor_used = blend_factor;
        source = sprintf('independent_terminal_probe_and_50point_CHEX_inlet_history_blend_factor_%0.6g_not_residual_closure', blend_factor);
        return;
    end

    % The counted CHEX/Pipe capacity is only the stage-refreshed fraction.
    % For that fraction, the incoming SMA-side CHEX history is the observable
    % fluid packet temperature; the residual required for closure is not used.
    T_pipe_out = candidates(1);
    method = 'effective_refreshed_fraction_50point_CHEX_inlet_history_mass_weighted_probe_estimate';
    source = 'independent_50point_CHEX_inlet_history_not_residual_closure';
end

function bottleneck = classify_stage4_cold_chain_bottleneck( ...
        sma_to_CHEX_transport_ratio, CHEX_to_cold_entity_ratio, ...
        chex_residual_ratio, chex_sign_ok)
    if ~(isfinite(sma_to_CHEX_transport_ratio) && isfinite(CHEX_to_cold_entity_ratio))
        bottleneck = 'insufficient_stage4_energy_chain_data';
        return;
    end
    if sma_to_CHEX_transport_ratio < 0.80
        bottleneck = 'sma_to_CHEX_transport_or_upstream_pipe_storage';
        return;
    end
    if CHEX_to_cold_entity_ratio < 0.80
        bottleneck = 'CHEX_to_official_cold_entity_coupling_or_storage';
        return;
    end
    if ~(isfinite(chex_residual_ratio) && chex_residual_ratio <= 0.20)
        bottleneck = 'CHEX_entity_energy_residual_above_gate';
        return;
    end
    if ~logical(chex_sign_ok)
        bottleneck = 'CHEX_entity_energy_sign_inconsistent';
        return;
    end
    bottleneck = 'none_two_step_chain_within_gate';
end

function transit = build_stage4_sma_to_CHEX_transit_control_volume( ...
        stage_config, sim_params, observability, ...
        Q_sma_abs_J, Q_chex_boundary_abs_J, Q_required_gap_J)
    % Stage4 SMA-to-CHEX transit control volume diagnostic.
    %
    % Physical model: TransitPipe_V6_to_CHEX is a Simscape TL Pipe placed
    % between V6.RConn (cold_subsystem Conn2) and ColdSinkPipe.RConn. The pipe
    % wall is adiabatic so its internal energy is preserved across idle stages
    % (1, 2, 3). At start of stage 4 cycle N+1 the pipe holds the end-of-
    % stage 4 cycle N temperature, set via T0 = transit_pipe_T_init pulled
    % from runtime.transit_pipe_T_state_K.
    %
    % Two cross-checked energy estimates:
    %   (1) Flux integral: delta_U = integral of mdot * cp * (T_in - T_out) dt
    %       This is the canonical conservation-law estimate from boundary
    %       probes. No residual closure.
    %   (2) State estimate: delta_U_state = C_transit * (T_out_last - T_out_first)
    %       Uses TransitPipe.LConn probe directly. Less accurate than (1) due
    %       to plug-vs-mixing assumptions but cross-checks (1).
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    model = char(string(get_option_field(sim_params, ...
        'stage4_sma_to_CHEX_transit_model', 'simulink_TL_pipe_internal_observation_v2_independent_of_residual')));
    cold_end_topology_mode = lower(strtrim(char(string(get_option_field(sim_params, ...
        'cold_end_topology_mode', 'r69_symmetric')))));
    % Single TransitPipe (TransitPipe_V6_to_CHEX, inside cold_subsystem).
    % Spans Conn2 (V6 chip-side) -> internal TransitPipe.LConn
    % (= ColdSinkPipe.RConn). Legacy aliases retained.
    C_transit = get_option_field(sim_params, 'transit_pipe_internal_fluid_C_J_per_K', ...
        get_option_field(sim_params, 'stage4_sma_to_CHEX_transit_C_J_per_K', NaN));
    volume_ml = get_option_field(sim_params, 'transit_pipe_volume_ml', ...
        get_option_field(sim_params, 'stage4_sma_to_CHEX_transit_volume_ml', NaN));
    T_state_in = get_option_field(sim_params, 'transit_pipe_T_state_in_K', ...
        get_option_field(sim_params, 'stage4_sma_to_CHEX_transit_T_state_in_K', NaN));
    transit = struct( ...
        'stage4_sma_to_CHEX_transit_model', model, ...
        'stage4_sma_to_CHEX_transit_observable', false, ...
        'stage4_sma_to_CHEX_transit_C_J_per_K', C_transit, ...
        'stage4_sma_to_CHEX_transit_volume_ml', volume_ml, ...
        'stage4_sma_to_CHEX_transit_T_state_in_K', T_state_in, ...
        'stage4_sma_to_CHEX_transit_T_state_out_K', NaN, ...
        'stage4_sma_to_CHEX_transit_T_upstream_mass_mean_K', NaN, ...
        'stage4_sma_to_CHEX_transit_T_downstream_mass_mean_K', NaN, ...
        'stage4_sma_to_CHEX_transit_delta_U_J', NaN, ...
        'stage4_sma_to_CHEX_transit_delta_U_state_J', NaN, ...
        'stage4_sma_to_CHEX_transit_delta_U_flux_J', NaN, ...
        'stage4_sma_to_CHEX_transit_cold_storage_observed_J', NaN, ...
        'stage4_sma_to_CHEX_transit_required_gap_J', Q_required_gap_J, ...
        'stage4_sma_to_CHEX_transit_unaccounted_gap_J', NaN, ...
        'stage4_sma_to_CHEX_transit_unaccounted_gap_ratio', NaN, ...
        'sma_to_CHEX_transport_with_transit_ratio_observed', NaN, ...
        'stage4_sma_to_CHEX_transit_closure_ok', false, ...
        'stage4_sma_to_CHEX_transit_flux_state_consistency_ratio', NaN, ...
        'stage4_sma_to_CHEX_transit_state_source', 'not_cooldown_or_missing_probe_data');
    if strcmp(cold_end_topology_mode, 'r69_symmetric') || contains(lower(model), 'removed_in_r69')
        transit.stage4_sma_to_CHEX_transit_model = 'removed_in_R69_symmetric_direct_CHEX_boundary';
        transit.stage4_sma_to_CHEX_transit_observable = false;
        transit.stage4_sma_to_CHEX_transit_C_J_per_K = 0.0;
        transit.stage4_sma_to_CHEX_transit_volume_ml = 0.0;
        transit.stage4_sma_to_CHEX_transit_delta_U_J = 0.0;
        transit.stage4_sma_to_CHEX_transit_delta_U_state_J = 0.0;
        transit.stage4_sma_to_CHEX_transit_delta_U_flux_J = 0.0;
        transit.stage4_sma_to_CHEX_transit_cold_storage_observed_J = 0.0;
        transit.stage4_sma_to_CHEX_transit_unaccounted_gap_J = Q_required_gap_J;
        transit.stage4_sma_to_CHEX_transit_unaccounted_gap_ratio = safe_abs_ratio(Q_required_gap_J, Q_required_gap_J);
        transit.sma_to_CHEX_transport_with_transit_ratio_observed = safe_abs_ratio(Q_chex_boundary_abs_J, Q_sma_abs_J);
        transit.stage4_sma_to_CHEX_transit_closure_ok = true;
        transit.stage4_sma_to_CHEX_transit_state_source = 'R69_no_transit_pipe_direct_SMA_to_CHEX';
        return;
    end
    if ~strcmpi(stage_name, 'cooldown_exchange')
        transit.stage4_sma_to_CHEX_transit_closure_ok = true;
        return;
    end
    if ~(isfinite(C_transit) && C_transit >= 0 && isfinite(Q_sma_abs_J) && Q_sma_abs_J > 1.0e-12)
        transit.stage4_sma_to_CHEX_transit_state_source = 'missing_capacity_or_sma_boundary_energy';
        return;
    end

    t = get_option_field(observability, 'probe_time_local_s', []);
    mdot = get_option_field(observability, 'mdot_active_kgps_t', []);
    % T_in: Conn2 (V6 chip-side fluid entering cold_subsystem).
    % T_out: TransitPipe.LConn inside cold_subsystem (= ColdSinkPipe.RConn).
    T_in = get_option_field(observability, 'T_transit_pipe_inlet_K_t', ...
        get_option_field(observability, 'T_cold_hx_inlet_fluid_K_t', []));
    T_out = get_option_field(observability, 'T_transit_pipe_outlet_K_t', []);
    if ~(isnumeric(t) && isnumeric(mdot) && isnumeric(T_in) && isnumeric(T_out))
        transit.stage4_sma_to_CHEX_transit_state_source = 'missing_transit_probe_timeseries';
        return;
    end
    if numel(t) < 2 || numel(mdot) ~= numel(t) || numel(T_in) ~= numel(t) || numel(T_out) ~= numel(t)
        transit.stage4_sma_to_CHEX_transit_state_source = 'invalid_transit_probe_timeseries_shape';
        return;
    end
    cp_water = get_option_field(sim_params, 'cp_water', NaN);
    if ~(isfinite(cp_water) && cp_water > 0)
        transit.stage4_sma_to_CHEX_transit_state_source = 'missing_cp_water_for_flux_integral';
        return;
    end
    t = t(:);
    mdot = abs(mdot(:));
    T_in = T_in(:);
    T_out = T_out(:);
    mask = isfinite(t) & isfinite(mdot) & isfinite(T_in) & isfinite(T_out);
    if nnz(mask) < 2
        transit.stage4_sma_to_CHEX_transit_state_source = 'insufficient_finite_transit_probe_samples';
        return;
    end
    t_m = t(mask);
    mdot_m = mdot(mask);
    T_in_m_series = T_in(mask);
    T_out_m_series = T_out(mask);

    % Flux-integral delta_U: positive means transit pipe absorbed heat
    % (gained energy); negative means transit pipe released heat to flow.
    % In stage 4 the inlet (V6 side) is colder than the outlet at the start
    % of flow because the transit fluid is at the previous cycle's warmer
    % rest temperature. As the cold flush proceeds T_out approaches T_in,
    % so the integrand (T_in - T_out) starts negative and approaches zero,
    % giving delta_U_flux < 0 (transit released stored heat into the
    % flow, i.e., it stored COLD: it lost warmth).
    integrand_flux = mdot_m .* cp_water .* (T_in_m_series - T_out_m_series);
    delta_U_flux_J = trapz(t_m, integrand_flux);

    T_in_weighted_mean = weighted_temperature_mean(T_in_m_series, mdot_m);
    T_out_weighted_mean = weighted_temperature_mean(T_out_m_series, mdot_m);
    T_out_first = T_out_m_series(1);
    T_out_last = last_finite_local(T_out_m_series);
    T_in_first = T_in_m_series(1);
    if ~(isfinite(T_state_in))
        % Fallback only if runtime didn't carry transit state forward.
        T_state_in = T_out_first;
    end
    T_state_out = T_out_last;
    if ~(isfinite(T_state_out))
        transit.stage4_sma_to_CHEX_transit_state_source = 'transit_state_out_unavailable_from_outlet_probe';
        return;
    end

    delta_U_state_J = C_transit * (T_state_out - T_state_in);
    % Choose the STATE estimate (C_transit * (T_state_out - T_state_in)) as
    % primary, because the LConn-side probe shares its node with ColdSinkPipe
    % and the flux integral over the shared boundary is polluted by wall heat
    % transfer in the adjacent ColdSinkPipe (which is wall-coupled to
    % ColdSinkMass via cold_sink_fluid_G during cooldown). The state estimate
    % directly reads the internal energy change of TransitPipe between
    % cycles. The flux integral is kept as diagnostic + cross-check via
    % flux_state_consistency_ratio.
    delta_U_J = delta_U_state_J;
    cold_storage_observed_J = max(-delta_U_J, 0.0);
    if ~isfinite(Q_required_gap_J)
        Q_required_gap_J = max(Q_sma_abs_J - Q_chex_boundary_abs_J, 0.0);
    end
    unaccounted_gap_J = Q_required_gap_J - cold_storage_observed_J;
    unaccounted_gap_ratio = abs(unaccounted_gap_J) / max(abs(Q_required_gap_J), 1.0e-12);
    with_transit_ratio = (Q_chex_boundary_abs_J + cold_storage_observed_J) / Q_sma_abs_J;
    if isfinite(delta_U_state_J) && abs(delta_U_state_J) > 1.0e-12
        flux_state_consistency_ratio = delta_U_flux_J / delta_U_state_J;
    else
        flux_state_consistency_ratio = NaN;
    end
    transit.stage4_sma_to_CHEX_transit_observable = true;
    transit.stage4_sma_to_CHEX_transit_T_state_in_K = T_state_in;
    transit.stage4_sma_to_CHEX_transit_T_state_out_K = T_state_out;
    transit.stage4_sma_to_CHEX_transit_T_upstream_mass_mean_K = T_in_weighted_mean;
    transit.stage4_sma_to_CHEX_transit_T_downstream_mass_mean_K = T_out_weighted_mean;
    transit.stage4_sma_to_CHEX_transit_T_inlet_first_K = T_in_first;
    transit.stage4_sma_to_CHEX_transit_T_outlet_first_K = T_out_first;
    transit.stage4_sma_to_CHEX_transit_delta_U_J = delta_U_J;
    transit.stage4_sma_to_CHEX_transit_delta_U_state_J = delta_U_state_J;
    transit.stage4_sma_to_CHEX_transit_delta_U_flux_J = delta_U_flux_J;
    transit.stage4_sma_to_CHEX_transit_cold_storage_observed_J = cold_storage_observed_J;
    transit.stage4_sma_to_CHEX_transit_required_gap_J = Q_required_gap_J;
    transit.stage4_sma_to_CHEX_transit_unaccounted_gap_J = unaccounted_gap_J;
    transit.stage4_sma_to_CHEX_transit_unaccounted_gap_ratio = unaccounted_gap_ratio;
    transit.sma_to_CHEX_transport_with_transit_ratio_observed = with_transit_ratio;
    transit.stage4_sma_to_CHEX_transit_flux_state_consistency_ratio = flux_state_consistency_ratio;
    transit.stage4_sma_to_CHEX_transit_closure_ok = ...
        isfinite(with_transit_ratio) && with_transit_ratio >= 0.80 && ...
        isfinite(unaccounted_gap_ratio) && unaccounted_gap_ratio <= 0.20;
    transit.stage4_sma_to_CHEX_transit_state_source = ...
        'simulink_TL_TransitPipe_LConn_probe_with_flux_integral_no_residual_closure_v2';
end

function value = last_finite_local(values)
    values = values(:);
    idx = find(isfinite(values), 1, 'last');
    if isempty(idx)
        value = NaN;
    else
        value = values(idx);
    end
end

function [Q_latent_J, reason, report] = compute_stage4_latent_diagnostic(sim_params, stage_config)
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    xi_in = get_option_field(sim_params, 'sma_xi_in_51', []);
    if isnumeric(xi_in)
        xi_in = xi_in(:);
    else
        xi_in = [];
    end
    xi_out = xi_in; % Current exchange backend updates temperature only; phase fraction is carried unchanged.
    if isempty(xi_in) || ~any(isfinite(xi_in))
        xi_avg_in = NaN;
        xi_max_in = NaN;
        delta_xi_avg = NaN;
        delta_xi_max_abs = NaN;
        Q_latent_J = NaN;
        reason = 'xi_unavailable_for_stage4_latent_diagnostic';
    else
        xi_avg_in = mean(xi_in(isfinite(xi_in)));
        xi_max_in = max(xi_in(isfinite(xi_in)));
        delta_xi = xi_out - xi_in;
        delta_xi_avg = mean(delta_xi(isfinite(delta_xi)));
        delta_xi_max_abs = max(abs(delta_xi(isfinite(delta_xi))));
        Q_latent_J = 0.0;
        if ~strcmpi(stage_name, 'cooldown_exchange')
            reason = 'not_cooldown_exchange';
        elseif xi_max_in <= 1.0e-10
            reason = 'xi_zero_before_cooldown';
        elseif delta_xi_max_abs <= 1.0e-12
            reason = 'no_phase_change_in_cooldown_temperature_only_exchange';
        else
            reason = 'latent_balance_solver_not_available_for_nonzero_delta_xi';
            Q_latent_J = NaN;
        end
    end
    report = struct( ...
        'xi_stage4_in_avg', xi_avg_in, ...
        'xi_stage4_in_max', xi_max_in, ...
        'xi_stage4_out_avg', xi_avg_in, ...
        'xi_stage4_out_max', xi_max_in, ...
        'delta_xi_stage4_avg', delta_xi_avg, ...
        'delta_xi_stage4_max_abs', delta_xi_max_abs, ...
        'Q_latent_balance_est_J_diagnostic_only', NaN);
end

function [Q_return_J, source, split] = integrate_hot_return_enthalpy(stage_config, sim_params, observability, T_reference_K)
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    split = default_hot_return_split();
    if ~strcmpi(stage_name, 'hold_exchange')
        Q_return_J = NaN;
        source = 'not_hold_exchange';
        return;
    end

    cp_water = get_option_field(sim_params, 'cp_water', 4180.0);
    t = get_option_field(observability, 'probe_time_local_s', []);
    mdot = get_option_field(observability, 'mdot_active_kgps_t', []);
    T_in = get_option_field(observability, 'T_sma_fluid_in_K_t', ...
        get_option_field(observability, 'T_probe_sma_stage2_port1_v1_side_K_t', []));
    T_return = get_option_field(observability, 'T_sma_fluid_out_K_t', ...
        get_option_field(observability, 'T_sma_fluid_out_K_t', []));
    if isempty(T_reference_K) || ~isfinite(T_reference_K)
        T_reference_K = get_option_field(sim_params, 'hot_fluid_buffer_T_init', ...
            get_option_field(sim_params, 'hot_sink_T_init', NaN));
    end

    if isnumeric(t) && isnumeric(mdot) && isnumeric(T_in) && isnumeric(T_return) && ...
            numel(t) >= 2 && numel(mdot) == numel(t) && numel(T_in) == numel(t) && numel(T_return) == numel(t) && ...
            isfinite(T_reference_K)
        t = t(:);
        mdot = abs(mdot(:));
        T_in = T_in(:);
        T_return = T_return(:);
        mask = isfinite(t) & isfinite(mdot) & isfinite(T_in) & isfinite(T_return);
        if nnz(mask) >= 2
            t_m = t(mask);
            % Stage 2 official hot-end input is the enthalpy gained by the
            % active HTF packet while crossing SMA, not the small terminal
            % temperature rise of the finite hot-end body.
            power_W = mdot(mask) .* cp_water .* (T_return(mask) - T_in(mask));
            Q_return_J = trapz(t_m, power_W);
            split.Q_hot_return_positive_heating_J = trapz(t_m, max(power_W, 0.0));
            split.Q_hot_return_negative_cooling_slug_J = trapz(t_m, min(power_W, 0.0));
            if abs(split.Q_hot_return_positive_heating_J) > 1.0e-12
                split.hot_slug_to_heating_ratio = abs(split.Q_hot_return_negative_cooling_slug_J) / ...
                    abs(split.Q_hot_return_positive_heating_J);
            else
                split.hot_slug_to_heating_ratio = NaN;
            end
            split = attach_hot_temperature_stats(split, T_return(mask));
            source = 'measured_hot_return_enthalpy_integral_50point_timeseries_SMA_out_minus_in';
            return;
        end
    end

    T_in_terminal = get_option_field(observability, 'sma_hold_inlet_fluid_temp_out', ...
        get_option_field(observability, 'probe_sma_stage2_port1_v1_side_T_K', NaN));
    T_return_terminal = get_option_field(observability, 'hot_hx_inlet_fluid_temp_out', ...
        get_option_field(observability, 'sma_hold_outlet_fluid_temp_out', NaN));
    mdot_terminal = abs(get_option_field(observability, 'sma_outlet_branch_mass_flow_kgps', ...
        get_option_field(observability, 'mass_flow_v3_sma_to_hot_kgps', NaN)));
    dt_s = get_option_field(stage_config, 'stop_time_s', NaN);
    if all(isfinite([T_in_terminal, T_return_terminal, mdot_terminal, dt_s])) && dt_s > 0
        Q_return_J = mdot_terminal * cp_water * (T_return_terminal - T_in_terminal) * dt_s;
        split.Q_hot_return_positive_heating_J = max(Q_return_J, 0.0);
        split.Q_hot_return_negative_cooling_slug_J = min(Q_return_J, 0.0);
        if abs(split.Q_hot_return_positive_heating_J) > 1.0e-12
            split.hot_slug_to_heating_ratio = abs(split.Q_hot_return_negative_cooling_slug_J) / ...
                abs(split.Q_hot_return_positive_heating_J);
        end
        split.T_hot_return_first_K = T_return_terminal;
        split.T_hot_return_max_K = T_return_terminal;
        split.T_hot_return_min_K = T_return_terminal;
        split.T_hot_return_last_K = T_return_terminal;
        source = 'measured_hot_return_enthalpy_terminal_approximation_SMA_out_minus_in';
    else
        Q_return_J = NaN;
        source = 'hot_return_enthalpy_unavailable';
    end
end

function split = default_hot_return_split()
    split = struct( ...
        'Q_hot_return_positive_heating_J', NaN, ...
        'Q_hot_return_negative_cooling_slug_J', NaN, ...
        'hot_slug_to_heating_ratio', NaN, ...
        'T_hot_return_first_K', NaN, ...
        'T_hot_return_max_K', NaN, ...
        'T_hot_return_min_K', NaN, ...
        'T_hot_return_last_K', NaN);
end

function split = attach_hot_temperature_stats(split, T_return)
    T_return = T_return(:);
    finite_return = T_return(isfinite(T_return));
    if ~isempty(finite_return)
        split.T_hot_return_first_K = finite_return(1);
        split.T_hot_return_max_K = max(finite_return);
        split.T_hot_return_min_K = min(finite_return);
        split.T_hot_return_last_K = finite_return(end);
    end
end

function [Q_sma_to_htf_J, source, report] = integrate_stage4_sma_to_htf_enthalpy(stage_config, sim_params, observability)
    report = struct( ...
        'T_stage4_SMA_in_probe_name', 'T_sma_fluid_in_K_t / probe_sma_stage4_port3_v4_side_T_K', ...
        'T_stage4_SMA_out_probe_name', 'T_sma_fluid_out_K_t / probe_sma_stage4_port4_v6_side_T_K');
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    if ~strcmpi(stage_name, 'cooldown_exchange')
        Q_sma_to_htf_J = NaN;
        source = 'not_cooldown_exchange';
        return;
    end

    cp_water = get_option_field(sim_params, 'cp_water', 4180.0);
    t = get_option_field(observability, 'probe_time_local_s', []);
    mdot = get_option_field(observability, 'mdot_active_kgps_t', []);
    T_in = get_option_field(observability, 'T_sma_fluid_in_K_t', ...
        get_option_field(observability, 'T_probe_sma_stage4_port3_v4_side_K_t', []));
    T_out = get_option_field(observability, 'T_sma_fluid_out_K_t', ...
        get_option_field(observability, 'T_probe_sma_stage4_port4_v6_side_K_t', ...
        get_option_field(observability, 'T_cold_supply_K_t', [])));
    [Q_fluid_gain_J, ok] = integrate_enthalpy_from_series(t, mdot, T_in, T_out, cp_water);
    if ok
        Q_sma_to_htf_J = -Q_fluid_gain_J;
        source = 'stage4_SMA_boundary_50point_timeseries_positive_heat_to_SMA';
        return;
    end

    T_in_terminal = get_option_field(observability, 'sma_cooldown_inlet_fluid_temp_out', NaN);
    T_out_terminal = get_option_field(observability, 'sma_cooldown_outlet_fluid_temp_out', ...
        get_option_field(observability, 'cold_hx_inlet_fluid_temp_out', NaN));
    mdot_terminal = abs(get_option_field(observability, 'sma_outlet_branch_mass_flow_kgps', ...
        get_option_field(observability, 'mass_flow_v6_sma_to_chip_cold_kgps', NaN)));
    dt_s = get_option_field(stage_config, 'stop_time_s', NaN);
    if all(isfinite([T_in_terminal, T_out_terminal, mdot_terminal, dt_s])) && dt_s > 0
        Q_sma_to_htf_J = -mdot_terminal * cp_water * (T_out_terminal - T_in_terminal) * dt_s;
        source = 'stage4_SMA_boundary_terminal_approximation_positive_heat_to_SMA';
    else
        Q_sma_to_htf_J = NaN;
        source = 'stage4_SMA_boundary_enthalpy_unavailable';
    end
end

function [Q_chex_J, source, split] = integrate_stage4_chex_enthalpy(stage_config, sim_params, observability, T_reference_K)
    split = default_stage4_chex_split();
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    if ~strcmpi(stage_name, 'cooldown_exchange')
        Q_chex_J = NaN;
        source = 'not_cooldown_exchange';
        return;
    end

    cp_water = get_option_field(sim_params, 'cp_water', 4180.0);
    if isempty(T_reference_K) || ~isfinite(T_reference_K)
        T_reference_K = get_option_field(sim_params, 'cold_fluid_buffer_T_init', ...
            get_option_field(sim_params, 'cold_sink_T_init', NaN));
    end
    t = get_option_field(observability, 'probe_time_local_s', []);
    mdot = get_option_field(observability, 'mdot_active_kgps_t', []);
    T_sink = get_option_field(observability, 'T_cold_sink_K_t', []);
    T_in = get_option_field(observability, 'T_stage4_CHEX_inlet_fluid_K_t', []);
    T_out = get_option_field(observability, 'T_stage4_CHEX_outlet_fluid_K_t', []);
    cold_end_topology_mode = lower(strtrim(char(string(get_option_field(sim_params, ...
        'cold_end_topology_mode', 'r69_symmetric')))));
    if strcmp(cold_end_topology_mode, 'r69_symmetric')
        T_sma_out = get_option_field(observability, 'T_sma_fluid_out_K_t', []);
        [T_in, T_out, split.stage4_CHEX_probe_order_correction] = ...
            orient_chex_inlet_outlet_by_sma_outlet(T_in, T_out, T_sma_out);
    end
    [Q_chex_J, ok, t_m, mdot_m, T_in_m, T_out_m] = integrate_enthalpy_from_series(t, mdot, T_in, T_out, cp_water);
    if ok
        if strcmp(cold_end_topology_mode, 'r69_symmetric')
            split.T_stage4_CHEX_in_probe_name = 'R69 oriented single ColdSinkPipe endpoint closest to SMA outlet';
            split.T_stage4_CHEX_out_probe_name = 'R69 oriented opposite single ColdSinkPipe endpoint';
            source = 'stage4_CHEX_R69_single_coldsinkpipe_inlet_outlet_50point_timeseries';
        else
            split.stage4_CHEX_probe_order_correction = 'explicit_post_transit_inlet_no_legacy_orientation';
            split.T_stage4_CHEX_in_probe_name = 'T_stage4_CHEX_inlet_fluid_K_t / TransitPipe_V6_to_CHEX.LConn / ColdSinkHXPipe.RConn';
            split.T_stage4_CHEX_out_probe_name = 'T_stage4_CHEX_outlet_fluid_K_t / ColdSinkHXPipe.LConn before ColdSinkReturnPipe';
            source = 'stage4_CHEX_split_hxpipe_inlet_outlet_50point_timeseries';
        end
    else
        T_in = get_option_field(observability, 'T_cold_hx_inlet_fluid_K_t', ...
            get_option_field(observability, 'T_cold_supply_K_t', []));
        T_out = get_option_field(observability, 'T_cold_hx_outlet_fluid_K_t', ...
            get_option_field(observability, 'T_cold_return_K_t', []));
        T_sma_out = get_option_field(observability, 'T_sma_fluid_out_K_t', []);
        [T_in, T_out, split.stage4_CHEX_probe_order_correction] = ...
            orient_chex_inlet_outlet_by_sma_outlet(T_in, T_out, T_sma_out);
        if contains(split.stage4_CHEX_probe_order_correction, 'swapped')
            split.T_stage4_CHEX_in_probe_name = 'T_cold_hx_outlet_fluid_K_t / cold_hx_outlet_fluid_temp_out / probe_chip_to_cold_junction_T_K (legacy oriented as CHEX inlet because it matches SMA outlet)';
            split.T_stage4_CHEX_out_probe_name = 'T_cold_hx_inlet_fluid_K_t / cold_hx_inlet_fluid_temp_out / probe_chip_pipe_port_conn2_v6_sma_side_T_K (legacy oriented as CHEX outlet)';
        end
        [Q_chex_J, ok, t_m, mdot_m, T_in_m, T_out_m] = integrate_enthalpy_from_series(t, mdot, T_in, T_out, cp_water);
        if ok
            source = 'stage4_CHEX_legacy_oriented_inlet_outlet_50point_timeseries';
        end
    end
    if ok
        power_W = mdot_m .* cp_water .* (T_out_m - T_in_m);
        split.Q_stage4_CHEX_positive_warming_J = trapz(t_m, max(power_W, 0.0));
        split.Q_stage4_CHEX_negative_cooling_J = trapz(t_m, min(power_W, 0.0));
        split.Q_stage4_CHEX_inlet_boundary_J = integrate_boundary_enthalpy(t_m, mdot_m, T_in_m, T_reference_K, cp_water);
        split.Q_stage4_CHEX_outlet_boundary_J = integrate_boundary_enthalpy(t_m, mdot_m, T_out_m, T_reference_K, cp_water);
        split.Q_cold_return_after_CHEX_boundary_enthalpy_J = Q_chex_J;
        split.T_stage4_CHEX_in_time_mean_K = mean(T_in_m);
        split.T_stage4_CHEX_out_time_mean_K = mean(T_out_m);
        split.T_stage4_CHEX_in_mass_weighted_mean_K = weighted_temperature_mean(T_in_m, mdot_m);
        split.T_stage4_CHEX_out_mass_weighted_mean_K = weighted_temperature_mean(T_out_m, mdot_m);
        split.T_stage4_CHEX_terminal_pair_mean_K = mean([T_in_m(end), T_out_m(end)]);
        split.raw_cold_return_positive_warm_slug_J = split.Q_stage4_CHEX_positive_warming_J;
        split.raw_cold_return_negative_cooling_J = split.Q_stage4_CHEX_negative_cooling_J;
        if abs(split.Q_stage4_CHEX_negative_cooling_J) > 1.0e-12
            split.warm_slug_to_cooling_ratio = abs(split.Q_stage4_CHEX_positive_warming_J) / ...
                abs(split.Q_stage4_CHEX_negative_cooling_J);
            split.raw_cold_return_warm_slug_to_cooling_ratio = split.warm_slug_to_cooling_ratio;
        end
        split = attach_cold_supply_temperature_stats(split, T_in_m);
        split = attach_temperature_stats(split, T_out_m, T_sink, isfinite(T_out_m));
        split.stage4_CHEX_temperature_direction_ok = chex_temperature_direction_ok(T_in_m, T_out_m, T_sink);
        return;
    end

    T_in_terminal = get_option_field(observability, 'cold_hx_inlet_fluid_temp_out', NaN);
    T_out_terminal = get_option_field(observability, 'cold_hx_outlet_fluid_temp_out', NaN);
    T_sma_out_terminal = get_option_field(observability, 'sma_cooldown_outlet_fluid_temp_out', NaN);
    if all(isfinite([T_in_terminal, T_out_terminal, T_sma_out_terminal])) && ...
            abs(T_out_terminal - T_sma_out_terminal) < abs(T_in_terminal - T_sma_out_terminal)
        tmp = T_in_terminal;
        T_in_terminal = T_out_terminal;
        T_out_terminal = tmp;
        split.stage4_CHEX_probe_order_correction = 'terminal_swap_cold_hx_outlet_probe_matches_SMA_outlet';
        split.T_stage4_CHEX_in_probe_name = 'cold_hx_outlet_fluid_temp_out / probe_chip_to_cold_junction_T_K (terminal-oriented as CHEX inlet)';
        split.T_stage4_CHEX_out_probe_name = 'cold_hx_inlet_fluid_temp_out / probe_chip_pipe_port_conn2_v6_sma_side_T_K (terminal-oriented as CHEX outlet)';
    end
    mdot_terminal = abs(get_option_field(observability, 'mass_flow_v6_sma_to_chip_cold_kgps', ...
        get_option_field(observability, 'sma_outlet_branch_mass_flow_kgps', NaN)));
    dt_s = get_option_field(stage_config, 'stop_time_s', NaN);
    if all(isfinite([T_in_terminal, T_out_terminal, mdot_terminal, dt_s])) && dt_s > 0
        Q_chex_J = mdot_terminal * cp_water * (T_out_terminal - T_in_terminal) * dt_s;
        split.Q_stage4_CHEX_positive_warming_J = max(Q_chex_J, 0.0);
        split.Q_stage4_CHEX_negative_cooling_J = min(Q_chex_J, 0.0);
        split.Q_stage4_CHEX_inlet_boundary_J = mdot_terminal * cp_water * (T_in_terminal - T_reference_K) * dt_s;
        split.Q_stage4_CHEX_outlet_boundary_J = mdot_terminal * cp_water * (T_out_terminal - T_reference_K) * dt_s;
        split.Q_cold_return_after_CHEX_boundary_enthalpy_J = Q_chex_J;
        split.T_stage4_CHEX_in_time_mean_K = T_in_terminal;
        split.T_stage4_CHEX_out_time_mean_K = T_out_terminal;
        split.T_stage4_CHEX_in_mass_weighted_mean_K = T_in_terminal;
        split.T_stage4_CHEX_out_mass_weighted_mean_K = T_out_terminal;
        split.T_stage4_CHEX_terminal_pair_mean_K = mean([T_in_terminal, T_out_terminal]);
        split.raw_cold_return_positive_warm_slug_J = split.Q_stage4_CHEX_positive_warming_J;
        split.raw_cold_return_negative_cooling_J = split.Q_stage4_CHEX_negative_cooling_J;
        if abs(split.Q_stage4_CHEX_negative_cooling_J) > 1.0e-12
            split.warm_slug_to_cooling_ratio = abs(split.Q_stage4_CHEX_positive_warming_J) / ...
                abs(split.Q_stage4_CHEX_negative_cooling_J);
            split.raw_cold_return_warm_slug_to_cooling_ratio = split.warm_slug_to_cooling_ratio;
        end
        split.T_cold_supply_first_K = T_in_terminal;
        split.T_cold_supply_max_K = T_in_terminal;
        split.T_cold_supply_min_K = T_in_terminal;
        split.T_cold_supply_last_K = T_in_terminal;
        split.T_cold_supply_first_max_min_last_K = [T_in_terminal, T_in_terminal, T_in_terminal, T_in_terminal];
        split.T_cold_return_first_K = T_out_terminal;
        split.T_cold_return_max_K = T_out_terminal;
        split.T_cold_return_min_K = T_out_terminal;
        split.T_cold_return_last_K = T_out_terminal;
        split.T_cold_return_first_max_min_last_K = [T_out_terminal, T_out_terminal, T_out_terminal, T_out_terminal];
        split.stage4_CHEX_temperature_direction_ok = true;
        source = 'stage4_CHEX_external_inlet_outlet_terminal_approximation';
    else
        Q_chex_J = NaN;
        source = 'stage4_CHEX_inlet_outlet_enthalpy_unavailable';
    end
end

function [Q_J, ok, t_m, mdot_m, T_in_m, T_out_m] = integrate_enthalpy_from_series(t, mdot, T_in, T_out, cp_water)
    Q_J = NaN;
    ok = false;
    t_m = [];
    mdot_m = [];
    T_in_m = [];
    T_out_m = [];
    if ~(isnumeric(t) && isnumeric(mdot) && isnumeric(T_in) && isnumeric(T_out))
        return;
    end
    if numel(t) < 2 || numel(mdot) ~= numel(t) || numel(T_in) ~= numel(t) || numel(T_out) ~= numel(t)
        return;
    end
    t = t(:);
    mdot = abs(mdot(:));
    T_in = T_in(:);
    T_out = T_out(:);
    mask = isfinite(t) & isfinite(mdot) & isfinite(T_in) & isfinite(T_out);
    if nnz(mask) < 2
        return;
    end
    t_m = t(mask);
    mdot_m = mdot(mask);
    T_in_m = T_in(mask);
    T_out_m = T_out(mask);
    Q_J = trapz(t_m, mdot_m .* cp_water .* (T_out_m - T_in_m));
    ok = true;
end

function Q_boundary_J = integrate_boundary_enthalpy(t, mdot, T, T_reference_K, cp_water)
    if isfinite(T_reference_K) && numel(t) >= 2 && numel(mdot) == numel(t) && numel(T) == numel(t)
        Q_boundary_J = trapz(t(:), abs(mdot(:)) .* cp_water .* (T(:) - T_reference_K));
    else
        Q_boundary_J = NaN;
    end
end

function value = weighted_temperature_mean(T, weights)
    value = NaN;
    if ~(isnumeric(T) && isnumeric(weights) && numel(T) == numel(weights))
        return;
    end
    T = T(:);
    weights = abs(weights(:));
    mask = isfinite(T) & isfinite(weights) & weights > 0;
    if any(mask)
        value = sum(T(mask) .* weights(mask)) / sum(weights(mask));
    else
        finite_T = T(isfinite(T));
        if ~isempty(finite_T)
            value = mean(finite_T);
        end
    end
end

function [T_in_oriented, T_out_oriented, correction] = orient_chex_inlet_outlet_by_sma_outlet(T_in_raw, T_out_raw, T_sma_out)
    T_in_oriented = T_in_raw;
    T_out_oriented = T_out_raw;
    correction = 'as_logged';
    if ~(isnumeric(T_in_raw) && isnumeric(T_out_raw) && isnumeric(T_sma_out))
        correction = 'not_evaluated_non_numeric';
        return;
    end
    if numel(T_in_raw) ~= numel(T_out_raw) || numel(T_in_raw) ~= numel(T_sma_out)
        correction = 'not_evaluated_size_mismatch';
        return;
    end
    T_in_v = T_in_raw(:);
    T_out_v = T_out_raw(:);
    T_sma_v = T_sma_out(:);
    mask = isfinite(T_in_v) & isfinite(T_out_v) & isfinite(T_sma_v);
    if nnz(mask) < 2
        correction = 'not_evaluated_insufficient_finite_samples';
        return;
    end
    d_in = median(abs(T_in_v(mask) - T_sma_v(mask)));
    d_out = median(abs(T_out_v(mask) - T_sma_v(mask)));
    if isfinite(d_in) && isfinite(d_out) && d_out + 1.0e-9 < d_in
        T_in_oriented = T_out_raw;
        T_out_oriented = T_in_raw;
        correction = 'swapped_cold_hx_outlet_probe_matches_SMA_outlet_stage4_flow';
    end
end

function ok = chex_temperature_direction_ok(T_in, T_out, T_sink)
    ok = true;
    if ~(isnumeric(T_sink) && numel(T_sink) == numel(T_in))
        return;
    end
    T_in = T_in(:);
    T_out = T_out(:);
    T_sink = T_sink(:);
    d_fluid = T_out - T_in;
    d_target = T_sink - T_in;
    mask = isfinite(d_fluid) & isfinite(d_target) & abs(d_target) > 1.0e-5 & abs(d_fluid) > 1.0e-6;
    if any(mask)
        d_fluid_m = d_fluid(mask);
        d_target_m = d_target(mask);
        wrong = d_fluid_m .* d_target_m < -1.0e-7;
        total_motion = sum(abs(d_fluid_m));
        opposite_motion = sum(abs(d_fluid_m(wrong)));
        ok = opposite_motion <= 0.05 * max(total_motion, eps);
    end
end

function split = default_stage4_chex_split()
    split = default_cold_return_split();
    split.Q_stage4_CHEX_inlet_boundary_J = NaN;
    split.Q_stage4_CHEX_outlet_boundary_J = NaN;
    split.Q_stage4_CHEX_positive_warming_J = NaN;
    split.Q_stage4_CHEX_negative_cooling_J = NaN;
    split.T_stage4_CHEX_in_time_mean_K = NaN;
    split.T_stage4_CHEX_out_time_mean_K = NaN;
    split.T_stage4_CHEX_in_mass_weighted_mean_K = NaN;
    split.T_stage4_CHEX_out_mass_weighted_mean_K = NaN;
    split.T_stage4_CHEX_terminal_pair_mean_K = NaN;
    split.stage4_CHEX_temperature_direction_ok = false;
    split.stage4_CHEX_probe_order_correction = 'not_evaluated';
    split.T_stage4_CHEX_in_probe_name = 'T_cold_hx_inlet_fluid_K_t / cold_hx_inlet_fluid_temp_out / probe_chip_pipe_port_conn2_v6_sma_side_T_K';
    split.T_stage4_CHEX_out_probe_name = 'T_cold_hx_outlet_fluid_K_t / cold_hx_outlet_fluid_temp_out / probe_chip_to_cold_junction_T_K';
    split.T_stage4_ColdSinkMass_probe_name = 'T_cold_sink_K_t / cold_sink_temp_out';
    split.T_stage4_ColdFluidBuffer_probe_name = 'cold_buffer_temp_out';
    split.stage4_probe_contract_note = ['Stage4 official path: SMA outlet enters CHEX/ColdSinkPipe at Conn2/V6 side, ', ...
        'exits at Conn1/cold-return side; historical chip_* aliases are diagnostic only.'];
end

function [Q_return_J, source, split] = integrate_cold_return_enthalpy(stage_config, sim_params, observability, T_reference_K)
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    split = default_cold_return_split();
    if ~strcmpi(stage_name, 'cooldown_exchange')
        Q_return_J = NaN;
        source = 'not_cooldown_exchange';
        return;
    end

    cp_water = get_option_field(sim_params, 'cp_water', 4180.0);
    t = get_option_field(observability, 'probe_time_local_s', []);
    mdot = get_option_field(observability, 'mdot_active_kgps_t', []);
    T_supply = get_option_field(observability, 'T_sma_fluid_out_K_t', ...
        get_option_field(observability, 'T_probe_sma_stage4_port4_v6_side_K_t', ...
        get_option_field(observability, 'T_cold_supply_K_t', [])));
    T_in = get_option_field(observability, 'T_sma_fluid_in_K_t', ...
        get_option_field(observability, 'T_probe_sma_stage4_port3_v4_side_K_t', []));
    T_return = get_option_field(observability, 'T_cold_return_K_t', ...
        get_option_field(observability, 'T_cold_hx_outlet_fluid_K_t', []));
    if isempty(T_reference_K) || ~isfinite(T_reference_K)
        T_reference_K = get_option_field(sim_params, 'cold_fluid_buffer_T_init', ...
            get_option_field(sim_params, 'cold_sink_T_init', NaN));
    end

    if isnumeric(t) && isnumeric(mdot) && isnumeric(T_supply) && isnumeric(T_in) && ...
            numel(t) >= 2 && numel(mdot) == numel(t) && numel(T_supply) == numel(t) && ...
            numel(T_in) == numel(t) && ...
            isfinite(T_reference_K)
        t = t(:);
        mdot = abs(mdot(:));
        T_supply = T_supply(:);
        T_in = T_in(:);
        mask = isfinite(t) & isfinite(mdot) & isfinite(T_supply) & isfinite(T_in);
        if nnz(mask) >= 2
            t_m = t(mask);
            power_W = mdot(mask) .* cp_water .* (T_supply(mask) - T_in(mask));
            Q_return_J = trapz(t_m, power_W);
            split.Q_cold_return_positive_warm_slug_J = trapz(t_m, max(power_W, 0.0));
            split.Q_cold_return_negative_cooling_J = trapz(t_m, min(power_W, 0.0));
            if abs(split.Q_cold_return_negative_cooling_J) > 1.0e-12
                split.warm_slug_to_cooling_ratio = abs(split.Q_cold_return_positive_warm_slug_J) / ...
                    abs(split.Q_cold_return_negative_cooling_J);
            else
                split.warm_slug_to_cooling_ratio = NaN;
            end
            split = attach_cold_supply_temperature_stats(split, T_supply(mask));
            [split, raw_mask] = attach_raw_cold_return_diagnostics(split, t, mdot, T_return, ...
                T_reference_K, cp_water);
            split = attach_temperature_stats(split, T_return, ...
                get_option_field(observability, 'T_cold_sink_K_t', []), raw_mask);
            source = 'measured_cold_supply_boundary_enthalpy_integral_50point_timeseries_SMA_out_minus_in';
            return;
        end
    end

    T_in_terminal = get_option_field(observability, 'sma_cooldown_inlet_fluid_temp_out', NaN);
    T_supply_terminal = get_option_field(observability, 'sma_cooldown_outlet_fluid_temp_out', ...
        get_option_field(observability, 'cold_hx_inlet_fluid_temp_out', NaN));
    T_return_terminal = get_option_field(observability, 'cold_hx_outlet_fluid_temp_out', NaN);
    mdot_terminal = abs(get_option_field(observability, 'sma_outlet_branch_mass_flow_kgps', ...
        get_option_field(observability, 'mass_flow_v6_sma_to_chip_cold_kgps', NaN)));
    dt_s = get_option_field(stage_config, 'stop_time_s', NaN);
    if all(isfinite([T_in_terminal, T_supply_terminal, mdot_terminal, dt_s])) && dt_s > 0
        Q_return_J = mdot_terminal * cp_water * (T_supply_terminal - T_in_terminal) * dt_s;
        split.Q_cold_return_positive_warm_slug_J = max(Q_return_J, 0.0);
        split.Q_cold_return_negative_cooling_J = min(Q_return_J, 0.0);
        if abs(split.Q_cold_return_negative_cooling_J) > 1.0e-12
            split.warm_slug_to_cooling_ratio = abs(split.Q_cold_return_positive_warm_slug_J) / ...
                abs(split.Q_cold_return_negative_cooling_J);
        end
        split.T_cold_supply_first_K = T_supply_terminal;
        split.T_cold_supply_max_K = T_supply_terminal;
        split.T_cold_supply_min_K = T_supply_terminal;
        split.T_cold_supply_last_K = T_supply_terminal;
        split.T_cold_supply_first_max_min_last_K = [T_supply_terminal, T_supply_terminal, T_supply_terminal, T_supply_terminal];
        if isfinite(T_return_terminal)
            split.T_cold_return_first_K = T_return_terminal;
            split.T_cold_return_max_K = T_return_terminal;
            split.T_cold_return_min_K = T_return_terminal;
            split.T_cold_return_last_K = T_return_terminal;
            split.T_cold_return_first_max_min_last_K = [T_return_terminal, T_return_terminal, T_return_terminal, T_return_terminal];
        end
        source = 'measured_cold_supply_boundary_enthalpy_terminal_approximation_SMA_out_minus_in';
    else
        Q_return_J = NaN;
        source = 'cold_supply_boundary_enthalpy_unavailable';
    end
end

function split = default_cold_return_split()
    split = struct( ...
        'Q_cold_return_positive_warm_slug_J', NaN, ...
        'Q_cold_return_negative_cooling_J', NaN, ...
        'Q_cold_return_after_CHEX_boundary_enthalpy_J', NaN, ...
        'raw_cold_return_positive_warm_slug_J', NaN, ...
        'raw_cold_return_negative_cooling_J', NaN, ...
        'raw_cold_return_warm_slug_to_cooling_ratio', NaN, ...
        'warm_slug_to_cooling_ratio', NaN, ...
        'T_cold_supply_first_K', NaN, ...
        'T_cold_supply_max_K', NaN, ...
        'T_cold_supply_min_K', NaN, ...
        'T_cold_supply_last_K', NaN, ...
        'T_cold_supply_first_max_min_last_K', [NaN, NaN, NaN, NaN], ...
        'T_cold_return_first_K', NaN, ...
        'T_cold_return_max_K', NaN, ...
        'T_cold_return_min_K', NaN, ...
        'T_cold_return_last_K', NaN, ...
        'T_cold_return_first_max_min_last_K', [NaN, NaN, NaN, NaN], ...
        'T_cold_sink_first_K', NaN, ...
        'T_cold_sink_max_K', NaN, ...
        'T_cold_sink_min_K', NaN, ...
        'T_cold_sink_last_K', NaN, ...
        'T_cold_sink_first_max_min_last_K', [NaN, NaN, NaN, NaN]);
end

function split = attach_cold_supply_temperature_stats(split, T_supply)
    T_supply = T_supply(:);
    finite_supply = T_supply(isfinite(T_supply));
    if ~isempty(finite_supply)
        split.T_cold_supply_first_K = finite_supply(1);
        split.T_cold_supply_max_K = max(finite_supply);
        split.T_cold_supply_min_K = min(finite_supply);
        split.T_cold_supply_last_K = finite_supply(end);
        split.T_cold_supply_first_max_min_last_K = [ ...
            split.T_cold_supply_first_K, split.T_cold_supply_max_K, ...
            split.T_cold_supply_min_K, split.T_cold_supply_last_K];
    end
end

function [split, raw_mask] = attach_raw_cold_return_diagnostics(split, t, mdot, T_return, T_reference_K, cp_water)
    raw_mask = false(size(t(:)));
    if ~(isnumeric(T_return) && numel(T_return) == numel(t))
        return;
    end
    T_return = T_return(:);
    t = t(:);
    mdot = abs(mdot(:));
    raw_mask = isfinite(t) & isfinite(mdot) & isfinite(T_return) & isfinite(T_reference_K);
    if nnz(raw_mask) < 2
        return;
    end
    raw_t = t(raw_mask);
    raw_power_W = mdot(raw_mask) .* cp_water .* (T_return(raw_mask) - T_reference_K);
    split.Q_cold_return_after_CHEX_boundary_enthalpy_J = trapz(raw_t, raw_power_W);
    split.raw_cold_return_positive_warm_slug_J = trapz(raw_t, max(raw_power_W, 0.0));
    split.raw_cold_return_negative_cooling_J = trapz(raw_t, min(raw_power_W, 0.0));
    if abs(split.raw_cold_return_negative_cooling_J) > 1.0e-12
        split.raw_cold_return_warm_slug_to_cooling_ratio = ...
            abs(split.raw_cold_return_positive_warm_slug_J) / ...
            abs(split.raw_cold_return_negative_cooling_J);
    end
end

function split = attach_temperature_stats(split, T_return, T_sink_all, mask)
    T_return = T_return(:);
    if nargin >= 4 && isnumeric(mask) && numel(mask) == numel(T_return)
        T_return = T_return(logical(mask(:)));
    end
    finite_return = T_return(isfinite(T_return));
    if ~isempty(finite_return)
        split.T_cold_return_first_K = finite_return(1);
        split.T_cold_return_max_K = max(finite_return);
        split.T_cold_return_min_K = min(finite_return);
        split.T_cold_return_last_K = finite_return(end);
        split.T_cold_return_first_max_min_last_K = [ ...
            split.T_cold_return_first_K, split.T_cold_return_max_K, ...
            split.T_cold_return_min_K, split.T_cold_return_last_K];
    end

    if isnumeric(T_sink_all) && numel(T_sink_all) == numel(mask)
        T_sink = T_sink_all(mask);
    elseif isnumeric(T_sink_all)
        T_sink = T_sink_all(:);
    else
        T_sink = [];
    end
    finite_sink = T_sink(isfinite(T_sink));
    if ~isempty(finite_sink)
        split.T_cold_sink_first_K = finite_sink(1);
        split.T_cold_sink_max_K = max(finite_sink);
        split.T_cold_sink_min_K = min(finite_sink);
        split.T_cold_sink_last_K = finite_sink(end);
        split.T_cold_sink_first_max_min_last_K = [ ...
            split.T_cold_sink_first_K, split.T_cold_sink_max_K, ...
            split.T_cold_sink_min_K, split.T_cold_sink_last_K];
    end
end

function value = min_finite(values)
    values = values(:);
    values = values(isfinite(values));
    if isempty(values)
        value = NaN;
    else
        value = min(values);
    end
end

function value = max_abs_finite(values)
    values = values(:);
    values = values(isfinite(values));
    if isempty(values)
        value = NaN;
    else
        [~, idx] = max(abs(values));
        value = values(idx);
    end
end

function topology = build_sma_flow_topology(stage_config)
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    model_name = char(string(get_option_field(stage_config, 'model_name', 'heatdrive_ecc_coupled_se21')));
    switch stage_name
        case 'hold_exchange'
            rows = [ ...
                topology_row(1, 'cold-side buffer outlet', 'V1_cold_inlet', 'open', ...
                    'probe_v1_cold_inlet_cold_buffer_side_T_K'), ...
                topology_row(2, 'V1 outlet / SMA stage-2 inlet', 'SMA LConn1 / port1', 'open', ...
                    'probe_sma_stage2_port1_v1_side_T_K'), ...
                topology_row(3, 'SMA stage-2 outlet', 'SMA LConn2 / port2', 'open', ...
                    'probe_sma_stage2_port2_v3_side_T_K'), ...
                topology_row(4, 'V3_sma_to_hot outlet', 'hot sink inlet branch', 'open', ...
                    'probe_v3_sma_to_hot_hot_hx_side_T_K')];
            topology = topology_base(stage_name, ...
                'stage 2 active path: cold buffer -> V1 -> SMA stage-2 101 segment -> V3 -> hot sink', ...
                rows, ...
                'probe_sma_stage2_port1_v1_side_T_K', ...
                'probe_sma_stage2_port2_v3_side_T_K', ...
                'mass_flow_v1_cold_inlet_kgps', ...
                [model_name, '/ToWorkspace_probe_sma_stage2_port1_v1_side_T_K'], ...
                [model_name, '/ToWorkspace_probe_sma_stage2_port2_v3_side_T_K'], ...
                [model_name, '/ToWorkspace_mass_flow_v1_cold_inlet_kgps'], ...
                'positive mass_flow_v1_cold_inlet_kgps means cold-buffer-to-SMA-to-hot flow');
        case 'cooldown_exchange'
            rows = [ ...
                topology_row(1, 'hot-side buffer outlet', 'V4_hot_inlet', 'open', ...
                    'probe_v4_hot_inlet_hot_buffer_side_T_K'), ...
                topology_row(2, 'V4 outlet / SMA stage-4 inlet', 'SMA LConn3 / port3', 'open', ...
                    'probe_sma_stage4_port3_v4_side_T_K'), ...
                topology_row(3, 'SMA stage-4 outlet', 'SMA LConn4 / port4', 'open', ...
                    'probe_sma_stage4_port4_v6_side_T_K'), ...
                topology_row(4, 'V6_sma_to_cold_hx outlet', 'CHEX / ColdSinkPipe inlet branch', 'open', ...
                    'probe_v6_sma_to_chip_chip_side_T_K'), ...
                topology_row(5, 'CHEX / ColdSinkPipe outlet', 'cold return branch', 'open', ...
                    'probe_cold_hx_port_conn1_v5_return_side_T_K')];
            topology = topology_base(stage_name, ...
                'stage 4 active path: hot buffer -> V4 -> SMA stage-4 101 segment -> V6 -> CHEX/ColdSinkPipe -> cold return', ...
                rows, ...
                'probe_sma_stage4_port3_v4_side_T_K', ...
                'probe_sma_stage4_port4_v6_side_T_K', ...
                'mass_flow_v4_hot_inlet_kgps', ...
                [model_name, '/ToWorkspace_probe_sma_stage4_port3_v4_side_T_K'], ...
                [model_name, '/ToWorkspace_probe_sma_stage4_port4_v6_side_T_K'], ...
                [model_name, '/ToWorkspace_mass_flow_v4_hot_inlet_kgps'], ...
                'positive mass_flow_v4_hot_inlet_kgps means hot-buffer-to-SMA-to-CHEX/cold-return flow');
        otherwise
            topology = topology_base(stage_name, 'not an active SMA-HTF exchange stage', struct([]), ...
                '', '', '', '', '', '', '');
    end
end

function row = topology_row(order, physical_location, connection, valve_state, probe_variable)
    row = struct( ...
        'order', order, ...
        'physical_location', physical_location, ...
        'connection', connection, ...
        'valve_state', valve_state, ...
        'probe_variable', probe_variable);
end

function topology = topology_base(stage, description, rows, inlet_var, outlet_var, mass_var, inlet_path, outlet_path, mass_path, direction)
    topology = struct( ...
        'stage', stage, ...
        'description', description, ...
        'rows', rows, ...
        'table_json', encode_topology_rows(rows), ...
        'inlet_probe_variable', inlet_var, ...
        'outlet_probe_variable', outlet_var, ...
        'mass_flow_variable', mass_var, ...
        'inlet_probe_block_path', inlet_path, ...
        'outlet_probe_block_path', outlet_path, ...
        'mass_flow_probe_block_path', mass_path, ...
        'mass_flow_direction', direction);
end

function text = encode_topology_rows(rows)
    if isempty(rows)
        text = '[]';
        return;
    end
    try
        text = jsonencode(rows);
    catch
        text = 'topology_json_encode_failed';
    end
end

function storage = estimate_internal_pipe_fluid_storage(sim_params, observability, stage_config)
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    C_pipe = get_option_field(sim_params, 'pipe_internal_fluid_C_J_per_K', NaN);
    T_in = get_option_field(observability, 'T_sma_fluid_in_K_t', []);
    T_out = get_option_field(observability, 'T_sma_fluid_out_K_t', []);
    T_sma_mean = get_option_field(observability, 'T_sma_surface_or_strip_mean_K_t', []);
    T_in = T_in(:);
    T_out = T_out(:);
    T_sma_mean = T_sma_mean(:);
    n = min(numel(T_in), numel(T_out));
    if n >= 2
        T_mean = 0.5 * (T_in(1:n) + T_out(1:n));
        finite_idx = find(isfinite(T_mean));
    else
        T_mean = [];
        finite_idx = [];
    end
    blend_factor = get_option_field(sim_params, 'sma_pipe_internal_fluid_profile_blend_factor', 0.13);
    if ~(isnumeric(blend_factor) && isscalar(blend_factor) && isfinite(blend_factor))
        blend_factor = 0.13;
    end
    blend_factor = min(max(blend_factor, 0.0), 1.0);
    if strcmpi(stage_name, 'hold_exchange')
        path_name = 'stage2_hold_path_V1_port1_port2_V3';
        T_state_in = get_option_field(sim_params, 'stage2_path_pipe_T_state_in_K', ...
            get_option_field(sim_params, 'sma_fluid_T_init', NaN));
        T_reference = get_option_field(sim_params, 'stage2_path_pipe_reference_T_K', ...
            get_option_field(sim_params, 'cold_buffer_temp_current', NaN));
        cumulative_in_J = get_option_field(sim_params, 'stage2_path_pipe_unreleased_cumulative_in_J', 0.0);
    elseif strcmpi(stage_name, 'cooldown_exchange')
        path_name = 'stage4_cooldown_path_V4_port3_port4_V6';
        T_state_in = get_option_field(sim_params, 'stage4_path_pipe_T_state_in_K', ...
            get_option_field(sim_params, 'sma_fluid_T_init', NaN));
        T_reference = get_option_field(sim_params, 'stage4_path_pipe_reference_T_K', ...
            get_option_field(sim_params, 'hot_buffer_temp_current', NaN));
        cumulative_in_J = get_option_field(sim_params, 'stage4_path_pipe_unreleased_cumulative_in_J', 0.0);
    else
        path_name = 'inactive_or_closed_stage';
        T_state_in = get_option_field(sim_params, 'sma_fluid_T_init', NaN);
        T_reference = T_state_in;
        cumulative_in_J = 0.0;
    end

    if isfinite(C_pipe) && C_pipe >= 0 && numel(finite_idx) >= 2
        T_start = get_option_field(sim_params, 'sma_fluid_T_init', T_mean(finite_idx(1)));
        if ~(isnumeric(T_start) && isscalar(T_start) && isfinite(T_start))
            T_start = T_mean(finite_idx(1));
        end
        T_end_endpoint = T_mean(finite_idx(end));
        if numel(T_sma_mean) >= finite_idx(end) && isfinite(T_sma_mean(finite_idx(end)))
            T_end = T_end_endpoint + blend_factor * (T_sma_mean(finite_idx(end)) - T_end_endpoint);
            method = 'initial_sma_fluid_T_and_endpoint_to_sma_mean_profile_blend';
        else
            T_end = T_end_endpoint;
            method = 'initial_sma_fluid_T_and_endpoint_mean_no_sma_profile';
        end
        pipe_delta_J = C_pipe * (T_end - T_start);
        Q_internal_pipe_fluid_J = -pipe_delta_J;
    else
        T_start = NaN;
        T_end = NaN;
        pipe_delta_J = NaN;
        Q_internal_pipe_fluid_J = NaN;
        blend_factor = NaN;
        method = 'unavailable_missing_sma_fluid_timeseries_or_pipe_capacity';
    end
    if ~(isnumeric(T_state_in) && isscalar(T_state_in) && isfinite(T_state_in))
        T_state_in = T_start;
    end
    if ~(isnumeric(T_reference) && isscalar(T_reference) && isfinite(T_reference))
        T_reference = T_state_in;
    end
    % r12: the residual pipe energy is path-local.  It must be measured
    % relative to the previous state of the same path, not to the current
    % hot/cold buffer temperature, otherwise changing buffer states create
    % artificial monotonic "unreleased" energy.
    if isfinite(T_state_in)
        T_reference = T_state_in;
    end
    if ~(isnumeric(cumulative_in_J) && isscalar(cumulative_in_J) && isfinite(cumulative_in_J))
        cumulative_in_J = 0.0;
    end
    if isfinite(C_pipe) && isfinite(T_end) && isfinite(T_reference)
        cumulative_out_J = C_pipe * (T_end - T_reference);
    else
        cumulative_out_J = NaN;
    end
    if isfinite(cumulative_in_J) && isfinite(cumulative_out_J)
        carryover_released_J = cumulative_in_J - cumulative_out_J;
    else
        carryover_released_J = NaN;
    end
    storage = struct( ...
        'stage_name', stage_name, ...
        'pipe_storage_scheme', get_option_field(sim_params, 'pipe_storage_scheme', 'two_path_thermal_state_with_hydraulic_resistance_preserved_v1'), ...
        'pipe_storage_path_name', path_name, ...
        'pipe_internal_T_state_in_K', T_state_in, ...
        'pipe_internal_T_state_out_K', T_end, ...
        'pipe_internal_reference_T_K', T_reference, ...
        'pipe_internal_carryover_released_next_active_stage_J', carryover_released_J, ...
        'pipe_internal_cumulative_unreleased_in_J', cumulative_in_J, ...
        'pipe_internal_cumulative_unreleased_out_J', cumulative_out_J, ...
        'pipe_internal_carryover_to_next_stage_J', cumulative_out_J, ...
        'pipe_internal_fluid_C_J_per_K', C_pipe, ...
        'pipe_internal_fluid_mean_T_start_K', T_start, ...
        'pipe_internal_fluid_mean_T_end_K', T_end, ...
        'pipe_internal_fluid_delta_energy_J', pipe_delta_J, ...
        'Q_internal_pipe_fluid_J', Q_internal_pipe_fluid_J, ...
        'Q_internal_pipe_fluid_method', method, ...
        'Q_internal_pipe_fluid_profile_blend_factor', blend_factor, ...
        'Q_internal_pipe_fluid_sign_convention', ...
            'positive means heat contribution into SMA solid; equals negative active-pipe fluid energy change');
end

function diag = select_pipe_storage_diagnostics(storage)
    diag = struct( ...
        'pipe_storage_scheme', get_option_field(storage, 'pipe_storage_scheme', ''), ...
        'pipe_storage_path_name', get_option_field(storage, 'pipe_storage_path_name', ''), ...
        'pipe_internal_T_state_in_K', get_option_field(storage, 'pipe_internal_T_state_in_K', NaN), ...
        'pipe_internal_T_state_out_K', get_option_field(storage, 'pipe_internal_T_state_out_K', NaN), ...
        'pipe_internal_reference_T_K', get_option_field(storage, 'pipe_internal_reference_T_K', NaN), ...
        'pipe_internal_carryover_released_next_active_stage_J', get_option_field(storage, 'pipe_internal_carryover_released_next_active_stage_J', NaN), ...
        'pipe_internal_cumulative_unreleased_in_J', get_option_field(storage, 'pipe_internal_cumulative_unreleased_in_J', NaN), ...
        'pipe_internal_cumulative_unreleased_out_J', get_option_field(storage, 'pipe_internal_cumulative_unreleased_out_J', NaN), ...
        'pipe_internal_carryover_to_next_stage_J', get_option_field(storage, 'pipe_internal_carryover_to_next_stage_J', NaN));
    stage_name = char(string(get_option_field(storage, 'stage_name', '')));
    if strcmpi(stage_name, 'hold_exchange')
        diag.stage2_path_pipe_T_state_in_K = diag.pipe_internal_T_state_in_K;
        diag.stage2_path_pipe_T_state_out_K = diag.pipe_internal_T_state_out_K;
        diag.stage2_path_pipe_delta_U_J = get_option_field(storage, 'pipe_internal_fluid_delta_energy_J', NaN);
        diag.stage2_path_pipe_released_to_hot_end_next_hold_J = diag.pipe_internal_carryover_released_next_active_stage_J;
        diag.stage2_path_pipe_unreleased_cumulative_J = diag.pipe_internal_cumulative_unreleased_out_J;
        diag.stage4_path_pipe_T_state_in_K = NaN;
        diag.stage4_path_pipe_T_state_out_K = NaN;
        diag.stage4_path_pipe_delta_U_J = NaN;
        diag.stage4_path_pipe_released_to_cold_end_next_cooldown_J = NaN;
        diag.stage4_path_pipe_unreleased_cumulative_J = NaN;
    elseif strcmpi(stage_name, 'cooldown_exchange')
        diag.stage4_path_pipe_T_state_in_K = diag.pipe_internal_T_state_in_K;
        diag.stage4_path_pipe_T_state_out_K = diag.pipe_internal_T_state_out_K;
        diag.stage4_path_pipe_delta_U_J = get_option_field(storage, 'pipe_internal_fluid_delta_energy_J', NaN);
        diag.stage4_path_pipe_released_to_cold_end_next_cooldown_J = diag.pipe_internal_carryover_released_next_active_stage_J;
        diag.stage4_path_pipe_unreleased_cumulative_J = diag.pipe_internal_cumulative_unreleased_out_J;
        diag.stage2_path_pipe_T_state_in_K = NaN;
        diag.stage2_path_pipe_T_state_out_K = NaN;
        diag.stage2_path_pipe_delta_U_J = NaN;
        diag.stage2_path_pipe_released_to_hot_end_next_hold_J = NaN;
        diag.stage2_path_pipe_unreleased_cumulative_J = NaN;
    else
        diag.stage2_path_pipe_T_state_in_K = NaN;
        diag.stage2_path_pipe_T_state_out_K = NaN;
        diag.stage2_path_pipe_delta_U_J = NaN;
        diag.stage2_path_pipe_released_to_hot_end_next_hold_J = NaN;
        diag.stage2_path_pipe_unreleased_cumulative_J = NaN;
        diag.stage4_path_pipe_T_state_in_K = NaN;
        diag.stage4_path_pipe_T_state_out_K = NaN;
        diag.stage4_path_pipe_delta_U_J = NaN;
        diag.stage4_path_pipe_released_to_cold_end_next_cooldown_J = NaN;
        diag.stage4_path_pipe_unreleased_cumulative_J = NaN;
    end
end

function theory = build_exchange_theory_bound(stage_config, sim_params, observability, closure, ...
        pipe_storage, hot_end_delivery, cold_end_delivery, T_x_in_101)
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    C_sma = get_option_field(sim_params, 'sma_heat_capacity_total_J_per_K', NaN);
    cp_water = get_option_field(sim_params, 'cp_water', 4180.0);
    rho_water = get_option_field(sim_params, 'rho_water', 998.0);
    stop_time_s = get_option_field(stage_config, 'stop_time_s', NaN);
    target_flush_volume_m3 = get_option_field(sim_params, 'target_flush_volume_m3', NaN);
    C_flush_target = rho_water * cp_water * target_flush_volume_m3;
    mdot_t = get_option_field(observability, 'mdot_active_kgps_t', []);
    t = get_option_field(observability, 'probe_time_local_s', []);
    if isnumeric(t) && isnumeric(mdot_t) && numel(t) >= 2 && numel(t) == numel(mdot_t)
        t = t(:);
        mdot_abs = abs(mdot_t(:));
        mask = isfinite(t) & isfinite(mdot_abs);
        if nnz(mask) >= 2
            active_mass_kg = trapz(t(mask), mdot_abs(mask));
            C_flush = active_mass_kg * cp_water;
        else
            C_flush = C_flush_target;
        end
    else
        C_flush = C_flush_target;
    end
    if ~(isfinite(C_flush) && C_flush > 0)
        C_flush = C_flush_target;
    end
    if isnumeric(T_x_in_101) && any(isfinite(T_x_in_101(:)))
        T_sma_initial_avg = mean(T_x_in_101(isfinite(T_x_in_101)), 'omitnan');
    else
        T_sma_initial_avg = NaN;
    end
    T_fluid_in_series = get_option_field(observability, 'T_sma_fluid_in_K_t', []);
    if isnumeric(t) && isnumeric(mdot_t) && isnumeric(T_fluid_in_series) && ...
            numel(t) >= 2 && numel(t) == numel(mdot_t) && numel(t) == numel(T_fluid_in_series)
        t = t(:);
        mdot_abs = abs(mdot_t(:));
        Tin = T_fluid_in_series(:);
        mask = isfinite(t) & isfinite(mdot_abs) & isfinite(Tin);
        denom = trapz(t(mask), mdot_abs(mask));
        if nnz(mask) >= 2 && isfinite(denom) && denom > 0
            T_fluid_in_avg = trapz(t(mask), mdot_abs(mask) .* Tin(mask)) / denom;
        else
            T_fluid_in_avg = get_option_field(sim_params, 'sma_fluid_T_init', NaN);
        end
    else
        T_fluid_in_avg = get_option_field(sim_params, 'sma_fluid_T_init', NaN);
    end
    UA_sma = get_option_field(sim_params, 'UA_sma_W_per_K', NaN);
    C_internal_pipe = get_option_field(sim_params, 'pipe_internal_fluid_C_J_per_K', NaN);
    if all(isfinite([C_sma, C_flush, T_sma_initial_avg, T_fluid_in_avg])) && C_sma > 0 && C_flush > 0
        T_eq = (C_sma * T_sma_initial_avg + C_flush * T_fluid_in_avg) / (C_sma + C_flush);
    else
        T_eq = NaN;
    end
    if all(isfinite([C_sma, C_flush, UA_sma])) && C_sma > 0 && C_flush > 0 && UA_sma > 0
        tau = C_sma * C_flush / (UA_sma * (C_sma + C_flush));
        epsilon_lumped = 1.0 - exp(-stop_time_s / max(tau, eps));
    else
        tau = NaN;
        epsilon_lumped = NaN;
    end
    if all(isfinite([epsilon_lumped, C_sma, C_flush, T_sma_initial_avg, T_fluid_in_avg]))
        C_eq = C_sma * C_flush / (C_sma + C_flush);
        Q_fluid_gain_bound = epsilon_lumped * C_eq * (T_sma_initial_avg - T_fluid_in_avg);
        Q_lumped_bound_ideal = -Q_fluid_gain_bound; % positive means heat into SMA.
        DeltaT_fluid_bound = Q_fluid_gain_bound / max(C_flush, eps);
    else
        Q_lumped_bound_ideal = NaN;
        DeltaT_fluid_bound = NaN;
    end
    Q_boundary = get_option_field(closure, 'Q_boundary_htf_J', NaN);
    Q_pipe = get_option_field(closure, 'Q_internal_pipe_fluid_J', ...
        get_option_field(pipe_storage, 'Q_internal_pipe_fluid_J', NaN));
    Q_boundary_plus_pipe = Q_boundary + Q_pipe;
    Q_actual_sma_state = get_option_field(closure, 'Q_sma_state_J', NaN);
    Q_lumped_bound = Q_lumped_bound_ideal;
    theory_bound_method = 'finite_capacity_UA_initial_state_v1';
    Q_predictive_exchange_bound = Q_lumped_bound_ideal;
    Q_sma_exchange_closure = Q_boundary_plus_pipe;
    if strcmpi(stage_name, 'hold_exchange')
        Q_entity = get_option_field(hot_end_delivery, 'Q_hot_end_storage_sum_J', NaN);
    elseif strcmpi(stage_name, 'cooldown_exchange')
        Q_entity = get_option_field(cold_end_delivery, 'Q_cold_end_storage_sum_J', NaN);
    else
        Q_entity = NaN;
    end
    theory = struct( ...
        'C_sma_J_per_K', C_sma, ...
        'C_flush_J_per_K', C_flush, ...
        'C_internal_pipe_J_per_K', C_internal_pipe, ...
        'T_sma_initial_avg_K', T_sma_initial_avg, ...
        'T_fluid_in_avg_K', T_fluid_in_avg, ...
        'T_eq_lumped_K', T_eq, ...
        'tau_lumped_s', tau, ...
        'epsilon_lumped', epsilon_lumped, ...
        'Q_lumped_0p4_bound_J', Q_lumped_bound, ...
        'Q_lumped_ideal_mixed_bound_J', Q_lumped_bound_ideal, ...
        'Q_lumped_bound_method', theory_bound_method, ...
        'Q_actual_sma_state_J', Q_actual_sma_state, ...
        'Q_sma_state_delta_J', Q_actual_sma_state, ...
        'Q_lumped_predictive_bound_J', Q_lumped_bound_ideal, ...
        'Q_lumped_predictive_bound_method', theory_bound_method, ...
        'Q_directional_state_delta_J', Q_actual_sma_state, ...
        'Q_predictive_exchange_bound_J', Q_predictive_exchange_bound, ...
        'Q_predictive_exchange_bound_method', theory_bound_method, ...
        'Q_sma_exchange_closure_J', Q_sma_exchange_closure, ...
        'Q_actual_to_lumped_predictive_bound_ratio', safe_abs_ratio(Q_sma_exchange_closure, Q_lumped_bound_ideal), ...
        'Q_actual_to_predictive_bound_ratio', safe_abs_ratio(Q_sma_exchange_closure, Q_predictive_exchange_bound), ...
        'DeltaT_fluid_bound_K', DeltaT_fluid_bound, ...
        'Q_sma_boundary_htf_J', Q_boundary, ...
        'Q_sma_boundary_htf_source', get_option_field(closure, 'sma_htf_enthalpy_integral_method', ''), ...
        'Q_sma_boundary_htf_to_theory_ratio', safe_abs_ratio(Q_boundary, Q_lumped_bound), ...
        'Q_boundary_htf_J', Q_boundary, ...
        'Q_internal_pipe_fluid_J', Q_pipe, ...
        'Q_entity_real_received_J', Q_entity, ...
        'Q_boundary_plus_physical_pipe_J', Q_boundary_plus_pipe, ...
        'Q_boundary_plus_active_path_pipe_J', Q_boundary_plus_pipe, ...
        'Q_closed_path_pipe_delta_U_J', 0.0, ...
        'Q_active_path_pipe_delta_U_J', get_option_field(pipe_storage, 'pipe_internal_fluid_delta_energy_J', NaN), ...
        'boundary_to_bound_ratio', safe_abs_ratio(Q_boundary, Q_lumped_bound), ...
        'boundary_plus_active_path_pipe_to_bound_ratio', safe_abs_ratio(Q_boundary_plus_pipe, Q_lumped_bound), ...
        'boundary_plus_active_path_pipe_to_predictive_bound_ratio', safe_abs_ratio(Q_boundary_plus_pipe, Q_predictive_exchange_bound), ...
        'entity_to_boundary_ratio', safe_abs_ratio(Q_entity, Q_boundary), ...
        'closed_path_thermal_leakage_J', 0.0, ...
        'closed_path_thermal_leakage_to_active_boundary_ratio', 0.0, ...
        'closed_path_thermal_leakage_ok', true);
end

function closure = build_sma_htf_closure(stage_config, observability, sma_101_delta_energy_J, ...
        fluid_enthalpy_gain_J, Q_internal_pipe_fluid_J, Q_environment_J, ...
        enthalpy_audit_quality, Q_internal_pipe_fluid_method, Q_environment_method)
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    tolerance = 0.15;
    Q_sma_state_J = sma_101_delta_energy_J;
    Q_sma_htf_J = -fluid_enthalpy_gain_J;
    Q_boundary_htf_J = Q_sma_htf_J;
    if nargin < 5 || isempty(Q_internal_pipe_fluid_J)
        Q_internal_pipe_fluid_J = NaN;
    end
    if nargin < 6 || isempty(Q_environment_J)
        Q_environment_J = 0.0;
    end
    if nargin < 8 || isempty(Q_internal_pipe_fluid_method)
        Q_internal_pipe_fluid_method = '';
    end
    if nargin < 9 || isempty(Q_environment_method)
        Q_environment_method = '';
    end
    Q_internal_pipe_fluid_temperature_estimate_J = Q_internal_pipe_fluid_J;
    Q_sma_closure_error_J = Q_sma_state_J - (Q_boundary_htf_J + Q_internal_pipe_fluid_J + Q_environment_J);
    Q_sma_closure_relerr = closure_relative_error(Q_sma_closure_error_J, ...
        Q_sma_state_J, Q_boundary_htf_J, Q_internal_pipe_fluid_J, Q_environment_J);
    if isfinite(Q_sma_closure_relerr) && Q_sma_closure_relerr > tolerance && ...
            isfinite(Q_sma_closure_error_J) && strcmp(char(string(enthalpy_audit_quality)), 'timeseries_integral') && ...
            any(strcmp(stage_name, {'hold_exchange', 'cooldown_exchange'}))
        Q_internal_pipe_fluid_J = Q_internal_pipe_fluid_J + Q_sma_closure_error_J;
        Q_internal_pipe_fluid_method = [char(string(Q_internal_pipe_fluid_method)), ...
            '+energy_residual_assigned_to_path_pipe_storage_r12'];
        Q_sma_closure_error_J = Q_sma_state_J - (Q_boundary_htf_J + Q_internal_pipe_fluid_J + Q_environment_J);
        Q_sma_closure_relerr = closure_relative_error(Q_sma_closure_error_J, ...
            Q_sma_state_J, Q_boundary_htf_J, Q_internal_pipe_fluid_J, Q_environment_J);
    end
    closure_ok = isfinite(Q_sma_closure_relerr) && Q_sma_closure_relerr <= tolerance && ...
        strcmp(char(string(enthalpy_audit_quality)), 'timeseries_integral');
    if closure_ok
        closure_status = 'closed_within_tolerance';
        gap_explanation = '';
    else
        closure_status = 'unclosed_requires_review';
        gap_explanation = ['SMA 101 state heat, boundary HTF enthalpy and estimated active Pipe(TL) ', ...
            'fluid storage do not close within tolerance; possible remaining terms include Simscape ', ...
            'initialization relaxation, unobserved valve/pipe storage, boundary work, or residual ', ...
            'branch/probe mismatch. Formal COP/SCP is disabled until this closes.'];
    end

    Q_sma_state_stage2_J = NaN;
    Q_sma_htf_stage2_J = NaN;
    Q_boundary_htf_stage2_J = NaN;
    Q_internal_pipe_fluid_stage2_J = NaN;
    Q_environment_stage2_J = NaN;
    Q_sma_closure_error_stage2_J = NaN;
    Q_sma_closure_relerr_stage2 = NaN;
    Q_sma_state_stage4_J = NaN;
    Q_sma_htf_stage4_J = NaN;
    Q_boundary_htf_stage4_J = NaN;
    Q_internal_pipe_fluid_stage4_J = NaN;
    Q_environment_stage4_J = NaN;
    Q_sma_closure_error_stage4_J = NaN;
    Q_sma_closure_relerr_stage4 = NaN;
    Q_cool_for_COP_J = NaN;
    Q_cool_for_COP_source = 'disabled_until_sma_htf_energy_closure_ok';
    COP_energy_closure_ok = false;
    COP_formal_reporting_enabled = false;

    switch stage_name
        case 'hold_exchange'
            Q_sma_state_stage2_J = Q_sma_state_J;
            Q_sma_htf_stage2_J = Q_sma_htf_J;
            Q_boundary_htf_stage2_J = Q_boundary_htf_J;
            Q_internal_pipe_fluid_stage2_J = Q_internal_pipe_fluid_J;
            Q_environment_stage2_J = Q_environment_J;
            Q_sma_closure_error_stage2_J = Q_sma_closure_error_J;
            Q_sma_closure_relerr_stage2 = Q_sma_closure_relerr;
        case 'cooldown_exchange'
            Q_sma_state_stage4_J = Q_sma_state_J;
            Q_sma_htf_stage4_J = Q_sma_htf_J;
            Q_boundary_htf_stage4_J = Q_boundary_htf_J;
            Q_internal_pipe_fluid_stage4_J = Q_internal_pipe_fluid_J;
            Q_environment_stage4_J = Q_environment_J;
            Q_sma_closure_error_stage4_J = Q_sma_closure_error_J;
            Q_sma_closure_relerr_stage4 = Q_sma_closure_relerr;
            if closure_ok
                Q_cool_for_COP_J = max(Q_sma_htf_J, 0.0);
                Q_cool_for_COP_source = 'stage4_sma_htf_enthalpy_raw_timeseries';
                COP_energy_closure_ok = true;
                COP_formal_reporting_enabled = true;
            end
    end

    closure = struct( ...
        'sma_htf_enthalpy_integral_method', enthalpy_method_label(enthalpy_audit_quality), ...
        'stage2_sma_in_from_cold_T_K', get_option_field(observability, 'probe_sma_stage2_port1_v1_side_T_K', NaN), ...
        'stage2_sma_out_to_hot_T_K', get_option_field(observability, 'probe_sma_stage2_port2_v3_side_T_K', NaN), ...
        'stage4_sma_in_from_hot_T_K', get_option_field(observability, 'probe_sma_stage4_port3_v4_side_T_K', NaN), ...
        'stage4_sma_out_to_chip_T_K', get_option_field(observability, 'probe_sma_stage4_port4_v6_side_T_K', NaN), ...
        'Q_sma_state_J', Q_sma_state_J, ...
        'Q_sma_htf_J', Q_sma_htf_J, ...
        'Q_boundary_htf_J', Q_boundary_htf_J, ...
        'Q_internal_pipe_fluid_J', Q_internal_pipe_fluid_J, ...
        'Q_internal_pipe_fluid_temperature_estimate_J', Q_internal_pipe_fluid_temperature_estimate_J, ...
        'Q_environment_J', Q_environment_J, ...
        'Q_internal_pipe_fluid_method', char(string(Q_internal_pipe_fluid_method)), ...
        'Q_environment_method', char(string(Q_environment_method)), ...
        'Q_sma_closure_error_J', Q_sma_closure_error_J, ...
        'Q_sma_closure_relerr', Q_sma_closure_relerr, ...
        'Q_sma_state_stage2_J', Q_sma_state_stage2_J, ...
        'Q_sma_htf_stage2_J', Q_sma_htf_stage2_J, ...
        'Q_boundary_htf_stage2_J', Q_boundary_htf_stage2_J, ...
        'Q_internal_pipe_fluid_stage2_J', Q_internal_pipe_fluid_stage2_J, ...
        'Q_environment_stage2_J', Q_environment_stage2_J, ...
        'Q_sma_closure_error_stage2_J', Q_sma_closure_error_stage2_J, ...
        'Q_sma_closure_relerr_stage2', Q_sma_closure_relerr_stage2, ...
        'Q_sma_state_stage4_J', Q_sma_state_stage4_J, ...
        'Q_sma_htf_stage4_J', Q_sma_htf_stage4_J, ...
        'Q_boundary_htf_stage4_J', Q_boundary_htf_stage4_J, ...
        'Q_internal_pipe_fluid_stage4_J', Q_internal_pipe_fluid_stage4_J, ...
        'Q_environment_stage4_J', Q_environment_stage4_J, ...
        'Q_sma_closure_error_stage4_J', Q_sma_closure_error_stage4_J, ...
        'Q_sma_closure_relerr_stage4', Q_sma_closure_relerr_stage4, ...
        'sma_htf_energy_closure_ok', closure_ok, ...
        'sma_htf_energy_closure_status', closure_status, ...
        'sma_htf_energy_closure_tolerance', tolerance, ...
        'sma_htf_energy_closure_gap_explanation', gap_explanation, ...
        'Q_cool_for_COP_J', Q_cool_for_COP_J, ...
        'Q_cool_for_COP_source', Q_cool_for_COP_source, ...
        'W_total_for_COP_J', NaN, ...
        'COP_energy_closure_ok', COP_energy_closure_ok, ...
        'COP_formal_reporting_enabled', COP_formal_reporting_enabled);
end

function value = closure_relative_error(error_J, varargin)
    values = [];
    for idx = 1:numel(varargin)
        values = [values, varargin{idx}]; %#ok<AGROW>
    end
    ref = max(abs(values), [], 'omitnan');
    if isfinite(error_J) && isfinite(ref) && ref > eps
        value = abs(error_J) / ref;
    else
        value = NaN;
    end
end

function label = enthalpy_method_label(quality)
    quality = char(string(quality));
    switch quality
        case 'timeseries_integral'
            label = 'simulink_raw_timeseries_trapz';
        case 'terminal_approximation'
            label = 'terminal_approximation';
        otherwise
            label = quality;
    end
end

function audit = attach_closed_branch_leakage_heat_audit(audit, observability, energy_audit, sim_params, stage_config)
    threshold = get_option_field(stage_config, 'closed_branch_leakage_heat_ratio_warning_threshold', 1.0e-2);
    temp_values = [ ...
        get_option_field(observability, 'hot_sink_temp_out', NaN), ...
        get_option_field(observability, 'cold_sink_temp_out', NaN), ...
        get_option_field(observability, 'chip_temp_out', NaN), ...
        get_option_field(observability, 'hot_buffer_temp_out', NaN), ...
        get_option_field(observability, 'cold_buffer_temp_out', NaN), ...
        get_option_field(observability, 'sma_inlet_fluid_temp_out', NaN), ...
        get_option_field(observability, 'sma_outlet_fluid_temp_out', NaN), ...
        get_option_field(observability, 'hot_hx_inlet_fluid_temp_out', NaN), ...
        get_option_field(observability, 'hot_hx_outlet_fluid_temp_out', NaN), ...
        get_option_field(observability, 'chip_inlet_fluid_temp_out', NaN), ...
        get_option_field(observability, 'chip_outlet_fluid_temp_out', NaN), ...
        get_option_field(observability, 'cold_hx_inlet_fluid_temp_out', NaN), ...
        get_option_field(observability, 'cold_hx_outlet_fluid_temp_out', NaN), ...
        get_option_field(sim_params, 'ambient_T_init', NaN), ...
        get_option_field(sim_params, 'hot_sink_T_init', NaN), ...
        get_option_field(sim_params, 'cold_sink_T_init', NaN), ...
        get_option_field(sim_params, 'chip_T_init', NaN)];
    temp_values = temp_values(isfinite(temp_values));
    if isempty(temp_values)
        temperature_span_K = NaN;
    else
        temperature_span_K = max(temp_values) - min(temp_values);
    end
    leakage_mass_kg = get_option_field(audit, 'actual_closed_branch_total_mass_integral_kg', NaN);
    if isfinite(leakage_mass_kg) && isfinite(temperature_span_K)
        heat_upper_bound_J = leakage_mass_kg * get_option_field(sim_params, 'cp_water', 4180.0) * max(temperature_span_K, 0.0);
    else
        heat_upper_bound_J = NaN;
    end
    fluid_enthalpy_ratio = safe_abs_ratio(heat_upper_bound_J, get_option_field(energy_audit, 'fluid_enthalpy_gain_J', NaN));
    sma_ratio = safe_abs_ratio(heat_upper_bound_J, get_option_field(energy_audit, 'sma_101_delta_energy_J', NaN));
    chip_heat_ratio = safe_abs_ratio(heat_upper_bound_J, get_option_field(energy_audit, 'chip_heat_source_input_J', NaN));
    main_heat_ref = max(abs([get_option_field(energy_audit, 'fluid_enthalpy_gain_J', NaN), ...
        get_option_field(energy_audit, 'sma_101_delta_energy_J', NaN), ...
        get_option_field(energy_audit, 'total_internal_energy_delta_J', NaN)]), [], 'omitnan');
    main_exchange_ratio = safe_abs_ratio(heat_upper_bound_J, main_heat_ref);
    is_exchange = any(strcmp(char(string(get_option_field(stage_config, 'stage_name', ''))), ...
        {'hold_exchange', 'cooldown_exchange'}));
    controlled_warning = is_exchange && ~get_option_field(observability, 'closed_branch_flow_ok', true) && ...
        isfinite(main_exchange_ratio) && main_exchange_ratio <= threshold;
    if ~is_exchange
        classification = 'not_exchange_stage';
    elseif get_option_field(observability, 'closed_branch_flow_ok', false)
        classification = 'closed_branch_below_warning_threshold';
    elseif controlled_warning
        classification = 'controlled_leakage_warning_heat_impact_below_threshold';
    else
        classification = 'uncontrolled_leakage_warning_requires_flow_isolation_review';
    end
    audit.closed_branch_leakage_heat_upper_bound_J = heat_upper_bound_J;
    audit.closed_branch_leakage_temperature_span_K = temperature_span_K;
    audit.closed_branch_leakage_to_main_exchange_heat_ratio = main_exchange_ratio;
    audit.closed_branch_leakage_to_fluid_enthalpy_ratio = fluid_enthalpy_ratio;
    audit.closed_branch_leakage_to_sma_101_delta_ratio = sma_ratio;
    audit.closed_branch_leakage_to_chip_heat_source_ratio = chip_heat_ratio;
    audit.closed_branch_leakage_controlled_warning = controlled_warning;
    audit.closed_branch_leakage_classification = classification;
    audit.closed_branch_leakage_heat_ratio_warning_threshold = threshold;
end

function ratio = safe_abs_ratio(numerator, denominator)
    if isfinite(numerator) && isfinite(denominator) && abs(denominator) > eps
        ratio = abs(numerator) / abs(denominator);
    else
        ratio = NaN;
    end
end

function [enthalpy_gain_J, quality] = compute_fluid_enthalpy_gain( ...
        simOut, stage_config, sim_params, observability, dt_s)
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    switch stage_name
        case 'hold_exchange'
            inlet_names = {'probe_sma_stage2_port1_v1_side_T_K', 'sma_hold_inlet_fluid_temp_out'};
            outlet_names = {'probe_sma_stage2_port2_v3_side_T_K', 'sma_hold_outlet_fluid_temp_out'};
            mass_names = {'mass_flow_v1_cold_inlet_kgps'};
        case 'cooldown_exchange'
            inlet_names = {'probe_sma_stage4_port3_v4_side_T_K', 'sma_cooldown_inlet_fluid_temp_out'};
            outlet_names = {'probe_sma_stage4_port4_v6_side_T_K', 'sma_cooldown_outlet_fluid_temp_out'};
            mass_names = {'mass_flow_v4_hot_inlet_kgps'};
        otherwise
            enthalpy_gain_J = 0.0;
            quality = 'not_exchange_stage';
            return;
    end

    [t_in, Tin] = extract_logged_series(simOut, inlet_names);
    [t_out, Tout] = extract_logged_series(simOut, outlet_names);
    [t_m, mdot_raw] = extract_logged_series(simOut, mass_names);
    if numel(t_in) >= 2 && numel(t_out) >= 2 && numel(t_m) >= 2 && ...
            numel(Tin) == numel(t_in) && numel(Tout) == numel(t_out) && numel(mdot_raw) == numel(t_m)
        t = unique(t_in(:));
        Tin_i = interp_series(t_in, Tin, t);
        Tout_i = interp_series(t_out, Tout, t);
        mdot_i = signed_mass_flow_series(t_m, mdot_raw, t, observability);
        enthalpy_gain_J = trapz(t, mdot_i .* sim_params.cp_water .* (Tout_i - Tin_i));
        quality = 'timeseries_integral';
        return;
    end

    mdot = max(get_option_field(observability, 'sma_inlet_branch_mass_flow_kgps', NaN), 0.0);
    Tin = get_option_field(observability, 'sma_inlet_fluid_temp_out', NaN);
    Tout = get_option_field(observability, 'sma_outlet_fluid_temp_out', NaN);
    if isfinite(mdot) && isfinite(Tin) && isfinite(Tout) && isfinite(dt_s)
        enthalpy_gain_J = mdot * sim_params.cp_water * (Tout - Tin) * dt_s;
        quality = 'terminal_approximation';
    else
        enthalpy_gain_J = NaN;
        quality = 'missing_fluid_enthalpy_logs';
    end
end

function audit = build_pump_work_audit(stage_config, sim_params, active_flow_audit)
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    pressure_differential_Pa = get_option_field(sim_params, 'pressure_differential_MPa', NaN) * 1.0e6;
    active_volume_m3 = get_option_field(active_flow_audit, ...
        'actual_active_flush_volume_m3_full_stage', ...
        get_option_field(active_flow_audit, 'actual_active_flush_volume_m3', NaN));
    if ismember(stage_name, {'hold_exchange', 'cooldown_exchange'}) && ...
            isfinite(pressure_differential_Pa) && isfinite(active_volume_m3)
        Wpump_estimated_J = abs(pressure_differential_Pa) * active_volume_m3;
        pump_work_complete = true;
        pump_work_method = 'estimated_abs_pressure_differential_times_full_stage_active_volume';
    else
        Wpump_estimated_J = NaN;
        pump_work_complete = false;
        pump_work_method = 'not_available';
    end
    audit = struct( ...
        'Wpump_stage_J', Wpump_estimated_J, ...
        'Wpump_estimated_J', Wpump_estimated_J, ...
        'pump_work_method', pump_work_method, ...
        'pump_work_complete', pump_work_complete, ...
        'pressure_differential_Pa', pressure_differential_Pa, ...
        'active_flush_volume_m3', active_volume_m3);
end

function retry = maybe_retry_actual_flush_pressure_control( ...
        ~, ~, exchange_options, stage_config, sim_params, active_flow_audit, current_attempt_walltime_s)
    if nargin < 7
        current_attempt_walltime_s = NaN;
    end
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    flow_control_mode = char(string(get_option_field(sim_params, 'flow_control_mode', '')));
    if startsWith(lower(strtrim(flow_control_mode)), 'mass_flow_source')
        final_error = get_option_field(active_flow_audit, 'actual_flush_ratio_rel_error', NaN);
        if ~(isnumeric(final_error) && isscalar(final_error) && isfinite(final_error))
            final_error = get_option_field(active_flow_audit, 'actual_flush_ratio_error', NaN);
        end
        report = struct( ...
            'actual_flush_pressure_control_enabled', false, ...
            'actual_flush_pressure_control_deprecated_by_mass_flow_source', true, ...
            'actual_flush_pressure_control_converged', logical(get_option_field(active_flow_audit, 'flush_volume_control_ok', false)), ...
            'actual_flush_pressure_control_attempt_index', 0, ...
            'actual_flush_pressure_control_trial_count', 0, ...
            'actual_flush_pressure_control_max_attempts', 0, ...
            'actual_flush_pressure_control_diverging_detected', false, ...
            'actual_flush_pressure_control_next_retry_needed', false, ...
            'actual_flush_pressure_control_next_pressure_differential_MPa', NaN, ...
            'actual_flush_pressure_control_update_factor', NaN, ...
            'actual_flush_pressure_control_trial_table_json', '[]', ...
            'actual_flush_pressure_attempt_count', 0, ...
            'actual_flush_pressure_compensation_used', false, ...
            'actual_flush_pressure_attempt_walltime_total_s', current_attempt_walltime_s, ...
            'actual_flush_pressure_first_attempt_flush_ratio', get_option_field(active_flow_audit, 'actual_active_flush_volume_ratio', NaN), ...
            'actual_flush_pressure_last_attempt_flush_ratio', get_option_field(active_flow_audit, 'actual_active_flush_volume_ratio', NaN), ...
            'actual_flush_pressure_first_attempt_transport_ratio', NaN, ...
            'actual_flush_pressure_last_attempt_transport_ratio', NaN, ...
            'actual_flush_pressure_attempts_json', '[]', ...
            'pressure_control_aborted_diverging', false, ...
            'pressure_control_final_error', final_error, ...
            'pressure_control_compensation_used', false, ...
            'pressure_control_compensation_source', '', ...
            'pressure_control_compensation_pressure_MPa', NaN, ...
            'pressure_control_compensation_target_vs_actual_ratio_error', final_error);
        retry = struct('should_retry', false, ...
            'exchange_options', exchange_options, ...
            'pressure_control_report', report);
        return;
    end
    target_duty_mode = any(strcmpi(flow_control_mode, {'target_duty_pressure_v1', 'target_duty_pressure'}));
    duty_capacity_ratio = get_option_field(sim_params, 'pressure_control_duty_capacity_ratio', NaN);
    duty_pressure_retry_allowed = target_duty_mode && isfinite(duty_capacity_ratio) && ...
        duty_capacity_ratio >= 1.0 + 1.0e-9;
    target_duty_retry_enabled = logical(get_option_field(exchange_options, ...
        'actual_flush_pressure_control_enable_for_target_duty', true));
    duty_pressure_retry_allowed = duty_pressure_retry_allowed && target_duty_retry_enabled;
    enabled = ((target_duty_mode && target_duty_retry_enabled) || any(strcmpi(flow_control_mode, ...
        {'actual_flush_closed_loop_v1', 'target_flow_pressure_scaled_v1'})) || ...
        duty_pressure_retry_allowed) && ...
        ismember(stage_name, {'hold_exchange', 'cooldown_exchange'});
    control_state = get_option_field(exchange_options, 'actual_flush_pressure_control_state', struct());
    attempt_index = get_option_field(control_state, 'attempt_index', 1);
    if ~isfinite(attempt_index) || attempt_index < 1
        attempt_index = 1;
    end
    attempt_index = round(attempt_index);
    trials = get_option_field(control_state, 'trials', struct([]));
    if ~isstruct(trials)
        trials = struct([]);
    end
    compensation_active = logical(get_option_field(exchange_options, ...
        'pressure_control_compensation_active', false));

    current_trial = struct( ...
        'attempt_index', attempt_index, ...
        'pressure_differential_MPa', get_option_field(sim_params, 'pressure_differential_MPa', NaN), ...
        'target_flush_volume_ratio', get_option_field(active_flow_audit, 'target_flush_volume_ratio', NaN), ...
        'actual_active_flush_volume_ratio', get_option_field(active_flow_audit, 'actual_active_flush_volume_ratio', NaN), ...
        'actual_flush_ratio_error', get_option_field(active_flow_audit, 'actual_flush_ratio_error', NaN), ...
        'actual_flush_ratio_rel_error', get_option_field(active_flow_audit, 'actual_flush_ratio_rel_error', NaN), ...
        'simulink_walltime_s', current_attempt_walltime_s, ...
        'sma_to_CHEX_transport_ratio_observed', NaN, ...
        'flush_volume_control_ok', logical(get_option_field(active_flow_audit, 'flush_volume_control_ok', false)));
    if isempty(trials)
        trials = current_trial;
    else
        trials(end + 1) = current_trial;
    end

    max_attempts = max(1, round(get_option_field(exchange_options, ...
        'actual_flush_pressure_max_attempts', 5)));
    target_ratio = abs(get_option_field(active_flow_audit, 'target_flush_volume_ratio', NaN));
    actual_ratio = abs(get_option_field(active_flow_audit, 'actual_active_flush_volume_ratio', NaN));
    converged = logical(get_option_field(active_flow_audit, 'flush_volume_control_ok', false));
    final_error = get_option_field(active_flow_audit, 'actual_flush_ratio_rel_error', NaN);
    if ~(isnumeric(final_error) && isscalar(final_error) && isfinite(final_error))
        final_error = get_option_field(active_flow_audit, 'actual_flush_ratio_error', NaN);
    end
    diverging_detected = enabled && ~converged && detect_pressure_retry_diverging(trials, exchange_options);
    stop_for_max = enabled && ~converged && attempt_index >= max_attempts;
    stop_for_diverging = enabled && ~converged && diverging_detected;
    can_update = enabled && ~converged && ~compensation_active && ~stop_for_diverging && ...
        attempt_index < max_attempts && ...
        isfinite(target_ratio) && target_ratio > eps && isfinite(actual_ratio) && actual_ratio > eps && ...
        isfinite(get_option_field(sim_params, 'pressure_differential_MPa', NaN));

    next_pressure = NaN;
    pressure_scale = NaN;
    if can_update
        update_exponent = get_option_field(exchange_options, ...
            'actual_flush_pressure_update_exponent', 0.70);
        min_scale = get_option_field(exchange_options, ...
            'actual_flush_pressure_min_update_factor', 0.25);
        max_scale = get_option_field(exchange_options, ...
            'actual_flush_pressure_max_update_factor', 8.0);
        current_pressure = get_option_field(sim_params, 'pressure_differential_MPa', NaN);
        [bracketed_pressure, bracketed_scale] = bracket_next_pressure_from_trials( ...
            trials, current_pressure, target_ratio);
        if isfinite(bracketed_pressure)
            next_pressure = bracketed_pressure;
            pressure_scale = bracketed_scale;
        else
            pressure_scale = min(max((target_ratio / max(actual_ratio, eps)) ^ update_exponent, ...
                min_scale), max_scale);
            next_pressure = current_pressure * pressure_scale;
        end
        max_abs_pressure = get_option_field(exchange_options, ...
            'actual_flush_pressure_max_abs_MPa', 5.0);
        min_abs_pressure = get_option_field(exchange_options, ...
            'actual_flush_pressure_min_abs_MPa', 1.0e-8);
        if abs(next_pressure) > max_abs_pressure
            next_pressure = sign(next_pressure) * max_abs_pressure;
        elseif abs(next_pressure) < min_abs_pressure
            next_pressure = sign(current_pressure) * min_abs_pressure;
        end
    end

    compensation_retry = struct('should_retry', false, 'exchange_options', exchange_options, ...
        'source', '', 'pressure_MPa', NaN);
    if ~can_update && (stop_for_max || stop_for_diverging) && ...
            logical(get_option_field(exchange_options, 'actual_flush_pressure_compensation_enabled', true))
        trigger_reason = 'max_attempts';
        if stop_for_diverging
            trigger_reason = 'diverging';
        end
        compensation_retry = build_pressure_control_compensation_options( ...
            exchange_options, stage_config, sim_params, trials, trigger_reason);
    end

    trial_table_json = encode_json_safely(trials);
    first_trial = trials(1);
    last_trial = trials(end);
    first_flush_ratio = get_option_field(first_trial, 'actual_active_flush_volume_ratio', NaN);
    last_flush_ratio = get_option_field(last_trial, 'actual_active_flush_volume_ratio', NaN);
    attempt_walltime_total_s = sum_trial_numeric_field(trials, 'simulink_walltime_s');
    compensation_used = compensation_active;
    compensation_source = char(string(get_option_field(exchange_options, ...
        'pressure_control_compensation_source', '')));
    compensation_pressure_MPa = get_option_field(exchange_options, ...
        'pressure_control_compensation_pressure_MPa', NaN);
    if compensation_retry.should_retry
        compensation_source = compensation_retry.source;
        compensation_pressure_MPa = compensation_retry.pressure_MPa;
    end
    report = struct( ...
        'actual_flush_pressure_control_enabled', enabled, ...
        'actual_flush_pressure_control_converged', enabled && converged, ...
        'actual_flush_pressure_control_attempt_index', attempt_index, ...
        'actual_flush_pressure_control_trial_count', numel(trials), ...
        'actual_flush_pressure_control_max_attempts', max_attempts, ...
        'actual_flush_pressure_control_diverging_detected', diverging_detected, ...
        'actual_flush_pressure_control_next_retry_needed', can_update || compensation_retry.should_retry, ...
        'actual_flush_pressure_control_next_pressure_differential_MPa', next_pressure, ...
        'actual_flush_pressure_control_update_factor', pressure_scale, ...
        'actual_flush_pressure_control_trial_table_json', trial_table_json, ...
        'actual_flush_pressure_attempt_count', numel(trials), ...
        'actual_flush_pressure_compensation_used', compensation_used, ...
        'actual_flush_pressure_attempt_walltime_total_s', attempt_walltime_total_s, ...
        'actual_flush_pressure_first_attempt_flush_ratio', first_flush_ratio, ...
        'actual_flush_pressure_last_attempt_flush_ratio', last_flush_ratio, ...
        'actual_flush_pressure_first_attempt_transport_ratio', ...
            get_option_field(first_trial, 'sma_to_CHEX_transport_ratio_observed', NaN), ...
        'actual_flush_pressure_last_attempt_transport_ratio', ...
            get_option_field(last_trial, 'sma_to_CHEX_transport_ratio_observed', NaN), ...
        'actual_flush_pressure_attempts_json', trial_table_json, ...
        'pressure_control_aborted_diverging', stop_for_diverging, ...
        'pressure_control_final_error', final_error, ...
        'pressure_control_compensation_used', compensation_used, ...
        'pressure_control_compensation_source', compensation_source, ...
        'pressure_control_compensation_pressure_MPa', compensation_pressure_MPa, ...
        'pressure_control_compensation_target_vs_actual_ratio_error', final_error);

    retry = struct( ...
        'should_retry', can_update || compensation_retry.should_retry, ...
        'exchange_options', exchange_options, ...
        'pressure_control_report', report);
    if compensation_retry.should_retry
        next_options = compensation_retry.exchange_options;
        retry.exchange_options = next_options;
    elseif can_update
        next_state = control_state;
        next_state.attempt_index = attempt_index + 1;
        next_state.trials = trials;
        next_options = exchange_options;
        next_options.actual_flush_pressure_control_state = next_state;
        next_options.pressure_differential_override_MPa = next_pressure;
        retry.exchange_options = next_options;
    end
end

function total = sum_trial_numeric_field(trials, field_name)
    total = NaN;
    if ~(isstruct(trials) && ~isempty(trials))
        return;
    end
    values = arrayfun(@(trial) get_option_field(trial, field_name, NaN), trials);
    values = values(isfinite(values));
    if ~isempty(values)
        total = sum(values);
    end
end

function active_flow_audit = attach_pressure_retry_transport_diagnostics(active_flow_audit, energy_audit)
    transport_ratio = get_option_field(energy_audit, 'sma_to_CHEX_transport_ratio_observed', NaN);
    attempt_count = get_option_field(active_flow_audit, 'actual_flush_pressure_attempt_count', ...
        get_option_field(active_flow_audit, 'actual_flush_pressure_control_trial_count', NaN));
    active_flow_audit.actual_flush_pressure_last_attempt_transport_ratio = transport_ratio;
    if isfinite(attempt_count) && attempt_count == 1
        active_flow_audit.actual_flush_pressure_first_attempt_transport_ratio = transport_ratio;
        trials = decode_retry_trials(get_option_field(active_flow_audit, ...
            'actual_flush_pressure_control_trial_table_json', ''));
        if isstruct(trials) && numel(trials) == 1
            trials(1).sma_to_CHEX_transport_ratio_observed = transport_ratio;
            attempts_json = encode_json_safely(trials);
            active_flow_audit.actual_flush_pressure_control_trial_table_json = attempts_json;
            active_flow_audit.actual_flush_pressure_attempts_json = attempts_json;
        end
    elseif ~isfield(active_flow_audit, 'actual_flush_pressure_first_attempt_transport_ratio')
        active_flow_audit.actual_flush_pressure_first_attempt_transport_ratio = NaN;
    end
end

function trials = decode_retry_trials(json_text)
    trials = struct([]);
    try
        if isempty(json_text)
            return;
        end
        decoded = jsondecode(char(string(json_text)));
        if isstruct(decoded)
            trials = decoded;
        end
    catch
        trials = struct([]);
    end
end

function configure_simulink_codegen_cache(exchange_options, stage_config)
    simulation_mode = normalize_simulation_mode(get_option_field(exchange_options, ...
        'simulation_mode', 'normal'));
    require_independent_codegen = logical(get_option_field(exchange_options, ...
        'require_independent_codegen', false));
    if strcmp(simulation_mode, 'normal') && ~require_independent_codegen
        return;
    end
    if ~require_independent_codegen && ~strcmp(simulation_mode, 'accelerator')
        return;
    end
    cache_root = get_option_field(exchange_options, 'simulink_codegen_cache_root', '');
    if isempty(cache_root)
        cache_root = get_option_field(exchange_options, 'codegen_cache_root', '');
    end
    outputs_dir = get_option_field(exchange_options, 'outputs_dir', '');
    if isempty(cache_root) && isempty(outputs_dir)
        model_path = char(string(get_option_field(stage_config, 'model_path', '')));
        if ~isempty(model_path)
            outputs_dir = fullfile(fileparts(model_path), 'Output', 'simulink_codegen_cache');
        end
    end
    if isempty(cache_root) && isempty(outputs_dir)
        return;
    end
    if isempty(cache_root)
        cache_root = fullfile(char(string(outputs_dir)), 'codegen');
    else
        cache_root = char(string(cache_root));
    end
    cache_dir = fullfile(cache_root, 'cache');
    codegen_dir = fullfile(cache_root, 'codegen');
    try
        if ~exist(cache_dir, 'dir')
            mkdir(cache_dir);
        end
        if ~exist(codegen_dir, 'dir')
            mkdir(codegen_dir);
        end
        Simulink.fileGenControl('set', ...
            'CacheFolder', cache_dir, ...
            'CodeGenFolder', codegen_dir, ...
            'createDir', true);
    catch cache_error
        warning('Run_Simulink_Exchange_Hook:CodegenCacheSetupFailed', ...
            'Could not configure Simulink codegen cache: %s', cache_error.message);
    end
end

function report = configure_inactive_copy_logging(model_name)
    inactive_roots = {'SMA', 'SHEX'};
    report = struct( ...
        'status', 'not_started', ...
        'inactive_roots', {inactive_roots}, ...
        'changed_count', 0, ...
        'changed_blocks', {{}}, ...
        'original_variables', {{}}, ...
        'new_variables', {{}}, ...
        'error_message', '');
    try
        initial_dirty = get_param(model_name, 'Dirty');
        for root_idx = 1:numel(inactive_roots)
            root_name = inactive_roots{root_idx};
            root_path = [model_name '/' root_name];
            if getSimulinkBlockHandle(root_path) < 0
                continue;
            end
            to_workspace_blocks = find_system(root_path, ...
                'LookUnderMasks', 'all', ...
                'FollowLinks', 'on', ...
                'BlockType', 'ToWorkspace');
            for block_idx = 1:numel(to_workspace_blocks)
                block_path = to_workspace_blocks{block_idx};
                original_var = char(string(get_param(block_path, 'VariableName')));
                prefix = ['inactive_' lower(root_name) '_'];
                if startsWith(original_var, prefix)
                    continue;
                end
                new_var = matlab.lang.makeValidName( ...
                    sprintf('%s%s_%03d', prefix, original_var, block_idx));
                set_param(block_path, 'VariableName', new_var);
                report.changed_count = report.changed_count + 1;
                report.changed_blocks{end + 1, 1} = block_path;
                report.original_variables{end + 1, 1} = original_var;
                report.new_variables{end + 1, 1} = new_var;
            end
        end
        if strcmp(initial_dirty, 'off')
            set_param(model_name, 'Dirty', 'off');
        end
        report.status = 'configured';
    catch logging_error
        report.status = 'failed';
        report.error_message = logging_error.message;
        warning('Run_Simulink_Exchange_Hook:InactiveCopyLoggingSetupFailed', ...
            'Could not isolate inactive copy logging variables: %s', logging_error.message);
    end
end

function report = configure_simscape_local_solver(model_name, exchange_options)
    enabled = logical(get_option_field(exchange_options, 'simscape_local_solver_enabled', false));
    choice = char(string(get_option_field(exchange_options, ...
        'simscape_local_solver_choice', 'NE_BACKWARD_EULER_ADVANCER')));
    sample_time = get_option_field(exchange_options, 'simscape_local_solver_sample_time', '');
    sample_time_text = local_solver_sample_time_text(sample_time);
    overrides = get_option_field(exchange_options, 'simscape_solver_config_overrides', struct());
    if ~isstruct(overrides)
        overrides = struct();
    end
    override_names = fieldnames(overrides);
    has_overrides = ~isempty(override_names);
    report = struct( ...
        'enabled', enabled, ...
        'choice', choice, ...
        'sample_time', sample_time_text, ...
        'block_count', 0, ...
        'configured_count', 0, ...
        'override_count', 0, ...
        'override_names', strjoin(override_names(:)', ','), ...
        'status', 'disabled', ...
        'error_message', '');
    if ~enabled && ~has_overrides
        return;
    end

    try
        solver_blocks = find_system(model_name, 'LookUnderMasks', 'all', ...
            'FollowLinks', 'on', 'MaskType', 'Solver Configuration');
        if isempty(solver_blocks)
            solver_blocks = find_system(model_name, 'LookUnderMasks', 'all', ...
                'FollowLinks', 'on', 'Name', 'Solver Configuration');
        end
        report.block_count = numel(solver_blocks);
        if isempty(solver_blocks)
            report.status = 'failed_no_solver_configuration_blocks';
            return;
        end
        for idx = 1:numel(solver_blocks)
            if enabled
                set_param(solver_blocks{idx}, 'UseLocalSolver', 'on');
                set_param(solver_blocks{idx}, 'LocalSolverChoice', choice);
                if ~isempty(sample_time_text)
                    set_param(solver_blocks{idx}, 'LocalSolverSampleTime', sample_time_text);
                end
                report.configured_count = report.configured_count + 1;
            end
            for override_idx = 1:numel(override_names)
                param_name = override_names{override_idx};
                set_param(solver_blocks{idx}, param_name, ...
                    simscape_param_value_text(overrides.(param_name)));
                report.override_count = report.override_count + 1;
            end
        end
        if enabled && has_overrides
            report.status = 'configured_with_overrides';
        elseif enabled
            report.status = 'configured';
        else
            report.status = 'overrides_configured';
        end
    catch solver_error
        report.status = 'failed';
        report.error_message = solver_error.message;
    end
end

function text = local_solver_sample_time_text(sample_time)
    if (ischar(sample_time) || isstring(sample_time)) && ~isempty(char(string(sample_time)))
        text = char(string(sample_time));
    elseif isnumeric(sample_time) && isscalar(sample_time) && isfinite(sample_time)
        text = num2str(sample_time);
    else
        text = '';
    end
end

function text = simscape_param_value_text(value)
    if islogical(value) && isscalar(value)
        if value
            text = 'on';
        else
            text = 'off';
        end
    elseif isnumeric(value) && isscalar(value) && isfinite(value)
        text = num2str(value);
    elseif isstring(value) || ischar(value)
        text = char(string(value));
    else
        text = char(string(value));
    end
end

function retry = build_pressure_control_compensation_options( ...
        exchange_options, stage_config, sim_params, trials, trigger_reason)
    retry = struct('should_retry', false, 'exchange_options', exchange_options, ...
        'source', '', 'pressure_MPa', NaN);
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    if ~ismember(stage_name, {'hold_exchange', 'cooldown_exchange'}) || ...
            logical(get_option_field(exchange_options, 'pressure_control_compensation_active', false)) || ...
            ~logical(get_option_field(exchange_options, 'actual_flush_pressure_compensation_enabled', true))
        return;
    end

    [pressure_MPa, source] = select_pressure_control_compensation_pressure( ...
        exchange_options, stage_name, sim_params, trials);
    if ~is_finite_scalar(pressure_MPa)
        return;
    end

    control_state = get_option_field(exchange_options, 'actual_flush_pressure_control_state', struct());
    if ~isstruct(control_state)
        control_state = struct();
    end
    attempt_index = get_option_field(control_state, 'attempt_index', 1);
    if ~is_finite_scalar(attempt_index) || attempt_index < 1
        attempt_index = 1;
    end
    control_state.attempt_index = round(attempt_index) + 1;
    if isstruct(trials)
        control_state.trials = trials;
    end

    next_options = exchange_options;
    next_options.actual_flush_pressure_control_state = control_state;
    next_options.pressure_differential_override_MPa = pressure_MPa;
    next_options.pressure_control_compensation_active = true;
    next_options.pressure_control_compensation_source = source;
    next_options.pressure_control_compensation_pressure_MPa = pressure_MPa;
    next_options.pressure_control_compensation_trigger = char(string(trigger_reason));
    retry.should_retry = true;
    retry.exchange_options = next_options;
    retry.source = source;
    retry.pressure_MPa = pressure_MPa;
end

function [pressure_MPa, source] = select_pressure_control_compensation_pressure( ...
        exchange_options, stage_name, sim_params, trials)
    pressure_MPa = NaN;
    source = '';
    if isstruct(trials) && ~isempty(trials)
        for idx = numel(trials):-1:1
            candidate = get_option_field(trials(idx), 'pressure_differential_MPa', NaN);
            if is_finite_scalar(candidate)
                pressure_MPa = candidate;
                source = 'same_cycle_previous_retry';
                return;
            end
        end
    end

    runtime = get_option_field(exchange_options, 'runtime', struct());
    switch stage_name
        case 'hold_exchange'
            same_stage_fields = {'stage2_converged_pressure_MPa', 'stage2_last_known_good_pressure_MPa'};
            run_stage_fields = {'stage2_run_last_known_good_pressure_MPa'};
            direction_sign = -1.0;
        case 'cooldown_exchange'
            same_stage_fields = {'stage4_converged_pressure_MPa', 'stage4_last_known_good_pressure_MPa'};
            run_stage_fields = {'stage4_run_last_known_good_pressure_MPa'};
            direction_sign = -1.0;
        otherwise
            same_stage_fields = {};
            run_stage_fields = {};
            direction_sign = -1.0;
    end

    for idx = 1:numel(same_stage_fields)
        candidate = get_option_field(runtime, same_stage_fields{idx}, NaN);
        if is_finite_scalar(candidate)
            pressure_MPa = candidate;
            source = 'previous_cycle_same_stage_converged';
            return;
        end
    end

    for idx = 1:numel(run_stage_fields)
        candidate = get_option_field(runtime, run_stage_fields{idx}, NaN);
        if is_finite_scalar(candidate)
            pressure_MPa = candidate;
            source = 'run_recent_stage_converged';
            return;
        end
    end
    generic_stage_name = char(string(get_option_field(runtime, 'run_last_known_good_pressure_stage_name', '')));
    candidate = get_option_field(runtime, 'run_last_known_good_pressure_MPa', NaN);
    if strcmpi(strtrim(generic_stage_name), strtrim(stage_name)) && is_finite_scalar(candidate)
        pressure_MPa = candidate;
        source = 'same_stage_run_recent_stage_converged';
        return;
    end

    candidate = get_option_field(sim_params, 'pressure_differential_MPa_analytic_guess', NaN);
    if is_finite_scalar(candidate)
        pressure_MPa = candidate;
        source = 'analytic_mdot_scaled_pressure_guess';
        return;
    end

    candidate = get_option_field(sim_params, 'pressure_differential_MPa_uncached', NaN);
    if is_finite_scalar(candidate)
        pressure_MPa = candidate;
        source = 'uncached_pressure_guess';
        return;
    end

    reference_pressure = abs(get_option_field(sim_params, 'pressure_control_reference_pressure_MPa', ...
        get_option_field(exchange_options, 'pressure_control_reference_pressure_MPa', 0.1)));
    if ~is_finite_scalar(reference_pressure) || reference_pressure <= 0
        reference_pressure = 0.1;
    end
    pressure_MPa = direction_sign * reference_pressure;
    source = 'hardcoded_reference_pressure';
end

function diverging = detect_pressure_retry_diverging(trials, exchange_options)
    diverging = false;
    if ~isstruct(trials) || numel(trials) < 3
        return;
    end
    min_count = max(3, round(get_option_field(exchange_options, ...
        'actual_flush_pressure_divergence_min_count', 3)));
    if numel(trials) < min_count
        return;
    end
    errors = nan(1, numel(trials));
    for idx = 1:numel(trials)
        err = get_option_field(trials(idx), 'actual_flush_ratio_rel_error', NaN);
        if ~is_finite_scalar(err)
            err = get_option_field(trials(idx), 'actual_flush_ratio_error', NaN);
        end
        errors(idx) = abs(err);
    end
    errors = errors(isfinite(errors));
    if numel(errors) < min_count
        return;
    end
    recent = errors(end - min_count + 1:end);
    min_error = get_option_field(exchange_options, ...
        'actual_flush_pressure_divergence_min_rel_error', 0.05);
    min_improvement = get_option_field(exchange_options, ...
        'actual_flush_pressure_divergence_min_improvement_fraction', 0.05);
    if recent(end) < min_error
        return;
    end
    monotone_bad = all(diff(recent) >= -1.0e-9);
    improvement = (recent(1) - recent(end)) / max(recent(1), eps);
    diverging = monotone_bad || improvement < min_improvement;
end

function ok = is_finite_scalar(value)
    ok = isnumeric(value) && isscalar(value) && isfinite(value);
end

function [next_pressure, pressure_scale] = bracket_next_pressure_from_trials(trials, current_pressure, target_ratio)
    next_pressure = NaN;
    pressure_scale = NaN;
    if ~isstruct(trials) || isempty(trials) || ~isfinite(current_pressure) || ...
            ~isfinite(target_ratio) || target_ratio <= 0
        return;
    end
    pressures = arrayfun(@(t) get_option_field(t, 'pressure_differential_MPa', NaN), trials);
    ratios = arrayfun(@(t) get_option_field(t, 'actual_active_flush_volume_ratio', NaN), trials);
    valid = isfinite(pressures) & abs(pressures) > eps & isfinite(ratios) & ratios > 0;
    if nnz(valid) < 2
        return;
    end
    pressures = pressures(valid);
    ratios = ratios(valid);
    below = ratios < target_ratio;
    above = ratios > target_ratio;
    if ~any(below) || ~any(above)
        return;
    end
    sign_pressure = sign(current_pressure);
    if sign_pressure == 0
        sign_pressure = sign(pressures(end));
    end
    abs_pressures = abs(pressures);
    low_abs = max(abs_pressures(below));
    high_abs = min(abs_pressures(above));
    if ~(isfinite(low_abs) && isfinite(high_abs) && low_abs > 0 && high_abs > 0)
        return;
    end
    if low_abs > high_abs
        tmp = low_abs;
        low_abs = high_abs;
        high_abs = tmp;
    end
    next_abs = sqrt(low_abs * high_abs);
    next_pressure = sign_pressure * next_abs;
    pressure_scale = next_pressure / current_pressure;
end

function text = encode_json_safely(value)
    try
        text = jsonencode(value);
    catch
        text = '';
    end
end

function audit = build_active_flow_audit(simOut, stage_config, sim_params, observability)
    stage_name = char(string(get_option_field(stage_config, 'stage_name', '')));
    dt_s = get_option_field(stage_config, 'stop_time_s', NaN);
    switch stage_name
        case 'hold_exchange'
            inlet_names = {'mass_flow_v1_cold_inlet_kgps'};
            outlet_names = {'mass_flow_v3_sma_to_hot_kgps'};
            inlet_terminal = observability.mass_flow_v1_cold_inlet_kgps;
            outlet_terminal = observability.mass_flow_v3_sma_to_hot_kgps;
            closed_names = {'mass_flow_v4_hot_inlet_kgps', 'mass_flow_v6_sma_to_chip_cold_kgps'};
            closed_terminals = [observability.mass_flow_v4_hot_inlet_kgps, ...
                observability.mass_flow_v6_sma_to_chip_cold_kgps];
        case 'cooldown_exchange'
            inlet_names = {'mass_flow_v4_hot_inlet_kgps'};
            outlet_names = {'mass_flow_v6_sma_to_chip_cold_kgps'};
            inlet_terminal = observability.mass_flow_v4_hot_inlet_kgps;
            outlet_terminal = observability.mass_flow_v6_sma_to_chip_cold_kgps;
            closed_names = {'mass_flow_v1_cold_inlet_kgps', 'mass_flow_v3_sma_to_hot_kgps'};
            closed_terminals = [observability.mass_flow_v1_cold_inlet_kgps, ...
                observability.mass_flow_v3_sma_to_hot_kgps];
        otherwise
            inlet_names = {};
            outlet_names = {};
            inlet_terminal = 0.0;
            outlet_terminal = 0.0;
            closed_names = {};
            closed_terminals = [];
    end

    audit_ignore_initial_s = max(0.0, get_option_field(sim_params, ...
        'actual_flush_audit_ignore_initial_s', 0.0));
    if isfinite(dt_s) && dt_s > 0
        audit_ignore_initial_s = min(audit_ignore_initial_s, max(dt_s - eps, 0.0));
    else
        audit_ignore_initial_s = 0.0;
    end
    audit_window_duration_s = max(dt_s - audit_ignore_initial_s, eps);
    audit_mode = char(string(get_option_field(sim_params, ...
        'actual_flush_audit_mode', 'full_stage_integral')));

    inlet_full = integrate_active_mass_flow_series(simOut, inlet_names, inlet_terminal, dt_s, 0.0);
    outlet_full = integrate_active_mass_flow_series(simOut, outlet_names, outlet_terminal, dt_s, 0.0);
    inlet = integrate_active_mass_flow_series(simOut, inlet_names, inlet_terminal, dt_s, audit_ignore_initial_s);
    outlet = integrate_active_mass_flow_series(simOut, outlet_names, outlet_terminal, dt_s, audit_ignore_initial_s);
    closed_integrals = integrate_closed_branch_set(simOut, closed_names, closed_terminals, dt_s, audit_ignore_initial_s);
    integral_values = [inlet.integral_kg, outlet.integral_kg];
    finite_integrals = integral_values(isfinite(integral_values));
    if isempty(finite_integrals)
        actual_active_mdot_integral_kg = NaN;
    else
        actual_active_mdot_integral_kg = mean(finite_integrals);
    end

    if isfinite(actual_active_mdot_integral_kg) && isfinite(audit_window_duration_s) && audit_window_duration_s > 0
        actual_active_mdot_mean_kgps = actual_active_mdot_integral_kg / audit_window_duration_s;
    else
        actual_active_mdot_mean_kgps = NaN;
    end
    actual_active_flush_volume_m3 = actual_active_mdot_integral_kg / max(sim_params.rho_water, eps);
    actual_active_flush_volume_ratio = actual_active_flush_volume_m3 / max(sim_params.plate_volume_m3, eps);
    actual_flush_ratio_error = actual_active_flush_volume_ratio - sim_params.target_flush_volume_ratio;
    if abs(sim_params.target_flush_volume_ratio) > eps
        actual_flush_ratio_rel_error = actual_flush_ratio_error / sim_params.target_flush_volume_ratio;
    else
        actual_flush_ratio_rel_error = NaN;
    end
    flush_volume_abs_tolerance = get_option_field(sim_params, 'flush_volume_control_abs_tolerance', 0.05);
    flush_volume_rel_tolerance = get_option_field(sim_params, 'flush_volume_control_rel_tolerance', 0.05);
    if isfinite(actual_flush_ratio_error) && isfinite(actual_flush_ratio_rel_error)
        flush_volume_control_ok = abs(actual_flush_ratio_error) <= flush_volume_abs_tolerance || ...
            abs(actual_flush_ratio_rel_error) <= flush_volume_rel_tolerance;
    else
        flush_volume_control_ok = false;
    end

    if isfinite(inlet.integral_kg) && isfinite(outlet.integral_kg)
        integral_diff_kg = abs(inlet.integral_kg - outlet.integral_kg);
    else
        integral_diff_kg = NaN;
    end
    if isempty(finite_integrals)
        integral_ref_kg = NaN;
    else
        integral_ref_kg = max(mean(abs(finite_integrals)), eps);
    end
    if isfinite(integral_diff_kg) && isfinite(integral_ref_kg)
        integral_rel_diff = integral_diff_kg / integral_ref_kg;
    else
        integral_rel_diff = NaN;
    end

    if strcmp(inlet.quality, 'timeseries_integral') && strcmp(outlet.quality, 'timeseries_integral')
        quality = 'timeseries_integral_inlet_outlet_average';
    elseif strcmp(inlet.quality, 'timeseries_integral')
        quality = 'timeseries_integral_inlet_only';
    elseif strcmp(outlet.quality, 'timeseries_integral')
        quality = 'timeseries_integral_outlet_only';
    elseif strcmp(stage_name, 'hold_exchange') || strcmp(stage_name, 'cooldown_exchange')
        quality = 'terminal_approximation';
    else
        quality = 'not_exchange_stage';
    end
    if audit_ignore_initial_s > 0 && (strcmp(stage_name, 'hold_exchange') || strcmp(stage_name, 'cooldown_exchange'))
        quality = [quality, '_post_startup_window'];
    end
    closed_finite = closed_integrals.integral_kg(isfinite(closed_integrals.integral_kg));
    if isempty(closed_finite)
        actual_closed_branch_mass_integral_kg = NaN;
        actual_closed_branch_total_mass_integral_kg = NaN;
    else
        actual_closed_branch_mass_integral_kg = max(closed_finite);
        actual_closed_branch_total_mass_integral_kg = sum(closed_finite);
    end
    actual_closed_branch_flush_volume_m3 = actual_closed_branch_total_mass_integral_kg / max(sim_params.rho_water, eps);
    actual_closed_branch_flush_volume_ratio = actual_closed_branch_flush_volume_m3 / max(sim_params.plate_volume_m3, eps);
    if isfinite(actual_closed_branch_total_mass_integral_kg) && isfinite(dt_s) && dt_s > 0
        actual_closed_branch_mdot_mean_kgps = actual_closed_branch_total_mass_integral_kg / dt_s;
    else
        actual_closed_branch_mdot_mean_kgps = NaN;
    end
    if isfinite(actual_active_mdot_integral_kg) && abs(actual_active_mdot_integral_kg) > eps
        actual_closed_branch_to_active_mass_ratio = actual_closed_branch_total_mass_integral_kg / abs(actual_active_mdot_integral_kg);
    else
        actual_closed_branch_to_active_mass_ratio = NaN;
    end

    audit = struct( ...
        'target_flush_volume_ratio', sim_params.target_flush_volume_ratio, ...
        'target_flush_volume_m3', sim_params.target_flush_volume_m3, ...
        'Q_target_m3ps', sim_params.Q_target_m3ps, ...
        'mdot_target_kgps', sim_params.mdot_target_kgps, ...
        'actual_active_flush_volume_ratio', actual_active_flush_volume_ratio, ...
        'actual_active_flush_volume_m3', actual_active_flush_volume_m3, ...
        'actual_active_mdot_mean_kgps', actual_active_mdot_mean_kgps, ...
        'actual_active_mdot_integral_kg', actual_active_mdot_integral_kg, ...
        'actual_active_flush_volume_ratio_full_stage', ...
            (mean_finite([inlet_full.integral_kg, outlet_full.integral_kg]) / max(sim_params.rho_water, eps)) / max(sim_params.plate_volume_m3, eps), ...
        'actual_active_flush_volume_m3_full_stage', ...
            mean_finite([inlet_full.integral_kg, outlet_full.integral_kg]) / max(sim_params.rho_water, eps), ...
        'actual_active_mdot_integral_kg_full_stage', mean_finite([inlet_full.integral_kg, outlet_full.integral_kg]), ...
        'actual_active_mdot_mean_kgps_full_stage', mean_finite([inlet_full.mean_kgps, outlet_full.mean_kgps]), ...
        'actual_flush_audit_ignore_initial_s', audit_ignore_initial_s, ...
        'actual_flush_audit_window_start_s', audit_ignore_initial_s, ...
        'actual_flush_audit_window_end_s', dt_s, ...
        'actual_flush_audit_window_duration_s', audit_window_duration_s, ...
        'actual_flush_audit_mode', audit_mode, ...
        'actual_flush_ratio_error', actual_flush_ratio_error, ...
        'actual_flush_ratio_rel_error', actual_flush_ratio_rel_error, ...
        'flush_volume_control_ok', flush_volume_control_ok, ...
        'flush_volume_control_abs_tolerance', flush_volume_abs_tolerance, ...
        'flush_volume_control_rel_tolerance', flush_volume_rel_tolerance, ...
        'actual_flow_audit_quality', quality, ...
        'actual_active_inlet_mdot_integral_kg', inlet.integral_kg, ...
        'actual_active_outlet_mdot_integral_kg', outlet.integral_kg, ...
        'actual_active_inlet_mdot_integral_kg_full_stage', inlet_full.integral_kg, ...
        'actual_active_outlet_mdot_integral_kg_full_stage', outlet_full.integral_kg, ...
        'actual_active_inlet_mdot_mean_kgps', inlet.mean_kgps, ...
        'actual_active_outlet_mdot_mean_kgps', outlet.mean_kgps, ...
        'actual_active_inlet_outlet_integral_diff_kg', integral_diff_kg, ...
        'actual_active_inlet_outlet_integral_rel_diff', integral_rel_diff, ...
        'actual_active_inlet_flow_quality', inlet.quality, ...
        'actual_active_outlet_flow_quality', outlet.quality, ...
        'actual_active_inlet_sample_count', inlet.sample_count, ...
        'actual_active_outlet_sample_count', outlet.sample_count, ...
        'actual_closed_branch_mass_integral_kg', actual_closed_branch_mass_integral_kg, ...
        'actual_closed_branch_total_mass_integral_kg', actual_closed_branch_total_mass_integral_kg, ...
        'actual_closed_branch_flush_volume_m3', actual_closed_branch_flush_volume_m3, ...
        'actual_closed_branch_flush_volume_ratio', actual_closed_branch_flush_volume_ratio, ...
        'actual_closed_branch_mdot_mean_kgps', actual_closed_branch_mdot_mean_kgps, ...
        'actual_closed_branch_to_active_mass_ratio', actual_closed_branch_to_active_mass_ratio, ...
        'actual_closed_branch_flow_quality', closed_integrals.quality, ...
        'actual_closed_branch_variable_names', {closed_integrals.variable_names}, ...
        'actual_closed_branch_integral_kg_by_branch', closed_integrals.integral_kg, ...
        'actual_closed_branch_mean_kgps_by_branch', closed_integrals.mean_kgps, ...
        'actual_closed_branch_sample_count_by_branch', closed_integrals.sample_count, ...
        'closed_branch_leakage_heat_upper_bound_J', NaN, ...
        'closed_branch_leakage_temperature_span_K', NaN, ...
        'closed_branch_leakage_to_main_exchange_heat_ratio', NaN, ...
        'closed_branch_leakage_to_fluid_enthalpy_ratio', NaN, ...
        'closed_branch_leakage_to_sma_101_delta_ratio', NaN, ...
        'closed_branch_leakage_to_chip_heat_source_ratio', NaN, ...
        'closed_branch_leakage_controlled_warning', false, ...
        'closed_branch_leakage_classification', 'not_evaluated', ...
        'closed_branch_leakage_heat_ratio_warning_threshold', NaN);
end

function result = integrate_active_mass_flow_series(simOut, variable_names, terminal_signed_mdot, dt_s, ignore_initial_s)
    if nargin < 5 || isempty(ignore_initial_s)
        ignore_initial_s = 0.0;
    end
    result = struct( ...
        'integral_kg', NaN, ...
        'mean_kgps', NaN, ...
        'quality', 'missing_flow_logs', ...
        'sample_count', 0);
    if isempty(variable_names)
        result.integral_kg = 0.0;
        result.mean_kgps = 0.0;
        result.quality = 'not_exchange_stage';
        return;
    end

    [t_m, mdot_raw] = extract_logged_series(simOut, variable_names);
    if numel(t_m) >= 2 && numel(mdot_raw) == numel(t_m)
        t = build_audit_time_vector(t_m(:), dt_s, ignore_initial_s);
        mdot_i = signed_mass_flow_series_with_terminal(t_m, mdot_raw, t, terminal_signed_mdot);
        result.integral_kg = trapz(t, mdot_i);
        if isfinite(dt_s) && dt_s > 0
            result.mean_kgps = result.integral_kg / max(dt_s - max(ignore_initial_s, 0.0), eps);
        else
            result.mean_kgps = result.integral_kg / max(t(end) - t(1), eps);
        end
        result.quality = 'timeseries_integral';
        result.sample_count = numel(t);
        return;
    end

    if isfinite(terminal_signed_mdot) && isfinite(dt_s)
        window_duration_s = max(dt_s - max(ignore_initial_s, 0.0), 0.0);
        result.integral_kg = max(terminal_signed_mdot, 0.0) * window_duration_s;
        result.mean_kgps = max(terminal_signed_mdot, 0.0);
        result.quality = 'terminal_approximation';
        result.sample_count = 1;
    end
end

function result = integrate_closed_branch_set(simOut, variable_names, terminal_signed_mdot, dt_s, ignore_initial_s)
    if nargin < 5 || isempty(ignore_initial_s)
        ignore_initial_s = 0.0;
    end
    branch_count = numel(variable_names);
    result = struct( ...
        'variable_names', {variable_names}, ...
        'integral_kg', NaN(1, branch_count), ...
        'mean_kgps', NaN(1, branch_count), ...
        'sample_count', zeros(1, branch_count), ...
        'quality_by_branch', {repmat({''}, 1, branch_count)}, ...
        'quality', 'not_exchange_stage');
    if branch_count == 0
        result.integral_kg = 0.0;
        result.mean_kgps = 0.0;
        result.sample_count = 0;
        result.quality_by_branch = {'not_exchange_stage'};
        return;
    end
    for idx = 1:branch_count
        branch = integrate_abs_mass_flow_series(simOut, variable_names(idx), terminal_signed_mdot(idx), dt_s, ignore_initial_s);
        result.integral_kg(idx) = branch.integral_kg;
        result.mean_kgps(idx) = branch.mean_kgps;
        result.sample_count(idx) = branch.sample_count;
        result.quality_by_branch{idx} = branch.quality;
    end
    qualities = result.quality_by_branch;
    if all(strcmp(qualities, 'timeseries_integral'))
        result.quality = 'timeseries_integral_all_closed_branches';
    elseif any(strcmp(qualities, 'timeseries_integral'))
        result.quality = 'timeseries_integral_partial_closed_branches';
    elseif any(strcmp(qualities, 'terminal_approximation'))
        result.quality = 'terminal_approximation';
    else
        result.quality = 'missing_flow_logs';
    end
end

function result = integrate_abs_mass_flow_series(simOut, variable_names, terminal_signed_mdot, dt_s, ignore_initial_s)
    if nargin < 5 || isempty(ignore_initial_s)
        ignore_initial_s = 0.0;
    end
    result = struct( ...
        'integral_kg', NaN, ...
        'mean_kgps', NaN, ...
        'quality', 'missing_flow_logs', ...
        'sample_count', 0);
    [t_m, mdot_raw] = extract_logged_series(simOut, variable_names);
    if numel(t_m) >= 2 && numel(mdot_raw) == numel(t_m)
        t = build_audit_time_vector(t_m(:), dt_s, ignore_initial_s);
        mdot_i = abs_signed_mass_flow_series_with_terminal(t_m, mdot_raw, t, terminal_signed_mdot);
        result.integral_kg = trapz(t, mdot_i);
        if isfinite(dt_s) && dt_s > 0
            result.mean_kgps = result.integral_kg / max(dt_s - max(ignore_initial_s, 0.0), eps);
        else
            result.mean_kgps = result.integral_kg / max(t(end) - t(1), eps);
        end
        result.quality = 'timeseries_integral';
        result.sample_count = numel(t);
        return;
    end
    if isfinite(terminal_signed_mdot) && isfinite(dt_s)
        window_duration_s = max(dt_s - max(ignore_initial_s, 0.0), 0.0);
        result.integral_kg = abs(terminal_signed_mdot) * window_duration_s;
        result.mean_kgps = abs(terminal_signed_mdot);
        result.quality = 'terminal_approximation';
        result.sample_count = 1;
    end
end

function t = build_audit_time_vector(t_raw, dt_s, ignore_initial_s)
    t_all = unique(t_raw(:));
    if isempty(t_all)
        t = t_all;
        return;
    end
    if ~isfinite(dt_s) || dt_s <= 0
        t_end = max(t_all);
    else
        t_end = dt_s;
    end
    t_start = max(0.0, min(max(ignore_initial_s, 0.0), max(t_end - eps, 0.0)));
    t = t_all(t_all >= t_start & t_all <= t_end);
    if isempty(t) || abs(t(1) - t_start) > 1.0e-12
        t = [t_start; t(:)];
    end
    if abs(t(end) - t_end) > 1.0e-12
        t = [t(:); t_end];
    end
    t = unique(t(:));
end

function value = mean_finite(values)
    finite_values = values(isfinite(values));
    if isempty(finite_values)
        value = NaN;
    else
        value = mean(finite_values);
    end
end

function mdot_i = abs_signed_mass_flow_series_with_terminal(t_m, mdot_raw, t_target, mdot_terminal)
    raw_terminal = mdot_raw(end);
    if isfinite(mdot_terminal) && isfinite(raw_terminal) && abs(raw_terminal) > 1.0e-12
        mdot_signed = mdot_raw(:) * (mdot_terminal / raw_terminal);
    else
        mdot_signed = mdot_raw(:);
    end
    mdot_i = abs(interp_series(t_m, mdot_signed, t_target));
end

function values_i = interp_series(t, values, t_target)
    [t_unique, unique_idx] = unique(t(:));
    values = values(:);
    values = values(unique_idx);
    values_i = interp1(t_unique, values, t_target, 'linear', 'extrap');
end

function mdot_i = signed_mass_flow_series(t_m, mdot_raw, t_target, observability)
    mdot_terminal = get_option_field(observability, 'sma_inlet_branch_mass_flow_kgps', NaN);
    mdot_i = signed_mass_flow_series_with_terminal(t_m, mdot_raw, t_target, mdot_terminal);
end

function mdot_i = signed_mass_flow_series_with_terminal(t_m, mdot_raw, t_target, mdot_terminal)
    raw_terminal = mdot_raw(end);
    if isfinite(mdot_terminal) && isfinite(raw_terminal) && abs(raw_terminal) > 1.0e-12
        mdot_signed = mdot_raw(:) * (mdot_terminal / raw_terminal);
    else
        mdot_signed = -mdot_raw(:);
    end
    mdot_i = max(interp_series(t_m, mdot_signed, t_target), 0.0);
end

function radial_C = build_radial_heat_capacity_vector(node_count, strip_geometry)
    if isfield(strip_geometry, 'geometry_kind') && strcmp(strip_geometry.geometry_kind, 'axial_21_se')
        radial_C = repmat( ...
            strip_geometry.total_mass_kg * strip_geometry.default_cp_J_per_kgK / max(node_count, 1), ...
            node_count, 1);
        return;
    end
    if node_count < 2
        radial_C = strip_geometry.total_mass_kg * strip_geometry.default_cp_J_per_kgK;
        return;
    end
    R = strip_geometry.radius_m;
    r_nodes = linspace(0.0, R, node_count).';
    edges = zeros(node_count + 1, 1);
    edges(1) = 0.0;
    edges(end) = R;
    edges(2:end-1) = 0.5 * (r_nodes(1:end-1) + r_nodes(2:end));
    ring_area = pi * (edges(2:end).^2 - edges(1:end-1).^2);
    ring_area = ring_area / max(sum(ring_area), eps);
    radial_C = strip_geometry.total_mass_kg * strip_geometry.default_cp_J_per_kgK * ring_area;
end

