function value = compute_nonmirror_max_abs(T_x)
    T_x = T_x(:);
    if isempty(T_x)
        value = NaN;
        return;
    end
    value = max(abs(T_x - flipud(T_x)));
end

function value = compute_endpoint_delta(T_x)
    T_x = T_x(:);
    if numel(T_x) < 2
        value = NaN;
        return;
    end
    value = T_x(end) - T_x(1);
end

function [var_name, expected_count] = resolve_raw_temperature_log_contract(exchange_backend_kind, sim_params)
    switch exchange_backend_kind
        case 'simulink_axial_21'
            var_name = get_option_field(sim_params, ...
                'solver_internal_temperature_workspace_var', 'Tx21_internal');
            expected_count = get_option_field(sim_params, 'solver_internal_21_strip_count', ...
                get_option_field(sim_params, 'solver_internal_thermal_node_count', 21));
        otherwise
            var_name = 'Tx51';
            expected_count = numel(sim_params.solver_T_init_51);
    end
end

function target = inherit_field(target, source, field_name)
    if (~isstruct(target) || ~isfield(target, field_name) || isempty(target.(field_name))) && ...
            isstruct(source) && isfield(source, field_name) && ~isempty(source.(field_name))
        if ~isstruct(target)
            target = struct();
        end
        target.(field_name) = source.(field_name);
    end
end

function activate_release_path()
    this_dir = fileparts(mfilename('fullpath'));
    addpath(this_dir, '-begin');
    rehash;
end

