function delta = compute_temperature_difference(T_a, T_b)
    if ~isvector(T_a) || ~isvector(T_b)
        delta = NaN;
        return;
    end
    T_a = T_a(:);
    T_b = T_b(:);
    if numel(T_a) ~= numel(T_b) || isempty(T_a)
        delta = NaN;
        return;
    end
    delta = max(abs(T_a - T_b));
end

