function target = merge_probe_timeseries_fields(target, source)
    if ~isstruct(source) || isempty(source)
        return;
    end
    names = probe_timeseries_field_names();
    for idx = 1:numel(names)
        name = names{idx};
        if isfield(source, name)
            target.(name) = source.(name);
        end
    end
end

function merged = merge_flat_struct(base_struct, extra_struct)
    merged = base_struct;
    if ~isstruct(extra_struct) || isempty(extra_struct)
        return;
    end
    names = fieldnames(extra_struct);
    for idx = 1:numel(names)
        merged.(names{idx}) = extra_struct.(names{idx});
    end
end

function diagnostics = save_simulink_failure_diagnostics(ME, state_std, stage_config, sim_params, ...
        strip_geometry, T_r_in, T_x_in_101, runtime)
    diagnostics_dir = fullfile(get_option_field(runtime, 'outputs_dir', pwd), 'failure_diagnostics');
    ensure_local_dir(diagnostics_dir);

    cycle_index = get_option_field(runtime, 'cycle_index', 0);
    stage_index = get_option_field(runtime, 'stage_index', 0);
    stage_name = char(string(get_option_field(stage_config, 'stage_name', 'unknown_stage')));
    base_name = sprintf('failed_cycle%03d_stage%02d_%s', ...
        cycle_index, stage_index, sanitize_file_token(stage_name));
    snapshot_mat_path = fullfile(diagnostics_dir, [base_name, '_input_snapshot.mat']);
    error_txt_path = fullfile(diagnostics_dir, [base_name, '_error.txt']);

    error_info = exception_to_struct(ME);
    runtime_side_state = struct( ...
        'hot_sink_temp_current', get_option_field(runtime, 'hot_sink_temp_current', NaN), ...
        'cold_sink_temp_current', get_option_field(runtime, 'cold_sink_temp_current', NaN), ...
        'chip_temp_current', get_option_field(runtime, 'chip_temp_current', NaN), ...
        'hot_buffer_temp_current', get_option_field(runtime, 'hot_buffer_temp_current', NaN), ...
        'cold_buffer_temp_current', get_option_field(runtime, 'cold_buffer_temp_current', NaN), ...
        'last_stage_name', get_option_field(runtime, 'last_stage_name', ''), ...
        'last_checkpoint_path', get_option_field(runtime, 'last_checkpoint_path', ''));
    input_stats = struct( ...
        'T_r_in', vector_stats(T_r_in), ...
        'T_x_in_101', vector_stats(T_x_in_101), ...
        'solver_T_init_51', vector_stats(get_option_field(sim_params, 'solver_T_init_51', [])));

    snapshot = struct( ...
        'created_at', char(datetime('now', 'Format', 'yyyy-MM-dd HH:mm:ss')), ...
        'cycle_index', cycle_index, ...
        'stage_index', stage_index, ...
        'stage_name', stage_name, ...
        'error', error_info, ...
        'state_in', state_std, ...
        'stage_config', stage_config, ...
        'sim_params', sim_params, ...
        'strip_geometry', strip_geometry, ...
        'T_r_in', T_r_in, ...
        'T_x_in_101', T_x_in_101, ...
        'input_stats', input_stats, ...
        'runtime_side_state', runtime_side_state, ...
        'pressure_differential_MPa', get_option_field(sim_params, 'pressure_differential_MPa', NaN), ...
        'target_flush_volume_ratio', get_option_field(sim_params, 'target_flush_volume_ratio', NaN), ...
        'Q_target_m3ps', get_option_field(sim_params, 'Q_target_m3ps', NaN), ...
        'mdot_target_kgps', get_option_field(sim_params, 'mdot_target_kgps', NaN), ...
        'h_water', get_option_field(sim_params, 'h_water', NaN), ...
        'h_water_uncapped', get_option_field(sim_params, 'h_water_uncapped', NaN), ...
        'h_conv_W_per_m2K', get_option_field(sim_params, 'h_conv_W_per_m2K', NaN), ...
        'U_eff_W_per_m2K', get_option_field(sim_params, 'U_eff_W_per_m2K', NaN), ...
        'UA_sma_W_per_K', get_option_field(sim_params, 'UA_sma_W_per_K', NaN), ...
        'chip_fluid_G_model', get_option_field(sim_params, 'chip_fluid_G_model', ''), ...
        'chip_fluid_G_effective_W_per_K', get_option_field(sim_params, 'chip_fluid_G_effective_W_per_K', NaN), ...
        'chip_fluid_G_uncapped_W_per_K', get_option_field(sim_params, 'chip_fluid_G_uncapped_W_per_K', NaN), ...
        'chip_Re', get_option_field(sim_params, 'chip_Re', NaN), ...
        'chip_Nu', get_option_field(sim_params, 'chip_Nu', NaN), ...
        'chip_h_conv_W_per_m2K', get_option_field(sim_params, 'chip_h_conv_W_per_m2K', NaN), ...
        'chip_R_total_K_per_W', get_option_field(sim_params, 'chip_R_total_K_per_W', NaN), ...
        'correlation_name', get_option_field(sim_params, 'correlation_name', ''), ...
        'flow_regime', get_option_field(sim_params, 'flow_regime', ''), ...
        'h_water_cap_active', get_option_field(sim_params, 'h_water_cap_active', false), ...
        'fluid_buffer_reference_ratio', get_option_field(sim_params, 'fluid_buffer_reference_ratio', NaN), ...
        'fluid_buffer_volume_m3', get_option_field(sim_params, 'fluid_buffer_volume_m3', NaN), ...
        'fluid_buffer_tank_level_m', get_option_field(sim_params, 'fluid_buffer_tank_level_m', NaN), ...
        'L_valve_target', get_option_field(sim_params, 'L_valve_target', []), ...
        'L_valve_initial', get_option_field(sim_params, 'L_valve_initial', []), ...
        'L_valve_command_time_s', get_option_field(sim_params, 'L_valve_command_time_s', []), ...
        'L_valve_command_values', get_option_field(sim_params, 'L_valve_command_values', []), ...
        'exchange_startup_smoothing_enabled', get_option_field(sim_params, 'exchange_startup_smoothing_enabled', false), ...
        'exchange_startup_ramp_s', get_option_field(sim_params, 'exchange_startup_ramp_s', 0.0), ...
        'exchange_startup_profile', get_option_field(sim_params, 'exchange_startup_profile', ''), ...
        'startup_smoothing_used', get_option_field(sim_params, 'startup_smoothing_used', false), ...
        'startup_smoothing_reason', get_option_field(sim_params, 'startup_smoothing_reason', ''), ...
        'pressure_startup_smoothing_enabled', get_option_field(sim_params, 'pressure_startup_smoothing_enabled', false), ...
        'pressure_startup_smoothing_reason', get_option_field(sim_params, 'pressure_startup_smoothing_reason', ''));
    save(snapshot_mat_path, 'snapshot', '-v7.3');

    write_text_utf8(error_txt_path, format_failure_text(snapshot));
    diagnostics = struct( ...
        'snapshot_mat_path', snapshot_mat_path, ...
        'error_txt_path', error_txt_path, ...
        'failure_diagnostics_dir', diagnostics_dir);
end

function stats = vector_stats(values)
    values = double(values(:));
    finite_values = values(isfinite(values));
    stats = struct( ...
        'count', numel(values), ...
        'finite_count', numel(finite_values), ...
        'all_finite', numel(finite_values) == numel(values), ...
        'min', NaN, ...
        'max', NaN, ...
        'mean', NaN);
    if ~isempty(finite_values)
        stats.min = min(finite_values);
        stats.max = max(finite_values);
        stats.mean = mean(finite_values);
    end
end

function info = exception_to_struct(ME)
    stack = ME.stack;
    info = struct( ...
        'identifier', ME.identifier, ...
        'message', ME.message, ...
        'stack', stack);
    if ~isempty(ME.cause)
        causes = cell(1, numel(ME.cause));
        for idx = 1:numel(ME.cause)
            causes{idx} = exception_to_struct(ME.cause{idx});
        end
        info.cause = causes;
    else
        info.cause = {};
    end
end

function text = format_failure_text(snapshot)
    e = snapshot.error;
    lines = { ...
        sprintf('created_at: %s', snapshot.created_at), ...
        sprintf('cycle_index: %d', snapshot.cycle_index), ...
        sprintf('stage_index: %d', snapshot.stage_index), ...
        sprintf('stage_name: %s', snapshot.stage_name), ...
        sprintf('identifier: %s', e.identifier), ...
        sprintf('message: %s', e.message), ...
        sprintf('pressure_differential_MPa: %.15g', snapshot.pressure_differential_MPa), ...
        sprintf('target_flush_volume_ratio: %.15g', snapshot.target_flush_volume_ratio), ...
        sprintf('Q_target_m3ps: %.15g', snapshot.Q_target_m3ps), ...
        sprintf('mdot_target_kgps: %.15g', snapshot.mdot_target_kgps), ...
        sprintf('h_water: %.15g', snapshot.h_water), ...
        sprintf('h_water_uncapped: %.15g', snapshot.h_water_uncapped), ...
        sprintf('h_conv_W_per_m2K: %.15g', snapshot.h_conv_W_per_m2K), ...
        sprintf('U_eff_W_per_m2K: %.15g', snapshot.U_eff_W_per_m2K), ...
        sprintf('UA_sma_W_per_K: %.15g', snapshot.UA_sma_W_per_K), ...
        sprintf('correlation_name: %s', snapshot.correlation_name), ...
        sprintf('flow_regime: %s', snapshot.flow_regime), ...
        sprintf('h_water_cap_active: %d', logical(snapshot.h_water_cap_active)), ...
        sprintf('fluid_buffer_reference_ratio: %.15g', snapshot.fluid_buffer_reference_ratio), ...
        sprintf('fluid_buffer_volume_m3: %.15g', snapshot.fluid_buffer_volume_m3), ...
        sprintf('fluid_buffer_tank_level_m: %.15g', snapshot.fluid_buffer_tank_level_m), ...
        sprintf('exchange_startup_smoothing_enabled: %d', logical(snapshot.exchange_startup_smoothing_enabled)), ...
        sprintf('exchange_startup_ramp_s: %.15g', snapshot.exchange_startup_ramp_s), ...
        sprintf('exchange_startup_profile: %s', snapshot.exchange_startup_profile), ...
        sprintf('startup_smoothing_used: %d', logical(snapshot.startup_smoothing_used)), ...
        sprintf('startup_smoothing_reason: %s', snapshot.startup_smoothing_reason), ...
        sprintf('pressure_startup_smoothing_enabled: %d', logical(snapshot.pressure_startup_smoothing_enabled)), ...
        sprintf('pressure_startup_smoothing_reason: %s', snapshot.pressure_startup_smoothing_reason), ...
        sprintf('T_r_in_count: %d finite: %d min: %.15g max: %.15g mean: %.15g', ...
            snapshot.input_stats.T_r_in.count, snapshot.input_stats.T_r_in.finite_count, ...
            snapshot.input_stats.T_r_in.min, snapshot.input_stats.T_r_in.max, ...
            snapshot.input_stats.T_r_in.mean), ...
        sprintf('T_x_in_101_count: %d finite: %d min: %.15g max: %.15g mean: %.15g', ...
            snapshot.input_stats.T_x_in_101.count, snapshot.input_stats.T_x_in_101.finite_count, ...
            snapshot.input_stats.T_x_in_101.min, snapshot.input_stats.T_x_in_101.max, ...
            snapshot.input_stats.T_x_in_101.mean), ...
        'stack:'};
    for idx = 1:numel(e.stack)
        lines{end + 1} = sprintf('  %s:%d %s', e.stack(idx).file, e.stack(idx).line, e.stack(idx).name); %#ok<AGROW>
    end
    text = strjoin(lines, newline);
end

function write_text_utf8(path_value, text)
    fid = fopen(path_value, 'w', 'n', 'UTF-8');
    if fid < 0
        error('Run_Simulink_Exchange_Hook:FailureTextOpenFailed', ...
            'Could not write failure text file: %s', path_value);
    end
    cleaner = onCleanup(@() fclose(fid));
    fprintf(fid, '%s', text);
    clear cleaner
end

function ensure_local_dir(dir_path)
    if ~exist(dir_path, 'dir')
        mkdir(dir_path);
    end
end

function out = ternary_string(condition, true_value, false_value)
    if logical(condition)
        out = true_value;
    else
        out = false_value;
    end
end

function token = sanitize_file_token(text)
    token = regexprep(char(string(text)), '[^a-zA-Z0-9_\-]+', '_');
    if isempty(token)
        token = 'stage';
    end
end
